insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (0, 'gma', 'Guitar Orientation', 'Meet the electric guitar, set it up, hold it, tune it, and learn to read tab, chord diagrams and rhythm.', 'You can hold, tune, understand and operate an electric guitar.', 0) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (1, 'gma', 'First Notes & Fundamental Technique', 'Clean fretting, alternate picking, basic timing, open chords, power chords and your first riffs.', 'You can play basic melodies, riffs and chords with reasonable timing and clean technique.', 1) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (2, 'gma', 'The Guitar Fretboard', 'The musical alphabet, half and whole steps, every note on the neck and octave shapes.', 'You can locate notes across the fretboard instead of relying only on shapes.', 2) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (3, 'gma', 'Music Theory Foundations', 'Intervals, the major scale, keys, the circle of fifths, relative minor, triads and diatonic harmony.', 'You understand the building blocks of Western music and can apply them on the guitar.', 3) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (4, 'gma', 'Rhythm & Rhythm Guitar', 'Tempo, time signatures, subdivisions, syncopation, strumming and metal rhythm technique.', 'You can count and play rhythms accurately with a metronome or drummer.', 4) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (5, 'gma', 'The Pentatonic System & Blues', 'Pentatonic positions, the blues scale, bends, vibrato, legato and blues improvisation.', 'You can improvise simple, musical solos instead of just running scale shapes.', 5) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (6, 'gma', 'The Complete Scale System', 'Pillitiere''s rule-based 3NPS system, CAGED, minor scales, symmetrical scales and full-neck movement.', 'You can build any diatonic scale anywhere on the neck from understanding, not memorised diagrams.', 6) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (7, 'gma', 'Modes & Advanced Diatonic Theory', 'All seven modes, their characteristic notes, modes of harmonic and melodic minor, modal interchange.', 'You can hear, play and improvise with each mode in context.', 7) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (8, 'gma', 'Chords, Harmony & Chord–Scale Relationships', 'Barre chords, sevenths, inversions, extensions, arpeggios, functional harmony and chord–scale theory.', 'You can create solos that follow the harmony.', 8) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (9, 'gma', 'Shredding & Advanced Lead Technique', 'Picking systems, speed development, legato, sweeping, tapping, skipping, hybrid picking and expressive techniques.', 'You have the physical skills for advanced rock and metal lead guitar, without sacrificing tone or timing.', 9) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (10, 'gma', 'Improvisation Mastery', 'Motifs, targeting, chromaticism, rhythm and space, tension and resolution across styles.', 'You can improvise coherent solos over static chords and changing progressions.', 10) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
insert into public.levels (id, course_id, title, summary, outcome, sort_order) values (11, 'gma', 'Jamming & Real-World Application', 'Finding keys, hearing changes, playing with a rhythm section, song structure and performance.', 'You can join a jam or band and contribute confidently.', 11) on conflict (id) do update set title = excluded.title, summary = excluded.summary, outcome = excluded.outcome;
