insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l0-anatomy', 'm0-instrument', 0, 'Anatomy of the electric guitar', 15, array['Name every major part of an electric guitar', 'Explain what pickups, the selector switch and the volume/tone knobs do', 'Know which parts affect tuning and playability']::text[], array[]::text[], array['theory']::text[], '[{"book":"A","section":"Getting Started: parts of the guitar"},{"book":"P","note":"Electric-specific hardware: pickups, bridges, electronics"}]'::jsonb, '{"quizPass":0.75,"criteria":["Score 75% or more on the mastery check.","Name the parts of your own guitar from memory."]}'::jsonb, 0) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l0-anatomy', '{"id":"l0-anatomy","level":0,"module":"m0-instrument","title":"Anatomy of the electric guitar","minutes":15,"objectives":["Name every major part of an electric guitar","Explain what pickups, the selector switch and the volume/tone knobs do","Know which parts affect tuning and playability"],"prerequisites":[],"categories":["theory"],"sources":[{"book":"A","section":"Getting Started: parts of the guitar"},{"book":"P","note":"Electric-specific hardware: pickups, bridges, electronics"}],"why":"You will hear these names in every lesson, every video and every guitar shop. Knowing what each part does also tells you which knob to turn when the guitar sounds wrong, and which parts to leave alone.","explanation":[{"type":"p","text":"An electric guitar has three zones. The headstock holds the tuners (machine heads), which change string tension and therefore pitch. The neck carries the fretboard: a strip of wood with metal frets hammered across it. The body holds the electronics and the bridge."},{"type":"p","text":"Strings run from the tuners, over the nut (a slotted strip at the top of the fretboard), along the neck, over the pickups, and end at the bridge. The vibrating length between nut and bridge saddles is the scale length; pressing a string behind a fret shortens that length and raises the pitch."},{"type":"p","text":"Unlike an acoustic guitar, a solid electric guitar is almost silent on its own. Pickups (magnets wrapped in thousands of turns of fine wire) sense the steel strings vibrating and turn that motion into a tiny electrical signal. Single-coil pickups sound bright and glassy; humbuckers use two coils wired to cancel hum and sound thicker and louder, which suits overdrive."},{"type":"table","head":["Part","What it does"],"rows":[["Tuners","Raise or lower each string''s pitch"],["Nut","Spaces the strings and sets their height at the headstock end"],["Frets","Metal bars; each one is one semitone higher than the last"],["Inlays","Position markers (usually frets 3, 5, 7, 9, 12, 15 …)"],["Pickups","Convert string vibration to an electrical signal"],["Selector switch","Chooses neck, bridge or combined pickups"],["Volume / tone knobs","Set output level and roll off treble"],["Bridge & saddles","Anchor the strings; saddles set string height and intonation"],["Tremolo arm (if fitted)","Lowers (sometimes raises) the pitch of all strings"],["Output jack","Where the cable plugs in"]]},{"type":"callout","tone":"theory","text":"The neck pickup sits where the strings swing widely, giving a warm, round tone. The bridge pickup sits near the fixed end where the motion is small and complex, giving a bright, cutting tone."}],"guitar":[{"type":"p","text":"Pick up your guitar and find each part from the table. Then plug in (or imagine plugging in) and flip the selector switch while playing an open string: neck position for warm rhythm and smooth leads, bridge position for biting riffs and solos, middle positions for mixed tones."},{"type":"callout","tone":"tip","text":"Turn the tone knob down to about 3 on the neck pickup for a classic \"woman tone\" lead sound; turn it fully up for clarity."}],"exercise":{"title":"Guided tour","steps":["Point to and name: headstock, tuners, nut, frets, inlays, body, pickups, selector, volume, tone, bridge, output jack.","Play the open low E string with the selector in each position and describe the change in one word.","Roll the tone knob from 10 to 0 while the string rings and listen to the treble disappear."]},"mistakes":["Confusing the nut with the bridge saddles: the nut is at the headstock end.","Turning tuners to fix a bad tone: tuners only change pitch; tone comes from pickups, knobs and the amp.","Leaving the volume knob at 0 and assuming the amp is broken."],"selfCheck":["I can name ten parts of the guitar without looking.","I can explain the sound difference between neck and bridge pickups."],"realWorld":"When a band says \"switch to the neck pickup for the solo\" or a tech says \"your saddles need adjusting,\" you will know exactly what they mean.","summary":["Headstock, neck and body each have a job.","Frets are semitones; the nut and saddles define the vibrating length.","Pickups and electronics shape the electric sound."],"next":"l0-signal-chain","mastery":{"quizPass":0.75,"criteria":["Score 75% or more on the mastery check.","Name the parts of your own guitar from memory."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0a-1', 'l0-anatomy', 'What do the pickups do?', '["Hold the strings at the bridge","Convert string vibration into an electrical signal","Change the pitch of each string","Make the guitar louder acoustically"]'::jsonb, 1, 'Pickups are magnets and coils that sense string motion and output an electrical signal for the amplifier.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0a-2', 'l0-anatomy', 'Which pickup gives the warmest, roundest tone?', '["Bridge pickup","Neck pickup","Both are identical","Whichever is a humbucker"]'::jsonb, 1, 'Near the neck the string swings widely, producing a stronger fundamental and fewer harsh overtones.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0a-3', 'l0-anatomy', 'Moving one fret toward the body raises the pitch by…', '["A whole step","An octave","A semitone (half step)","Nothing; frets only mark positions"]'::jsonb, 2, 'Each fret is one semitone. Twelve frets make an octave.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0a-4', 'l0-anatomy', 'A humbucker differs from a single-coil pickup because it…', '["Has two coils that cancel hum","Only works with nylon strings","Is always in the neck position","Has no magnets"]'::jsonb, 0, 'Two coils wired out of phase cancel electrical hum and produce a thicker, louder signal.', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l0-signal-chain', 'm0-instrument', 0, 'Amplifiers, cables and the signal chain', 15, array['Connect a guitar to an amplifier correctly', 'Understand clean, overdrive and distortion', 'Set a safe starting amp tone']::text[], array['l0-anatomy']::text[], array['theory']::text[], '[{"book":"P","note":"Electric guitar amplification and accessories"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3 on the mastery check.","Set up a clean and an overdriven tone safely."]}'::jsonb, 1) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l0-signal-chain', '{"id":"l0-signal-chain","level":0,"module":"m0-instrument","title":"Amplifiers, cables and the signal chain","minutes":15,"objectives":["Connect a guitar to an amplifier correctly","Understand clean, overdrive and distortion","Set a safe starting amp tone"],"prerequisites":["l0-anatomy"],"categories":["theory"],"sources":[{"book":"P","note":"Electric guitar amplification and accessories"}],"why":"The amplifier is half of the electric guitar''s sound. A good basic setup avoids hum, protects your ears and speakers, and makes practice sound inspiring instead of harsh.","explanation":[{"type":"p","text":"The signal chain is the path of your sound: guitar → cable → (optional effects pedals) → amplifier input → preamp (gain and EQ) → power amp → speaker. Headphone amps, multi-effects units and audio interfaces with amp-simulator software follow the same logic in one box."},{"type":"p","text":"Gain (or drive) controls how hard the preamp is pushed. Low gain stays clean; more gain compresses and clips the signal, first into crunchy overdrive, then thick distortion. Master volume sets how loud the result is. Bass, middle and treble controls shape the EQ."},{"type":"list","items":["Essential accessories: a shielded instrument cable (3–6 m), picks, a clip-on or app tuner (this app has one), spare strings, a strap, a gig bag or case, and a metronome (also built in).","Optional: headphones or a headphone amp for quiet practice, a capo, a string winder, and a small set of hex keys and screwdrivers for adjustments."]},{"type":"callout","tone":"warning","text":"Turn the amp volume to zero before plugging or unplugging a cable. Plugging in with the volume up produces a loud pop that can damage speakers and ears."}],"guitar":[{"type":"list","items":["Amp volume to 0, power on.","Plug the cable into the guitar, then into the amp input.","Guitar volume to 10, tone to 10.","Amp: gain 3, bass 5, middle 5, treble 5, master volume up slowly to a comfortable level.","Strum an open chord. Raise gain to 6–7 and hear the overdrive; return to 3 for clean."],"ordered":true},{"type":"callout","tone":"tip","text":"Practise at a moderate volume. If your ears ring afterwards, it was too loud."}],"exercise":{"title":"Dial in three tones","steps":["Clean: gain 2–3, all EQ at 5.","Crunch: gain 5–6, middle 6.","Lead: gain 7–8, bass 5, middle 7, treble 6. Save a phone photo of each setting."]},"mistakes":["Too much gain while learning: it hides sloppy technique.","Treble on 10: harsh and fatiguing.","Coiling cables tightly around the elbow, which breaks the inner wires."],"selfCheck":["I can connect and power up without a pop.","I can dial in clean, crunch and lead tones."],"realWorld":"At a rehearsal you will plug into an unfamiliar amp. Starting from \"gain 3, EQ at noon, volume up slowly\" gets you a usable sound in seconds.","summary":["Guitar → cable → pedals → amp → speaker.","Gain shapes distortion; master volume sets loudness.","Volume to zero before plugging in."],"next":"l0-posture","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3 on the mastery check.","Set up a clean and an overdriven tone safely."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0s-1', 'l0-signal-chain', 'What is the correct order of the basic signal chain?', '["Amp → cable → guitar","Guitar → cable → pedals → amp → speaker","Speaker → amp → guitar","Pedals → guitar → amp"]'::jsonb, 1, 'Sound starts at the guitar and travels through the cable and any pedals into the amp and out of the speaker.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0s-2', 'l0-signal-chain', 'Which control mainly decides clean versus distorted?', '["Treble","Master volume","Gain / drive","Presence"]'::jsonb, 2, 'Gain sets how hard the preamp is driven; more gain means more clipping.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0s-3', 'l0-signal-chain', 'Before plugging in a cable you should…', '["Turn the amp volume to zero","Turn the gain to 10","Unplug the speaker","Tune the guitar"]'::jsonb, 0, 'Volume at zero prevents a loud, potentially damaging pop.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l0-posture', 'm0-setup', 0, 'Posture and hand positions', 20, array['Sit and stand with the guitar in a relaxed, repeatable position', 'Position the fretting hand: thumb behind the neck, arched fingers, fingertips', 'Position the picking hand near the pickups']::text[], array[]::text[], array['technique']::text[], '[{"book":"A","section":"Holding the guitar; left- and right-hand position"},{"book":"P","note":"Ergonomics and tension management"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Play one-finger-per-fret on all six strings at 60 bpm without buzzing."]}'::jsonb, 2) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l0-posture', '{"id":"l0-posture","level":0,"module":"m0-setup","title":"Posture and hand positions","minutes":20,"objectives":["Sit and stand with the guitar in a relaxed, repeatable position","Position the fretting hand: thumb behind the neck, arched fingers, fingertips","Position the picking hand near the pickups"],"prerequisites":[],"categories":["technique"],"sources":[{"book":"A","section":"Holding the guitar; left- and right-hand position"},{"book":"P","note":"Ergonomics and tension management"}],"why":"Every technique you will ever learn is built on posture. Good habits now prevent pain and plateaus later; bad habits become very hard to unlearn once you are fast.","explanation":[{"type":"p","text":"Sitting: use a chair without arms, feet flat. The guitar''s waist rests on your right leg (left leg if you play left-handed). The neck points slightly upward. Your back stays straight and your shoulders relaxed; bring the guitar to you rather than hunching over it."},{"type":"p","text":"Standing: adjust the strap so the guitar sits at roughly the same height as when seated. Very low \"rock star\" positions bend the fretting wrist sharply and make many techniques harder."},{"type":"p","text":"Fretting hand: fingers are numbered 1 (index) to 4 (pinky). Your thumb rests on the back of the neck, roughly behind the middle finger. Curve your fingers so they come down on their tips, just behind the fret wire, not on top of it. Keep the palm off the neck, leaving a small gap."},{"type":"p","text":"Picking hand: your forearm rests on the upper edge of the body. The hand floats over the strings between the neck and bridge pickups. Some players lightly anchor the palm edge on the bridge for stability, which is fine as long as it does not press hard."},{"type":"callout","tone":"warning","text":"Tension is the enemy. Every few minutes, check: shoulders down? jaw loose? thumb not squeezing? Squeeze only as hard as needed to stop buzzing."}],"guitar":[{"type":"p","text":"Place finger 1 on the 1st fret of the high E string, finger 2 on the 2nd fret, finger 3 on the 3rd and finger 4 on the 4th: one finger per fret. Press each just behind the fret wire with the fingertip and pick it. Then move the shape to the next string."},{"type":"callout","tone":"tip","text":"Use a mirror or your phone camera. Look for a straight-ish fretting wrist and a relaxed picking shoulder."}],"exercise":{"title":"One finger per fret, relaxed","steps":["Play frets 1-2-3-4 on each string from high E to low E, slowly.","Release pressure between notes until the note just stops buzzing; that is the minimum pressure you need.","Repeat standing up with your strap adjusted."]},"metronome":{"bpmStart":50,"bpmTarget":70,"subdivision":1,"instructions":"One note per click. Focus on relaxed, buzz-free notes rather than speed."},"mistakes":["Thumb wrapped high over the neck while learning single notes (fine for some chords later).","Fretting in the middle of the fret space or on the fret wire, which causes buzzing or muted notes.","Collapsed, flat fingers touching neighbouring strings.","Raised picking shoulder."],"selfCheck":["I can hold one-finger-per-fret position without pain.","My fingertips land just behind the frets.","I check my tension regularly."],"realWorld":"Professional players often practise for hours a day without pain because their posture is relaxed and efficient. This lesson is the foundation for that stamina.","summary":["Straight back, relaxed shoulders, guitar at a consistent height.","Fingertips just behind frets, thumb behind the neck.","Minimum pressure; constant tension checks."],"next":"l0-pick","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Play one-finger-per-fret on all six strings at 60 bpm without buzzing."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0p-1', 'l0-posture', 'Where should a fingertip press the string?', '["Directly on top of the fret wire","Just behind the fret wire","In the middle between two frets","Anywhere, as long as it is firm"]'::jsonb, 1, 'Just behind the fret gives a clear note with the least pressure.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0p-2', 'l0-posture', 'Which finger is "finger 3"?', '["Index","Middle","Ring","Pinky"]'::jsonb, 2, 'Index = 1, middle = 2, ring = 3, pinky = 4. The thumb is usually labelled T.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0p-3', 'l0-posture', 'What is the main sign you are pressing too hard?', '["The note buzzes","Your hand tires fast and the note goes sharp","The amp hums","The string breaks"]'::jsonb, 1, 'Excess pressure bends the pitch sharp and wastes energy. Find the minimum pressure that stops buzzing.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l0-pick', 'm0-setup', 0, 'Holding and using the pick', 15, array['Hold a pick securely with a small tip exposed', 'Choose a pick thickness for your style', 'Play controlled down- and upstrokes']::text[], array['l0-posture']::text[], array['technique']::text[], '[{"book":"A","section":"Right-hand position"},{"book":"P","note":"Pick grip and pick gauge"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Alternate-pick open strings at 80 bpm eighth notes cleanly."]}'::jsonb, 3) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l0-pick', '{"id":"l0-pick","level":0,"module":"m0-setup","title":"Holding and using the pick","minutes":15,"objectives":["Hold a pick securely with a small tip exposed","Choose a pick thickness for your style","Play controlled down- and upstrokes"],"prerequisites":["l0-posture"],"categories":["technique"],"sources":[{"book":"A","section":"Right-hand position"},{"book":"P","note":"Pick grip and pick gauge"}],"why":"The pick is where your tone, timing and speed are born. A consistent grip makes every later picking technique easier.","explanation":[{"type":"p","text":"Curl your index finger. Lay the pick on the side of the last joint with the point aiming away from you, then place the pad of your thumb on top. Only 2–3 mm of the tip should show. Grip firmly enough that the pick does not spin, but not so hard that your forearm tenses."},{"type":"p","text":"Pick thickness (gauge) changes feel and tone. Thin picks (0.4–0.6 mm) flex and suit light strumming. Medium (0.6–0.8 mm) is an all-rounder. Heavy picks (1.0 mm and up) give precise, punchy single notes and are standard for lead playing and metal."},{"type":"table","head":["Gauge","Feel","Best for"],"rows":[["0.40–0.60 mm","Flexible","Light strumming"],["0.60–0.80 mm","Medium","All-round rhythm and lead"],["0.88–1.14 mm","Firm","Rock lead and riffs"],["1.5 mm +","Rigid","Fast picking, metal, jazz"]]},{"type":"p","text":"A downstroke moves toward the floor (symbol ⊓ in notation); an upstroke moves toward the ceiling (symbol V). Keep the motion small and come from the wrist or a mix of wrist and forearm, not from the elbow alone."}],"guitar":[{"type":"p","text":"Rest your forearm on the body and pick the open low E string with downstrokes, aiming to hit only that string. Then alternate down-up on each open string. Notice that a smaller motion gives you more control."},{"type":"callout","tone":"tip","text":"Angle the pick very slightly (about 10–20°) so it glides through the string instead of catching on it."}],"exercise":{"title":"Downstroke and upstroke control","steps":["Four downstrokes on each open string from low E to high E.","Four upstrokes on each string.","Alternate down-up, four pairs per string, keeping the motion as small as possible."]},"metronome":{"bpmStart":60,"bpmTarget":90,"subdivision":2,"instructions":"Alternate down on the beat, up on the \"and\"."},"mistakes":["Too much pick showing, which makes it flap and miss strings.","Gripping so hard that the forearm locks.","Big, arm-driven strokes that overshoot the string."],"selfCheck":["My pick does not spin or slip after a minute of playing.","I can hit a single open string without touching its neighbours."],"realWorld":"Many great lead players use small, stiff picks with very little tip showing. Experiment, but keep one grip long enough for it to become automatic.","summary":["Pick between thumb pad and the side of the index finger, small tip showing.","Gauge affects feel and tone.","Small, efficient down- and upstrokes."],"next":"l0-tuning","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Alternate-pick open strings at 80 bpm eighth notes cleanly."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0k-1', 'l0-pick', 'How much of the pick tip should usually be exposed?', '["About half the pick","2–3 mm","None","As much as possible for speed"]'::jsonb, 1, 'A small exposed tip gives control and precision.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0k-2', 'l0-pick', 'The symbol V above a note means…', '["Vibrato","Upstroke","Downstroke","Volume swell"]'::jsonb, 1, 'V is an upstroke; a square bracket shape (⊓) is a downstroke.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0k-3', 'l0-pick', 'Which pick is most typical for fast, precise single-note lead playing?', '["0.46 mm","0.60 mm","1.0 mm or thicker","No pick"]'::jsonb, 2, 'Heavier picks do not flex, so attacks are precise and consistent.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l0-tuning', 'm0-setup', 0, 'Standard tuning and how to tune', 20, array['Name the open strings E A D G B E', 'Use the built-in tuner to tune every string', 'Understand cents, flat and sharp']::text[], array[]::text[], array['theory', 'ear']::text[], '[{"book":"A","section":"Tuning: E–A–D–G–B–E and the electronic tuner"},{"book":"P","note":"Cents, reference pitch and alternate tunings"}]'::jsonb, '{"quizPass":0.75,"criteria":["Score at least 75%.","Tune all strings within ±3 cents using the tuner."]}'::jsonb, 4) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l0-tuning', '{"id":"l0-tuning","level":0,"module":"m0-setup","title":"Standard tuning and how to tune","minutes":20,"objectives":["Name the open strings E A D G B E","Use the built-in tuner to tune every string","Understand cents, flat and sharp"],"prerequisites":[],"categories":["theory","ear"],"sources":[{"book":"A","section":"Tuning: E–A–D–G–B–E and the electronic tuner"},{"book":"P","note":"Cents, reference pitch and alternate tunings"}],"why":"An out-of-tune guitar makes correct playing sound wrong, and trains your ear badly. Tuning is the first thing you do every time you pick up the instrument.","explanation":[{"type":"p","text":"In standard tuning the six open strings, from the thickest (lowest pitch, nearest your face) to the thinnest (highest pitch, nearest the floor) are E A D G B E. A popular memory aid: \"Eddie Ate Dynamite, Good Bye Eddie.\""},{"type":"p","text":"Strings are also numbered from the thinnest: the high E is string 1 and the low E is string 6. So \"the 5th string\" is the A string. On 7- and 8-string guitars the extra strings are lower: string 7 is usually B, string 8 usually F♯."},{"type":"table","head":["String","Note","Octave","Frequency"],"rows":[["6","E","E2","82.41 Hz"],["5","A","A2","110.00 Hz"],["4","D","D3","146.83 Hz"],["3","G","G3","196.00 Hz"],["2","B","B3","246.94 Hz"],["1","E","E4","329.63 Hz"]]},{"type":"p","text":"A tuner measures the pitch you play and shows how far it is from the nearest note in cents. A cent is 1/100 of a semitone. Negative cents (flat) means the string is too low: tighten it. Positive cents (sharp) means too high: loosen it. Within ±3 cents is effectively perfect."},{"type":"callout","tone":"tip","text":"Always tune up to the note. If a string is sharp, go below the target and come back up. This settles the string against the tuner gear so it stays in tune."},{"type":"callout","tone":"theory","text":"The reference pitch is A4 = 440 Hz. The app lets you change it (for example to 432 Hz) to match a recording or another instrument."}],"guitar":[{"type":"list","items":["Open the Tuner (the tuning-fork button is always in the header).","Allow microphone access. Audio is analysed on your device and never recorded or uploaded.","Pick the low E string and let it ring. Watch the needle: left = flat, right = sharp.","Turn the tuning key slowly until the needle centres and turns green.","Repeat for A, D, G, B and high E, then check all six again: changing one string slightly changes the others'' tension."],"ordered":true},{"type":"p","text":"On most guitars, turning a tuner so the post winds more string on raises the pitch. Turn slowly, a few degrees at a time."}],"exercise":{"title":"Tune from scratch","steps":["Detune two strings slightly on purpose.","Use the tuner to bring all six strings within ±3 cents.","Use the reference-tone mode to hear each target pitch and try tuning one string by ear before checking."]},"mistakes":["Tuning to the wrong octave: the tuner shows the octave number; low E must read E2.","Turning the wrong tuner peg.","Tuning down to the note instead of up.","Pressing a fret accidentally while tuning an open string."],"selfCheck":["I can say the six string names from low to high and high to low.","I can tune all six strings in under two minutes."],"realWorld":"Before every rehearsal, recording or gig, guitarists tune, often between songs too. Drop D and E♭ tunings in the tuner prepare you for songs that use them.","summary":["Standard tuning is E A D G B E (low to high).","Cents measure how far off you are; ±3 is in tune.","Tune up to the note, then re-check all strings."],"next":"l0-tab","mastery":{"quizPass":0.75,"criteria":["Score at least 75%.","Tune all strings within ±3 cents using the tuner."]},"unlocks":{"trainerModes":["note-id"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0t-1', 'l0-tuning', 'What are the open strings in standard tuning, from low to high?', '["E A D G B E","E B G D A E","A D G C E A","E A D G C F"]'::jsonb, 0, 'Low to high: E A D G B E.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0t-2', 'l0-tuning', 'Which string is "string 1"?', '["The low E","The A string","The high E","The G string"]'::jsonb, 2, 'Strings are numbered from the thinnest: string 1 is the high E.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0t-3', 'l0-tuning', 'The tuner shows −15 cents. The string is…', '["Sharp: loosen it","Flat: tighten it","In tune","An octave too low"]'::jsonb, 1, 'Negative cents means the pitch is below the target: tighten (raise) it.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0t-4', 'l0-tuning', 'Why tune up to the note rather than down?', '["It is faster","The string settles against the gear and holds tuning better","Tuners only read rising pitches","It lowers string tension"]'::jsonb, 1, 'Approaching from below removes slack in the gear and string, so the tuning stays put.', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l0-tab', 'm0-reading', 0, 'Reading tablature', 20, array['Read string and fret information from tab', 'Recognise stacked notes (chords and double stops)', 'Understand common tab symbols']::text[], array['l0-tuning']::text[], array['theory', 'repertoire']::text[], '[{"book":"A","section":"Your first notes: tablature"},{"book":"C","section":"Tab conventions used throughout Book 3"},{"book":"P","note":"Technique symbols"}]'::jsonb, '{"quizPass":0.75,"criteria":["Score at least 75%.","Play both tab examples correctly from the page."]}'::jsonb, 5) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l0-tab', '{"id":"l0-tab","level":0,"module":"m0-reading","title":"Reading tablature","minutes":20,"objectives":["Read string and fret information from tab","Recognise stacked notes (chords and double stops)","Understand common tab symbols"],"prerequisites":["l0-tuning"],"categories":["theory","repertoire"],"sources":[{"book":"A","section":"Your first notes: tablature"},{"book":"C","section":"Tab conventions used throughout Book 3"},{"book":"P","note":"Technique symbols"}],"why":"Tab is the most common way guitar music is written and shared. Reading it fluently opens up almost every song, lesson and exercise.","explanation":[{"type":"p","text":"Tablature uses one horizontal line per string. The TOP line is the highest string (high E) and the BOTTOM line is the lowest (low E), which matches looking down at the guitar from above. A number on a line tells you which fret to press on that string; 0 means play the string open."},{"type":"p","text":"Read left to right like text. Numbers stacked vertically are played at the same time (a chord or a double stop). Numbers placed one after another are played one after another."},{"type":"tab","ascii":"e|-----------------0---|\nB|-------------1-------|\nG|---------0-----------|\nD|-----2---------------|\nA|-3-------------------|\nE|---------------------|","caption":"A C-major chord played one note at a time (an arpeggio): A string 3rd fret, D string 2nd fret, open G, B string 1st fret, open high E."},{"type":"table","head":["Symbol","Meaning"],"rows":[["h","Hammer-on"],["p","Pull-off"],["/ and \\","Slide up / down"],["b","Bend (7b9 = bend the 7th fret up to the pitch of the 9th)"],["~","Vibrato"],["x","Muted, pitchless \"dead\" note"],["PM----","Palm mute for the length of the dashes"],["<12>","Natural harmonic"]]},{"type":"callout","tone":"warning","text":"Basic tab does not show rhythm. Listen to the music, or use rhythm tab (stems and beams), which you will learn next."}],"guitar":[{"type":"tab","ascii":"e|-------------------------|\nB|-------------------------|\nG|-------------------------|\nD|---------------2---4-----|\nA|-------0---3-------------|\nE|-0---3-------------------|","caption":"An original riff on the three lowest strings. Play each note with a downstroke."}],"exercise":{"title":"Read and play","steps":["Play the C-major arpeggio above slowly, letting the notes ring.","Play the low-string riff, saying the string and fret aloud for each note.","Open the Tab Editor, write a four-note riff of your own, and play it back."]},"mistakes":["Reading tab upside down (the top line is the THIN string).","Playing stacked numbers one at a time.","Confusing fret numbers with finger numbers."],"selfCheck":["I can read a tab line and instantly know string and fret.","I know at least five tab symbols."],"realWorld":"Almost every online lesson, song transcription and guitar magazine uses tab. The app''s Tab Editor can import ASCII tab you find online and export your own exercises.","summary":["Six lines = six strings, high E on top.","Numbers = frets; 0 = open; stacked = together.","Symbols show techniques; basic tab has no rhythm."],"next":"l0-chord-diagrams","mastery":{"quizPass":0.75,"criteria":["Score at least 75%.","Play both tab examples correctly from the page."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0b-1', 'l0-tab', 'In tab, the top line represents…', '["The low E string","The high E string","The A string","Whichever string is played first"]'::jsonb, 1, 'The top line is the highest-pitched (thinnest) string.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0b-2', 'l0-tab', 'A "0" on the G line means…', '["Do not play the G string","Play the G string open","Play the G string at fret 10","Mute the G string"]'::jsonb, 1, 'Zero means the string is played open, without fretting.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0b-3', 'l0-tab', 'Numbers stacked vertically are played…', '["One after another, low to high","At the same time","Only with hammer-ons","Twice each"]'::jsonb, 1, 'Vertically aligned numbers sound together.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0b-4', 'l0-tab', 'What does "7b9" mean?', '["Fret 7, then fret 9","Bend fret 7 up to the pitch of fret 9","Slide from 7 to 9","Play frets 7 and 9 together"]'::jsonb, 1, 'The bend raises fret 7 by a whole step, to fret 9''s pitch.', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l0-chord-diagrams', 'm0-reading', 0, 'Reading chord diagrams', 15, array['Read strings, frets, fingers, open and muted strings from a chord diagram', 'Recognise barre markings and position numbers']::text[], array['l0-tab']::text[], array['chords', 'theory']::text[], '[{"book":"C","section":"Barre chords: chord diagrams"},{"book":"A","section":"Playing chords"},{"book":"P"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Form Em, C, G and D from diagrams with every note ringing."]}'::jsonb, 6) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l0-chord-diagrams', '{"id":"l0-chord-diagrams","level":0,"module":"m0-reading","title":"Reading chord diagrams","minutes":15,"objectives":["Read strings, frets, fingers, open and muted strings from a chord diagram","Recognise barre markings and position numbers"],"prerequisites":["l0-tab"],"categories":["chords","theory"],"sources":[{"book":"C","section":"Barre chords: chord diagrams"},{"book":"A","section":"Playing chords"},{"book":"P"}],"why":"Chord diagrams are the fastest way to learn a chord shape. Every chord in this academy is shown as a diagram, and the Chord Explorer draws them for any tuning.","explanation":[{"type":"p","text":"A chord diagram is a picture of the fretboard standing upright. Vertical lines are strings: the LEFT line is the low E string and the RIGHT line is the high E. Horizontal lines are frets; a thick line at the top is the nut."},{"type":"p","text":"Dots show where to press. A number in or under a dot tells you which finger to use (1 = index … 4 = pinky). Above the diagram, \"o\" means play the string open and \"x\" means do not play (mute) that string."},{"type":"p","text":"When the shape is higher up the neck, a number such as \"5fr\" beside the diagram tells you which fret the top line represents. A curved line or bar across several strings is a barre: one finger presses several strings at the same fret."},{"type":"chord","symbols":["Em","C","G","D"],"caption":"Four open chords. Compare each diagram with the tab version you play next."}],"guitar":[{"type":"p","text":"Read the E minor diagram: there are no x marks, so all six strings sound. Fingers 2 and 3 press the 2nd fret of the A and D strings. Strum all six strings. Then read the C diagram: the low E has an \"x\", so start your strum on the A string."},{"type":"callout","tone":"tip","text":"Place all fingers of a chord at once rather than one by one. It feels slower at first but makes chord changes much faster later."}],"exercise":{"title":"Diagram to fingers","steps":["Read each of the four diagrams aloud: which strings are open, muted and fretted, and with which fingers.","Form each chord and pick the strings one at a time to check every note rings clearly.","Open the Chord Explorer and look up the same chords in Drop D tuning: notice how the shapes change."]},"mistakes":["Mirroring the diagram (low E is on the LEFT).","Ignoring \"x\" strings and strumming notes that do not belong to the chord.","Fingers leaning on and muting neighbouring strings."],"selfCheck":["I can read any chord diagram correctly, including x, o and fret numbers."],"realWorld":"Song books and chord charts show diagrams above the lyrics. Being able to read them instantly lets you play along with thousands of songs.","summary":["Strings vertical (low E left), frets horizontal.","Dots = fingers; o = open; x = muted.","Fret labels and barre lines for higher positions."],"next":"l0-rhythm-notation","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Form Em, C, G and D from diagrams with every note ringing."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0c-1', 'l0-chord-diagrams', 'In a standard chord diagram, the leftmost vertical line is…', '["The high E string","The low E string","The 1st fret","The nut"]'::jsonb, 1, 'Diagrams show the guitar upright, facing you: low E on the left.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l0c-2', 'l0-chord-diagrams', 'An "x" above a string means…', '["Play it open","Do not play it","Bend it","Use finger 1"]'::jsonb, 1, 'x = muted or not played.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
