insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l2-sharps-flats', 'm2-notes', 2, 'Sharps, flats and enharmonic equivalents', 15, array['Explain sharp (♯) and flat (♭)', 'Recognise enharmonic equivalents such as C♯ = D♭', 'Know when to use sharp or flat names']::text[], array['l2-musical-alphabet']::text[], array['theory', 'fretboard']::text[], '[{"book":"P","note":"Accidentals and enharmonic spelling"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}'::jsonb, 18) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l2-sharps-flats', '{"id":"l2-sharps-flats","level":2,"module":"m2-notes","title":"Sharps, flats and enharmonic equivalents","minutes":15,"objectives":["Explain sharp (♯) and flat (♭)","Recognise enharmonic equivalents such as C♯ = D♭","Know when to use sharp or flat names"],"prerequisites":["l2-musical-alphabet"],"categories":["theory","fretboard"],"sources":[{"book":"P","note":"Accidentals and enharmonic spelling"}],"why":"The same fret can have two names. Knowing which name to use keeps scales and chords readable and makes theory click.","explanation":[{"type":"p","text":"A sharp (♯) raises a note by a half step; a flat (♭) lowers it by a half step. The fret between F and G can be called F♯ or G♭. Two names for the same sound are called enharmonic equivalents."},{"type":"p","text":"Which name is right depends on context. In a scale, each letter appears once: the G major scale is G A B C D E F♯ (not G♭, because G is already used). The F major scale is F G A B♭ C D E (not A♯, because A is already used)."},{"type":"callout","tone":"theory","text":"There are rarer spellings too: E♯ (= F), C♭ (= B), and double sharps or flats in some keys and chords. The theory engine in this app always spells notes correctly for their key."}],"guitar":[{"type":"p","text":"On the A string, play fret 1 and say both names: \"A-sharp or B-flat.\" Do the same for every fret that is not a natural note up to fret 12."},{"type":"callout","tone":"tip","text":"In settings you can choose whether the fretboard shows sharps or flats by default."}],"exercise":{"title":"Two names, one fret","steps":["On the D string, find all five notes that have two names between frets 0 and 12.","Use the Fretboard Trainer in \"Name the note\" mode with Stage 2."]},"mistakes":["Writing a scale with two versions of the same letter (G♭ and G).","Thinking sharps and flats are different pitches on the guitar."],"selfCheck":["I can give both names of every sharp/flat note."],"realWorld":"Chord charts say B♭ and F♯, not A♯ and G♭, because they follow key spelling. Reading them confidently comes from this lesson.","summary":["♯ raises, ♭ lowers by a half step.","Enharmonic = same pitch, different name.","Scales use each letter once."],"next":"l2-root-strings","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l2s-1', 'l2-sharps-flats', 'What is the enharmonic equivalent of D♯?', '["E","E♭","D♭","C♯"]'::jsonb, 1, 'D♯ and E♭ are the same pitch.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
