insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l2-root-strings', 'm2-notes', 2, 'Notes on the E and A strings (root strings)', 25, array['Know every natural note on the low E and A strings to fret 12', 'Use landmark frets 3, 5, 7, 9 and 12', 'Name power chords and barre chords by their root']::text[], array['l2-sharps-flats']::text[], array['fretboard']::text[], '[{"book":"A","section":"The low E and A strings"},{"book":"C","section":"Root of barre chords on the 6th and 5th strings"},{"book":"P","note":"Landmark method"}]'::jsonb, '{"quizPass":0.75,"criteria":["Score at least 75%.","Reach 90% in the Fretboard Trainer on strings 6 and 5 (frets 0–12, naturals)."]}'::jsonb, 19) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l2-root-strings', '{"id":"l2-root-strings","level":2,"module":"m2-notes","title":"Notes on the E and A strings (root strings)","minutes":25,"objectives":["Know every natural note on the low E and A strings to fret 12","Use landmark frets 3, 5, 7, 9 and 12","Name power chords and barre chords by their root"],"prerequisites":["l2-sharps-flats"],"categories":["fretboard"],"sources":[{"book":"A","section":"The low E and A strings"},{"book":"C","section":"Root of barre chords on the 6th and 5th strings"},{"book":"P","note":"Landmark method"}],"why":"Almost every movable shape (power chords, barre chords, scale patterns) is named after its root on the E or A string. Learn these two strings first.","explanation":[{"type":"p","text":"Landmarks make memorising fast. On the low E string: fret 3 = G, 5 = A, 7 = B, 8 = C, 10 = D, 12 = E. On the A string: fret 2 = B, 3 = C, 5 = D, 7 = E, 8 = F, 10 = G, 12 = A."},{"type":"p","text":"The inlay dots help: fret 5 on the E string is A, the same note as the open A string. Fret 5 on the A string is D, the open D string. That relationship (fret 5 = next open string) works on every pair of strings except G→B, which you will see in the next module."},{"type":"table","head":["Fret","3","5","7","8","10","12"],"rows":[["E string","G","A","B","C","D","E"],["A string","C","D","E","F","G","A"]],"caption":"Landmarks on the root strings."}],"guitar":[{"type":"fretboard","root":"E","notes":["E","F","G","A","B","C","D"],"maxFret":12,"labels":"note","caption":"Focus only on the bottom two strings first."},{"type":"p","text":"Practise: name a power chord, find its root on the E string, play it, then find the same chord with its root on the A string. For example, C5 is at fret 8 on the E string or fret 3 on the A string."}],"exercise":{"title":"Root hunt","steps":["Play the natural notes on the E string up and down, naming them.","Same on the A string.","Fretboard Trainer: \"Note on a string\" restricted to strings 6 and 5, until you reach 90% accuracy."]},"mistakes":["Counting every fret from the nut instead of using landmarks.","Relying on a single position for each note."],"selfCheck":["I can find any natural note on the E and A strings in under 3 seconds."],"realWorld":"When a bandmate says \"the riff is in D, starting on the 10th fret,\" you can find it instantly.","summary":["Learn landmarks, not every fret.","Fret 5 = next open string (except G→B).","Movable shapes are named after these roots."],"next":"l2-octaves","mastery":{"quizPass":0.75,"criteria":["Score at least 75%.","Reach 90% in the Fretboard Trainer on strings 6 and 5 (frets 0–12, naturals)."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
