insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l2-octaves', 'm2-navigation', 2, 'Octave shapes and finding every note', 25, array['Use octave shapes to find a note on every string', 'Understand why the G–B string pair shifts the shape', 'Find all occurrences of a note across the neck']::text[], array['l2-root-strings']::text[], array['fretboard']::text[], '[{"book":"P","note":"Octave-shape fretboard navigation"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Find all Gs, Cs and F♯s on the neck using octave shapes."]}'::jsonb, 20) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l2-octaves', '{"id":"l2-octaves","level":2,"module":"m2-navigation","title":"Octave shapes and finding every note","minutes":25,"objectives":["Use octave shapes to find a note on every string","Understand why the G–B string pair shifts the shape","Find all occurrences of a note across the neck"],"prerequisites":["l2-root-strings"],"categories":["fretboard"],"sources":[{"book":"P","note":"Octave-shape fretboard navigation"}],"why":"Octave shapes let you jump from a note you know to the same note elsewhere, which is the fastest route to knowing the entire fretboard.","explanation":[{"type":"p","text":"An octave is the same note name 12 half steps higher. On the guitar you can reach many octaves with fixed shapes. From a note on the E or A string, the octave is two strings higher and two frets higher. From the D or G string, crossing the B string adds one fret: two strings higher, three frets higher."},{"type":"p","text":"Another common shape goes three strings higher and three frets lower (E string to G string), again plus one fret if the jump crosses the G–B pair."},{"type":"callout","tone":"theory","text":"Standard tuning is built from perfect 4ths (5 half steps) between strings, except G to B, which is a major 3rd (4 half steps). Every shape that crosses that pair moves up one fret to compensate. This same \"B-string shift\" appears in Pillitiere''s scale system in Level 6."},{"type":"fretboard","root":"G","notes":["G"],"maxFret":17,"labels":"note","caption":"Every G between frets 0 and 17. Trace the octave shapes linking them."}],"guitar":[{"type":"tab","ascii":"e|---------------3--|\nB|----------8-------|\nG|------------------|\nD|-----5------------|\nA|-------------10---|\nE|-3----------------|","caption":"Gs linked by octave shapes: low E fret 3 → D string fret 5 (two strings up, two frets up); D fret 5 → B fret 8 (two strings up, three frets up: the G–B shift); A fret 10 is the same pitch as D fret 5; high E fret 3 is the same pitch as B fret 8."}],"exercise":{"title":"Find all the Gs","steps":["Starting on the low E string fret 3, use octave shapes to find every G up to fret 17.","Repeat for C, then for F♯.","Fretboard Trainer: \"Find every occurrence\" and \"Octave shapes\" modes."]},"mistakes":["Forgetting the extra fret when crossing the G–B pair.","Only knowing one octave shape."],"selfCheck":["I can find every occurrence of a note between frets 0 and 12 in under 15 seconds."],"realWorld":"Octave shapes are also a sound: guitarists play melodies in octaves for a big, fat lead tone. You will use that in Level 9.","summary":["Octave shapes link the same note across strings.","Add one fret when crossing the G–B pair.","Use them to find every note fast."],"next":"l2-tuning-relationships","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Find all Gs, Cs and F♯s on the neck using octave shapes."]},"unlocks":{"trainerModes":["find-all","octaves"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l2o-1', 'l2-octaves', 'From the A string, the octave two strings higher is…', '["Two frets higher","Three frets higher","Two frets lower","The same fret"]'::jsonb, 0, 'From E or A string: two strings up, two frets up.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
