insert into public.lesson_content (lesson_id, content) values ('l2-tuning-relationships', '{"id":"l2-tuning-relationships","level":2,"module":"m2-navigation","title":"Standard tuning relationships and fretboard navigation","minutes":20,"objectives":["Tune string to string using the 5th-fret method","Understand how alternate tunings change note locations","Navigate all strings to fret 12"],"prerequisites":["l2-octaves"],"categories":["fretboard","ear"],"sources":[{"book":"C","section":"Drop D tuning"},{"book":"P","note":"Relative tuning and tuning systems"}],"why":"Understanding how strings relate lets you tune without a tuner, read music in any tuning, and see why shapes behave the way they do.","explanation":[{"type":"p","text":"Relative tuning: with the low E in tune, fret 5 of the E string should match the open A. Fret 5 of A matches open D, fret 5 of D matches open G, fret 4 of G matches open B, and fret 5 of B matches open high E."},{"type":"p","text":"Alternate tunings change these relationships. In Drop D the low string is lowered a whole step to D, so its notes move two frets higher than in standard (D is open, E is at fret 2). In E♭ standard every string is a half step lower but the relationships stay the same, so all shapes still work."},{"type":"callout","tone":"warning","text":"The Fretboard, Scale Explorer, Tab Editor and Trainer all follow your selected tuning, including 7- and 8-string tunings and your own custom tunings. If notes look wrong, check the tuning selector."}],"guitar":[{"type":"list","items":["Tune the low E with the tuner, then tune the other strings by ear with the 5th-fret method.","Check your result with the tuner and note which strings were off.","Switch the Fretboard to Drop D and compare where the notes on the lowest string moved."],"ordered":true}],"exercise":{"title":"Ear tuning and tuning maps","steps":["Relative-tune all strings, then check with the tuner.","In the Fretboard view, show natural notes in standard tuning, then in Drop D and Open G. Describe what changed."]},"mistakes":["Using fret 5 on the G string (it should be fret 4) when relative tuning.","Assuming chord shapes work unchanged in open tunings."],"selfCheck":["I can tune by ear to within 10 cents of the tuner.","I can explain how Drop D changes the lowest string."],"realWorld":"Many famous recordings use E♭ standard or Drop D. Knowing what a tuning changes lets you play along correctly.","summary":["5th-fret method (4th fret on G).","Alternate tunings move notes on retuned strings.","All app tools follow your tuning."],"next":"l2-pitch","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Relative-tune all strings within 10 cents."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
