insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l2-pitch', 'm2-navigation', 2, 'Introduction to pitch recognition', 15, array['Match a heard pitch on the guitar', 'Tell higher from lower and same from different', 'Start daily ear training']::text[], array['l2-musical-alphabet']::text[], array['ear']::text[], '[{"book":"P","note":"Ear-training foundations"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions correctly.","Complete 20 level-1 interval questions with 70% or more."]}'::jsonb, 22) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l2-pitch', '{"id":"l2-pitch","level":2,"module":"m2-navigation","title":"Introduction to pitch recognition","minutes":15,"objectives":["Match a heard pitch on the guitar","Tell higher from lower and same from different","Start daily ear training"],"prerequisites":["l2-musical-alphabet"],"categories":["ear"],"sources":[{"book":"P","note":"Ear-training foundations"}],"why":"Your ear guides everything: tuning, learning songs, improvising. Like the fingers, it improves with short, regular practice.","explanation":[{"type":"p","text":"Pitch matching means hearing a note and finding it on the guitar. Start by deciding direction: is the target higher or lower than the note you are playing? Then move in that direction one fret at a time until the two notes merge and the \"beating\" (a wobble when two pitches are close) disappears."},{"type":"p","text":"Singing helps enormously. Humming a note before you play it connects your ear and your hands."}],"guitar":[{"type":"list","items":["Open the Tuner and use reference-tone mode to play a pitch.","Find it on the guitar by ear, then confirm with the tuner.","Open Ear Training → Relative pitch and Intervals (level 1)."],"ordered":true}],"exercise":{"title":"Five minutes of ears","steps":["Do 20 interval questions at level 1.","Do 10 relative-pitch questions.","Hum the low E string, then play it to check."]},"mistakes":["Guessing instead of listening for the beating to stop.","Skipping ear training because it feels hard; it gets easier quickly."],"selfCheck":["I can match a pitch within the first 5 frets of one string."],"realWorld":"Learning songs by ear, finding a singer''s key and jamming all start with pitch recognition.","summary":["Decide direction, then move by half steps.","Listen for beating to disappear.","Hum and sing to train the ear."],"next":"l3-pitch-intervals","mastery":{"quizPass":1,"criteria":["Answer both questions correctly.","Complete 20 level-1 interval questions with 70% or more."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
