insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l3-pitch-intervals', 'm3-intervals', 3, 'What music theory is: pitch and frequency', 15, array['Explain what music theory is for', 'Relate pitch to frequency and octaves to doubling', 'Understand equal temperament at a basic level']::text[], array['l2-musical-alphabet']::text[], array['theory']::text[], '[{"book":"P","note":"Acoustics and the purpose of theory"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}'::jsonb, 23) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l3-pitch-intervals', '{"id":"l3-pitch-intervals","level":3,"module":"m3-intervals","title":"What music theory is: pitch and frequency","minutes":15,"objectives":["Explain what music theory is for","Relate pitch to frequency and octaves to doubling","Understand equal temperament at a basic level"],"prerequisites":["l2-musical-alphabet"],"categories":["theory"],"sources":[{"book":"P","note":"Acoustics and the purpose of theory"}],"why":"Theory is not a set of rules; it is a vocabulary for what you hear. It lets you understand why things sound the way they do and communicate with other musicians.","explanation":[{"type":"p","text":"Music theory describes patterns that musicians have used for centuries: how notes combine into scales, how scales produce chords, and how chords move. Knowing the patterns lets you learn songs faster, improvise intentionally and write your own music."},{"type":"p","text":"Pitch is how high or low a sound is, set by its frequency (vibrations per second, measured in hertz). The open A string vibrates 110 times per second (110 Hz). An octave higher is exactly double (220 Hz); an octave lower is half (55 Hz). That doubling is why notes an octave apart sound like \"the same note.\""},{"type":"p","text":"Western music divides the octave into 12 equal half steps (equal temperament). Each fret multiplies the frequency by the twelfth root of two (about 1.0595). That is why frets get closer together as you go up the neck."},{"type":"callout","tone":"theory","text":"The tuner uses exactly this maths: it measures the frequency you play and converts it to a note name and a deviation in cents (1/100 of a half step)."}],"guitar":[{"type":"p","text":"Play the open A (110 Hz), then fret 12 on the A string (220 Hz), then the open high E (330 Hz). Watch the tuner''s frequency display for each."}],"exercise":{"title":"See the frequencies","steps":["Play the open A string and fret 12 of the A string; note both frequencies in the tuner.","Play the A on fret 5 of the low E: compare it with the open A string."]},"mistakes":["Thinking theory restricts creativity; it explains choices rather than dictating them."],"selfCheck":["I can explain why an octave sounds like the same note."],"realWorld":"Understanding frequency helps when you set EQ on an amp, choose a tuning, or read a tuner precisely.","summary":["Theory names what we hear.","Pitch = frequency; octave = double.","12 equal half steps per octave."],"next":"l3-intervals","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l3p-1', 'l3-pitch-intervals', 'If A2 is 110 Hz, A3 is…', '["55 Hz","165 Hz","220 Hz","440 Hz"]'::jsonb, 2, 'An octave up doubles the frequency.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l3p-2', 'l3-pitch-intervals', 'How many equal half steps make an octave in Western music?', '["7","8","12","24"]'::jsonb, 2, 'Twelve half steps (equal temperament).', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l3p-3', 'l3-pitch-intervals', 'Why are frets closer together higher up the neck?', '["To save wood","Each fret multiplies frequency by the same ratio, so the string length shrinks by a constant factor","For decoration","Higher strings are thinner"]'::jsonb, 1, 'Equal ratios mean progressively shorter distances.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l3-intervals', 'm3-intervals', 3, 'Intervals: names, sounds and shapes', 30, array['Name intervals from unison to octave by half-step count', 'See interval shapes on the fretboard', 'Recognise the sound of key intervals by ear']::text[], array['l3-pitch-intervals', 'l2-octaves']::text[], array['theory', 'fretboard', 'ear']::text[], '[{"book":"P","note":"Interval theory"},{"book":"C","section":"Intervals implied in triads and power chords"}]'::jsonb, '{"quizPass":0.8,"criteria":["Score at least 80%, including generated interval questions.","Find any interval from a given root on the fretboard."]}'::jsonb, 24) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l3-intervals', '{"id":"l3-intervals","level":3,"module":"m3-intervals","title":"Intervals: names, sounds and shapes","minutes":30,"objectives":["Name intervals from unison to octave by half-step count","See interval shapes on the fretboard","Recognise the sound of key intervals by ear"],"prerequisites":["l3-pitch-intervals","l2-octaves"],"categories":["theory","fretboard","ear"],"sources":[{"book":"P","note":"Interval theory"},{"book":"C","section":"Intervals implied in triads and power chords"}],"why":"Intervals are the atoms of music. Scales, chords, melodies and harmony are all made from them. Once you think in intervals, the fretboard becomes a map of relationships instead of a list of note names.","explanation":[{"type":"p","text":"An interval is the distance between two notes. Interval names have a number (2nd, 3rd, 4th…) counted by letter names, and a quality (major, minor, perfect, augmented, diminished) set by the exact number of half steps."},{"type":"table","head":["Half steps","Interval","Symbol","Sound"],"rows":[["0","Unison","P1","Same note"],["1","Minor 2nd","m2 / ♭2","Tense, dissonant"],["2","Major 2nd","M2 / 2","A step"],["3","Minor 3rd","m3 / ♭3","Sad, dark"],["4","Major 3rd","M3 / 3","Happy, bright"],["5","Perfect 4th","P4 / 4","Open, suspended"],["6","Tritone","TT / ♭5 / ♯4","Unstable"],["7","Perfect 5th","P5 / 5","Strong, stable (power chord)"],["8","Minor 6th","m6 / ♭6","Bittersweet"],["9","Major 6th","M6 / 6","Sweet"],["10","Minor 7th","m7 / ♭7","Bluesy"],["11","Major 7th","M7 / 7","Dreamy, tense"],["12","Octave","P8","Same note, higher"]]},{"type":"p","text":"On the guitar, intervals have shapes. On one string, count frets. Across strings in standard tuning: the same fret on the next string up is a perfect 4th; one fret higher on the next string is a tritone; two frets higher is a perfect 5th (the power-chord shape); one fret lower is a major 3rd; two frets lower is a minor 3rd. Remember to shift one fret when crossing from G to B."},{"type":"callout","tone":"theory","text":"The formula tokens you will see everywhere (1, ♭3, 5, ♭7) are intervals measured from the root. \"Minor 7th chord = 1 ♭3 5 ♭7\" means: root, minor 3rd, perfect 5th, minor 7th."}],"guitar":[{"type":"fretboard","root":"A","notes":["A","C","C#","D","E"],"minFret":3,"maxFret":9,"labels":"interval","caption":"Around an A root at fret 5: minor 3rd (C), major 3rd (C♯), perfect 4th (D) and perfect 5th (E)."},{"type":"callout","tone":"tip","text":"Link intervals to songs you know: a perfect 4th opens many wedding marches and anthems; a perfect 5th is the power chord. Your personal song list works best."}],"exercise":{"title":"Interval shapes and sounds","steps":["From an A root (low E, fret 5), play each interval up to the octave on the same string, naming it.","Find the same intervals as cross-string shapes.","Fretboard Trainer → \"Find the interval\"; Ear Training → Intervals level 2."]},"mistakes":["Counting the starting note as zero letters (C to E is a 3rd: C-D-E, three letters).","Forgetting the G–B shift on cross-string shapes."],"selfCheck":["I can name any interval up to the octave from its half-step count.","I can find major and minor 3rds and perfect 5ths from any root."],"realWorld":"Improvisers think \"land on the 3rd,\" \"add the ♭7.\" Session players say \"play the 5th.\" Intervals are the shared language.","summary":["Intervals = number (letters) + quality (half steps).","Each has a sound and a shape.","Formulas are intervals from the root."],"next":"l3-major-scale","mastery":{"quizPass":0.8,"criteria":["Score at least 80%, including generated interval questions.","Find any interval from a given root on the fretboard."]},"unlocks":{"trainerModes":["interval-find","interval-id"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
