insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l3-major-scale', 'm3-intervals', 3, 'The major scale: formula and degrees', 30, array['Build a major scale from the formula W W H W W W H', 'Number scale degrees 1–7', 'Play the major scale on one string and in one position']::text[], array['l3-intervals']::text[], array['theory', 'scales']::text[], '[{"book":"D","section":"Why just the major scale?"},{"book":"C","section":"Book 3 builds on the major scale introduced in Book Two"},{"book":"P","note":"Scale construction"}]'::jsonb, '{"quizPass":0.8,"practice":{"exerciseId":"ex-major-scale-pos","bpm":80},"criteria":["Score at least 80%, including generated scale-spelling questions.","Log a clean take of the one-position major scale at 80 bpm."]}'::jsonb, 25) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l3-major-scale', '{"id":"l3-major-scale","level":3,"module":"m3-intervals","title":"The major scale: formula and degrees","minutes":30,"objectives":["Build a major scale from the formula W W H W W W H","Number scale degrees 1–7","Play the major scale on one string and in one position"],"prerequisites":["l3-intervals"],"categories":["theory","scales"],"sources":[{"book":"D","section":"Why just the major scale?"},{"book":"C","section":"Book 3 builds on the major scale introduced in Book Two"},{"book":"P","note":"Scale construction"}],"why":"The major scale is the reference for nearly all Western theory. Every other scale, chord and mode is described as a variation of it, which is exactly Pillitiere''s point.","explanation":[{"type":"p","text":"A major scale has seven notes built from a fixed pattern of steps: whole, whole, half, whole, whole, whole, half (W W H W W W H). Start on any note, follow the pattern, and you get that note''s major scale. From C: C D E F G A B C, the only major scale with no sharps or flats."},{"type":"p","text":"The notes are numbered as scale degrees 1 to 7 (the 8th is the octave, 1 again). Degree 1 is the tonic: home. Each degree has a role: 3 makes the scale major, 5 is strong and stable, 7 (the leading tone) pulls up to 1."},{"type":"table","head":["Degree","1","2","3","4","5","6","7","8"],"rows":[["C major","C","D","E","F","G","A","B","C"],["G major","G","A","B","C","D","E","F♯","G"],["Step to next","W","W","H","W","W","W","H",""]]},{"type":"callout","tone":"source","text":"Pillitiere argues that you only need to truly study the major scale: natural minor and all the modes are the same notes started from a different degree. This academy follows that approach through Levels 6 and 7."}],"guitar":[{"type":"tab","ascii":"G|---------------------------------------------|\nD|---------------------------------------------|\nA|---------------------------------------------|\nE|-8---10---12---13---15---17---19---20--------|\n   C    D    E    F    G    A    B    C","caption":"C major on one string: see the W W H W W W H spacing as frets."},{"type":"fretboard","root":"C","scale":"major","minFret":7,"maxFret":11,"labels":"degree","caption":"C major in one position (root on the low E, 8th fret), labelled by degree."}],"exercise":{"title":"Build, play, hear","steps":["Build G, D and F major on paper from the formula.","Play C major on one string, then in the one-position shape above with alternate picking.","Sing \"1-2-3-4-5-6-7-8\" as you play."],"exerciseId":"ex-major-scale-pos"},"metronome":{"bpmStart":60,"bpmTarget":100,"subdivision":2,"instructions":"Eighth notes, ascending and descending."},"mistakes":["Misplacing the half steps (they fall between degrees 3–4 and 7–8).","Using both a sharp and a natural of one letter in a scale."],"selfCheck":["I can build any major scale from the formula.","I can play C major in one position cleanly."],"realWorld":"Most pop, rock and country melodies are major-scale melodies. Knowing the degrees lets you hear and describe them (\"it goes 3-2-1\").","summary":["W W H W W W H from any root.","Degrees 1–7 name each note''s role.","Every other scale is described relative to major."],"next":"l3-keys","mastery":{"quizPass":0.8,"practice":{"exerciseId":"ex-major-scale-pos","bpm":80},"criteria":["Score at least 80%, including generated scale-spelling questions.","Log a clean take of the one-position major scale at 80 bpm."]},"unlocks":{"scales":["major"],"trainerModes":["degree-id"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
