insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l3-keys', 'm3-keys', 3, 'Keys, key signatures and the circle of fifths', 25, array['Explain what a key is', 'Find the number of sharps or flats in any major key', 'Use the circle of fifths']::text[], array['l3-major-scale']::text[], array['theory']::text[], '[{"book":"P","note":"Key signatures and the circle of fifths"}]'::jsonb, '{"quizPass":0.8,"criteria":["Score at least 80%, including generated key-signature questions."]}'::jsonb, 26) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l3-keys', '{"id":"l3-keys","level":3,"module":"m3-keys","title":"Keys, key signatures and the circle of fifths","minutes":25,"objectives":["Explain what a key is","Find the number of sharps or flats in any major key","Use the circle of fifths"],"prerequisites":["l3-major-scale"],"categories":["theory"],"sources":[{"book":"P","note":"Key signatures and the circle of fifths"}],"why":"Songs are in keys. The key tells you which notes and chords belong, which scale to solo with, and how to transpose to suit a singer.","explanation":[{"type":"p","text":"A key is a home note (tonic) plus the scale built on it. A song \"in G major\" mostly uses the seven notes of G major and the chords built from them. The key signature lists the sharps or flats of that scale."},{"type":"p","text":"The circle of fifths arranges keys so that each step clockwise moves up a perfect 5th and adds one sharp: C (0) → G (1♯) → D (2) → A (3) → E (4) → B (5) → F♯ (6). Counter-clockwise moves up a perfect 4th and adds one flat: C → F (1♭) → B♭ (2) → E♭ (3) → A♭ (4) → D♭ (5) → G♭ (6)."},{"type":"list","items":["Order of sharps: F C G D A E B (\"Father Charles Goes Down And Ends Battle\").","Order of flats: B E A D G C F (the same words backward).","Neighbouring keys on the circle share six of seven notes, which is why songs often move between them."]},{"type":"callout","tone":"theory","text":"On the guitar, moving a scale shape up 7 frets (or down 5) moves one step clockwise on the circle. Same shape, new key."}],"guitar":[{"type":"p","text":"Play the C major position shape from the previous lesson, then slide the identical shape up two frets to D major, and up two more to E major. Count the sharps of each key using the circle."}],"exercise":{"title":"Circle drill","steps":["Write the circle of fifths from memory with sharps and flats.","Play the one-position major shape in C, G, D, A and E (move the root on the low E string).","Answer the generated key-signature questions in the mastery check."]},"mistakes":["Mixing sharps and flats in one key signature.","Confusing \"up a 5th\" with \"up 5 frets\" (a 5th is 7 frets)."],"selfCheck":["I can name the key signature of any major key."],"realWorld":"When a singer asks to move a song \"up a step,\" the circle and movable shapes let you transpose in seconds.","summary":["Key = tonic + scale.","Circle of fifths orders keys by sharps and flats.","Movable shapes make transposition easy on guitar."],"next":"l3-relative-minor","mastery":{"quizPass":0.8,"criteria":["Score at least 80%, including generated key-signature questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
