insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l3-relative-minor', 'm3-keys', 3, 'Major and minor tonality: the relative minor', 25, array['Hear the difference between major and minor tonality', 'Find the relative minor of any major key (degree 6)', 'Use one shape for both a major and its relative minor']::text[], array['l3-keys']::text[], array['theory', 'scales']::text[], '[{"book":"C","section":"Music Theory 201: relative minor"},{"book":"D","section":"Two scales out of one key signature"},{"book":"P"}]'::jsonb, '{"quizPass":0.75,"criteria":["Score at least 75%."]}'::jsonb, 27) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l3-relative-minor', '{"id":"l3-relative-minor","level":3,"module":"m3-keys","title":"Major and minor tonality: the relative minor","minutes":25,"objectives":["Hear the difference between major and minor tonality","Find the relative minor of any major key (degree 6)","Use one shape for both a major and its relative minor"],"prerequisites":["l3-keys"],"categories":["theory","scales"],"sources":[{"book":"C","section":"Music Theory 201: relative minor"},{"book":"D","section":"Two scales out of one key signature"},{"book":"P"}],"why":"Major and minor are the two main moods in Western music. Seeing that a major key and its relative minor share every note doubles the use of every shape you learn.","explanation":[{"type":"p","text":"A minor key sounds darker because its scale has a minor 3rd above the tonic. The natural minor scale formula is 1 2 ♭3 4 5 ♭6 ♭7 (steps W H W W H W W)."},{"type":"p","text":"Every major scale contains a minor scale: start on its 6th degree and play the same notes. C major (C D E F G A B) started on A gives A natural minor (A B C D E F G). A minor is the relative minor of C major; C is the relative major of A minor. They share a key signature."},{"type":"p","text":"On the fretboard: from a major root on the low E string, slide down three frets to find its relative minor root. C at fret 8 → A at fret 5. The notes under your fingers do not change, only which one you treat as home."},{"type":"callout","tone":"source","text":"Book 3 introduces this as a soloing shortcut (a G major song can use E minor shapes), and Pillitiere builds his whole method on the \"two scales from one pattern\" idea."}],"guitar":[{"type":"fretboard","root":"C","scale":"major","minFret":4,"maxFret":9,"labels":"note","caption":"C major and A minor share these notes. Play from C (major sound) and from A (minor sound)."},{"type":"callout","tone":"tip","text":"Over a backing track in A minor, the C major shape you already know works perfectly. Just resolve phrases to A instead of C."}],"exercise":{"title":"One shape, two moods","steps":["Play the C major shape starting and ending on C, then the same notes starting and ending on A. Describe the difference.","Find the relative minor of G, D, F and B♭ major.","Open the Jam Lab, choose A minor, and noodle with the C major shape, ending phrases on A."]},"mistakes":["Thinking A minor and C major are different notes.","Ending phrases on C when the backing track is in A minor (it will sound unresolved)."],"selfCheck":["I can find the relative minor of any major key, on paper and on the neck."],"realWorld":"Rock and metal live in minor keys; pop often in major. Many songs blend both, and the relative relationship is why that sounds smooth.","summary":["Minor = ♭3 above the tonic.","Relative minor = degree 6 of the major key.","Same notes, different home."],"next":"l3-triads","mastery":{"quizPass":0.75,"criteria":["Score at least 75%."]},"unlocks":{"scales":["aeolian"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
