insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l3-diatonic-chords', 'm3-harmony', 3, 'Diatonic chords, chord numbers and progressions', 30, array['Build the seven diatonic triads of a major key', 'Use Roman numerals and the Nashville number system', 'Recognise common progressions in any key']::text[], array['l3-triads', 'l3-keys']::text[], array['theory', 'chords']::text[], '[{"book":"C","section":"Music Theory 201: chord numbers and the Nashville system"},{"book":"P","note":"Diatonic harmony"}]'::jsonb, '{"quizPass":0.8,"criteria":["Score at least 80%, including generated diatonic-chord questions."]}'::jsonb, 29) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l3-diatonic-chords', '{"id":"l3-diatonic-chords","level":3,"module":"m3-harmony","title":"Diatonic chords, chord numbers and progressions","minutes":30,"objectives":["Build the seven diatonic triads of a major key","Use Roman numerals and the Nashville number system","Recognise common progressions in any key"],"prerequisites":["l3-triads","l3-keys"],"categories":["theory","chords"],"sources":[{"book":"C","section":"Music Theory 201: chord numbers and the Nashville system"},{"book":"P","note":"Diatonic harmony"}],"why":"Most songs use chords from one key. Knowing the seven chords of each key means you can predict chords, learn songs by number and transpose instantly.","explanation":[{"type":"p","text":"Stack thirds on each degree of a major scale, using only notes from that scale, and you get seven diatonic triads. In every major key the qualities follow the same pattern:"},{"type":"table","head":["Degree","I","ii","iii","IV","V","vi","vii°"],"rows":[["Quality","Major","minor","minor","Major","Major","minor","dim"],["C major","C","Dm","Em","F","G","Am","B°"],["G major","G","Am","Bm","C","D","Em","F♯°"]],"caption":"Uppercase = major, lowercase = minor, ° = diminished."},{"type":"p","text":"Roman numerals (or plain numbers in the Nashville system) describe chords by position rather than name. \"I–vi–IV–V\" is C–Am–F–G in C, or A–F♯m–D–E in A. Musicians use numbers to communicate progressions in any key."},{"type":"p","text":"Chords have functions. I is home (tonic). IV moves away (subdominant). V creates tension that wants to return home (dominant). vi often substitutes for I; ii often leads to V."},{"type":"list","items":["I–IV–V: rock, blues, country.","I–V–vi–IV: the most common pop progression.","ii–V–I: the core of jazz.","I–vi–IV–V: 1950s \"doo-wop\"."]}],"guitar":[{"type":"chord","symbols":["G","Am","Bm","C","D","Em"],"caption":"The diatonic chords of G major you can already play (F♯° is rarely used)."},{"type":"p","text":"Play I–V–vi–IV in G (G–D–Em–C), then in C (C–G–Am–F, using a mini-F: xx3211) and in D (D–A–Bm–G)."}],"exercise":{"title":"Numbers to chords","steps":["Write the diatonic chords of D and A major.","Play I–IV–V–I and I–V–vi–IV in G, C and D.","In the Jam Lab, select each progression preset and watch the chord names update when you change key."]},"mistakes":["Making every chord major.","Forgetting that the numbers stay the same when the key changes."],"selfCheck":["I can name the diatonic chords of any major key.","I can play I–V–vi–IV in three keys."],"realWorld":"In studios and jam sessions, \"it''s a 1-5-6-4 in E\" is a complete instruction. With this lesson you can follow it.","summary":["Seven diatonic triads: I ii iii IV V vi vii°.","Numbers describe progressions in any key.","Tonic, subdominant and dominant functions."],"next":"l4-tempo-time","mastery":{"quizPass":0.8,"criteria":["Score at least 80%, including generated diatonic-chord questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
