insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l4-tempo-time', 'm4-time', 4, 'Tempo, BPM and time signatures', 20, array['Relate BPM to beat length', 'Count 4/4, 3/4, 6/8, 12/8 and odd meters', 'Distinguish simple from compound meter']::text[], array['l1-timing']::text[], array['rhythm', 'theory']::text[], '[{"book":"A","section":"4/4 and 3/4 time"},{"book":"C","section":"5/4, 6/8, 7/4, 12/8 and changing meters"},{"book":"P"}]'::jsonb, '{"quizPass":0.75,"criteria":["Score at least 75%."]}'::jsonb, 30) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l4-tempo-time', '{"id":"l4-tempo-time","level":4,"module":"m4-time","title":"Tempo, BPM and time signatures","minutes":20,"objectives":["Relate BPM to beat length","Count 4/4, 3/4, 6/8, 12/8 and odd meters","Distinguish simple from compound meter"],"prerequisites":["l1-timing"],"categories":["rhythm","theory"],"sources":[{"book":"A","section":"4/4 and 3/4 time"},{"book":"C","section":"5/4, 6/8, 7/4, 12/8 and changing meters"},{"book":"P"}],"why":"Time signatures tell you how the music is grouped, and therefore where the strong beats are. Feeling the groupings is the difference between playing notes and playing music.","explanation":[{"type":"p","text":"Tempo is the speed of the beat in beats per minute (BPM). At 120 BPM there are two beats per second. Tempo markings also have names: largo (slow), andante (walking), moderato, allegro (fast), presto (very fast)."},{"type":"p","text":"Simple meters divide each beat into two: 2/4, 3/4, 4/4. Compound meters divide each beat into three: 6/8 (two beats of three eighths), 9/8, 12/8 (four beats of three eighths). Slow blues is often in 12/8: counted \"1-2-3, 2-2-3, 3-2-3, 4-2-3\"."},{"type":"p","text":"Odd meters such as 5/4 and 7/8 group beats unevenly: 5/4 often feels 3+2, 7/8 often 2+2+3. Progressive rock and metal use them constantly, as do some classic rock riffs."},{"type":"table","head":["Meter","Feels like","Count"],"rows":[["4/4","4 beats, each split in 2","1 + 2 + 3 + 4 +"],["3/4","3 beats (waltz)","1 + 2 + 3 +"],["6/8","2 beats, each split in 3","1 2 3 4 5 6"],["12/8","4 beats, each split in 3","1 2 3 2 2 3 3 2 3 4 2 3"],["5/4","3 + 2","1 2 3 4 5"],["7/8","2 + 2 + 3","1 2 1 2 1 2 3"]]}],"guitar":[{"type":"p","text":"Use the metronome presets: \"3/4 waltz\", \"12/8 slow blues\", \"5/4\" and \"7/8 (2+2+3)\". Strum an E minor chord on every accented click, then on every click."},{"type":"callout","tone":"tip","text":"Tap your foot on the beat and nod on the accents. Feeling meter in the body is faster than counting alone."}],"exercise":{"title":"Meter tour","steps":["Strum quarter notes in 4/4, then 3/4, accenting beat 1.","Play 12/8 with the triplet subdivision: strum on 1 of each group, then all three.","Play a 7/8 pattern accenting 1, 3 and 5 (2+2+3)."]},"mistakes":["Treating 6/8 like 3/4 (6/8 has two strong beats, 3/4 has three).","Rushing the long group in odd meters."],"selfCheck":["I can feel and count 12/8 against a metronome.","I can play a 7/8 groove without losing my place."],"realWorld":"Slow blues in 12/8, folk in 6/8, prog in 7/8: recognising meter lets you lock in with a band in seconds.","summary":["BPM sets beat length.","Simple = beats split in 2; compound = split in 3.","Odd meters group unevenly."],"next":"l4-subdivisions","mastery":{"quizPass":0.75,"criteria":["Score at least 75%."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l4t-1', 'l4-tempo-time', 'At 90 BPM, how long is one beat?', '["0.5 s","0.667 s","0.9 s","1.5 s"]'::jsonb, 1, '60 / 90 ≈ 0.667 seconds.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
