insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l5-pentatonic-positions', 'm5-pentatonic', 5, 'Five positions, connecting them, and the major pentatonic', 35, array['Play all five pentatonic positions in one key', 'Connect positions with slides', 'Use the same shapes as the major pentatonic of the relative major']::text[], array['l5-minor-pentatonic']::text[], array['scales', 'fretboard']::text[], '[{"book":"P","note":"Five-position pentatonic system"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Play all five positions of A minor pentatonic from memory."]}'::jsonb, 36) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l5-pentatonic-positions', '{"id":"l5-pentatonic-positions","level":5,"module":"m5-pentatonic","title":"Five positions, connecting them, and the major pentatonic","minutes":35,"objectives":["Play all five pentatonic positions in one key","Connect positions with slides","Use the same shapes as the major pentatonic of the relative major"],"prerequisites":["l5-minor-pentatonic"],"categories":["scales","fretboard"],"sources":[{"book":"P","note":"Five-position pentatonic system"}],"why":"One box limits you to one area of the neck. Five connected positions let you play anywhere, and each position highlights different notes and licks.","explanation":[{"type":"p","text":"Each pentatonic position starts on the next scale note on the low E string. In A minor: position 1 starts on A (fret 5), position 2 on C (fret 8), 3 on D (fret 10), 4 on E (fret 12), 5 on G (fret 15), then position 1 repeats at fret 17 (or 5 an octave lower)."},{"type":"p","text":"The positions overlap: the upper notes of one box are the lower notes of the next. Slide along one string to move between them."},{"type":"p","text":"Major pentatonic: 1 2 3 5 6. C major pentatonic (C D E G A) has exactly the same notes as A minor pentatonic, the relative relationship again. Position 2 of A minor is position 1 of C major. What changes is which note you treat as home."},{"type":"fretboard","root":"A","scale":"minor-pentatonic","minFret":0,"maxFret":17,"labels":"interval","caption":"A minor pentatonic across the neck: five interlocking positions."}],"guitar":[{"type":"tab","ascii":"e|-------------------------------------|\nB|-------------------------------------|\nG|-------------5-7-9/12-9-7------------|\nD|-------5-7-10----------10-7-5--------|\nA|-5-7-------------------------7-5-----|\nE|-------------------------------------|","caption":"Moving from position 1 into position 3/4 with a slide on the G string."}],"exercise":{"title":"Map the neck","steps":["Learn each position slowly, naming its starting degree.","Play one octave of the scale moving diagonally through three positions.","Over a C major Jam Lab track, use the same shapes and resolve to C.","Fretboard Trainer: chord tones and degree modes in A minor."]},"mistakes":["Learning the shapes but never connecting them.","Forgetting that the root changes when you switch to major pentatonic."],"selfCheck":["I can play all five positions in A minor and in E minor.","I can move between positions mid-phrase."],"realWorld":"Country and Southern rock lean on the major pentatonic; rock and blues on the minor. Many players mix both in one solo.","summary":["Five positions start on the five scale notes.","Positions overlap; slide between them.","Same shapes, different root = major pentatonic."],"next":"l5-bends-vibrato","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Play all five positions of A minor pentatonic from memory."]},"unlocks":{"scales":["major-pentatonic"],"challenges":["connect-positions"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
