insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l5-bends-vibrato', 'm5-expression', 5, 'String bending and vibrato', 30, array['Bend a half step and a whole step in tune', 'Release bends in control', 'Apply even, controlled vibrato']::text[], array['l5-minor-pentatonic']::text[], array['technique']::text[], '[{"book":"C","section":"Double-stop bend, pre-bend, bends in blues licks"},{"book":"B","section":"Bends and vibrato in solos"},{"book":"P","note":"Bending technique"}]'::jsonb, '{"quizPass":0.67,"practice":{"exerciseId":"ex-bend-pitch"},"criteria":["Score at least 2 of 3.","Log a clean bend exercise take (bends in tune)."]}'::jsonb, 37) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l5-bends-vibrato', '{"id":"l5-bends-vibrato","level":5,"module":"m5-expression","title":"String bending and vibrato","minutes":30,"objectives":["Bend a half step and a whole step in tune","Release bends in control","Apply even, controlled vibrato"],"prerequisites":["l5-minor-pentatonic"],"categories":["technique"],"sources":[{"book":"C","section":"Double-stop bend, pre-bend, bends in blues licks"},{"book":"B","section":"Bends and vibrato in solos"},{"book":"P","note":"Bending technique"}],"why":"Bends and vibrato turn a guitar into a voice. They are the most expressive tools in lead guitar, and in-tune bends are a mark of a skilled player.","explanation":[{"type":"p","text":"A bend pushes the string across the fretboard to raise its pitch. A half-step bend raises it by one fret''s worth, a whole-step (full) bend by two frets. Use several fingers together: for a ring-finger bend, place fingers 1 and 2 behind it on the same string and push with all three."},{"type":"p","text":"The power comes from rotating the wrist (like turning a door handle), not from pushing with the fingers alone. Hook the thumb over the neck for leverage when bending."},{"type":"p","text":"Vibrato is a repeated small bend and release that makes a held note sing. Aim for an even speed and width that fits the tempo; a wide, slow vibrato for blues, faster and narrower for rock and metal."},{"type":"callout","tone":"warning","text":"Mute the strings you are not playing. When you bend, the fretting hand''s spare fingers and the picking hand should keep neighbouring strings silent."},{"type":"callout","tone":"theory","text":"Check bend accuracy with the tuner: play fret 9 on the G string (E), note its pitch, then bend fret 7 up until it reads E."}],"guitar":[{"type":"tab","ascii":"e|----------------------------------|\nB|-8---8b10---8b10r8---8~~~~--------|\nG|-------------------------7b9~~----|\nD|----------------------------------|","caption":"Target note, full bend to it, bend and release, vibrato; then a full bend with vibrato on the G string."}],"exercise":{"title":"In-tune bends","steps":["Play the target note (B string fret 10), then bend fret 8 up to match it. Repeat 10 times.","Use the tuner to check: the bent note should read the target pitch.","Hold a note with vibrato for 4 beats at 70 BPM: one vibrato cycle per beat, then two per beat."],"exerciseId":"ex-bend-pitch"},"metronome":{"bpmStart":60,"bpmTarget":90,"subdivision":1,"instructions":"Synchronise vibrato cycles with the beat."},"mistakes":["Under-bending (flat bends are the most common error).","Bending with one finger only.","Nervous, uneven vibrato.","Letting neighbouring strings ring during bends."],"selfCheck":["My full bends reach pitch within 10 cents on the tuner.","My vibrato is even and in time."],"realWorld":"Blues greats are known for their vibrato and bends. A single well-bent note can say more than a fast run.","summary":["Bend with the wrist and several fingers.","Check bends against the target pitch.","Even, deliberate vibrato."],"next":"l5-legato","mastery":{"quizPass":0.67,"practice":{"exerciseId":"ex-bend-pitch"},"criteria":["Score at least 2 of 3.","Log a clean bend exercise take (bends in tune)."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l5b-1', 'l5-bends-vibrato', 'A full (whole-step) bend raises the pitch by…', '["1 fret","2 frets","3 frets","12 frets"]'::jsonb, 1, 'A whole step = two semitones.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
