insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l5b-3', 'l5-bends-vibrato', '"7b9r7" means…', '["Play frets 7, 9 and 7","Bend 7 to the pitch of 9, then release back to 7","Slide 7 to 9","Vibrato on 7"]'::jsonb, 1, 'b = bend, r = release.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l5-legato', 'm5-expression', 5, 'Hammer-ons, pull-offs, slides and legato phrasing', 30, array['Play clear hammer-ons and pull-offs', 'Slide accurately to target notes', 'Combine legato with picking for smooth phrases']::text[], array['l5-minor-pentatonic']::text[], array['technique']::text[], '[{"book":"A","section":"Legato: hammer-on, pull-off, slides"},{"book":"C","section":"Trills"},{"book":"P"}]'::jsonb, '{"quizPass":0.67,"practice":{"exerciseId":"ex-legato-hp","bpm":80},"criteria":["Score at least 2 of 3.","Log a clean legato take at 80 bpm."]}'::jsonb, 38) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l5-legato', '{"id":"l5-legato","level":5,"module":"m5-expression","title":"Hammer-ons, pull-offs, slides and legato phrasing","minutes":30,"objectives":["Play clear hammer-ons and pull-offs","Slide accurately to target notes","Combine legato with picking for smooth phrases"],"prerequisites":["l5-minor-pentatonic"],"categories":["technique"],"sources":[{"book":"A","section":"Legato: hammer-on, pull-off, slides"},{"book":"C","section":"Trills"},{"book":"P"}],"why":"Legato connects notes without picking each one, giving a smooth, vocal sound and freeing the picking hand. It is essential for blues phrasing and for fast rock lines later.","explanation":[{"type":"p","text":"Hammer-on: pick a note, then bring another finger down hard and fast on a higher fret of the same string; the impact sounds the new note. Pull-off: with both fingers in place, pick the higher note and flick the finger off sideways (slightly downward), plucking the string to sound the lower note."},{"type":"p","text":"Slides: pick a note and slide the same finger to a new fret without lifting pressure. Slide into a note from below for a vocal swoop; slide out of a note to end a phrase."},{"type":"p","text":"A trill alternates rapidly between two notes with continuous hammer-ons and pull-offs."},{"type":"callout","tone":"tip","text":"Hammer from just above the string with the fingertip, aiming right behind the fret. Volume should match the picked notes."}],"guitar":[{"type":"tab","ascii":"e|-------------------------------------|\nB|-5h8p5-------5h8p5-------------------|\nG|-------7p5-7-------7/9--9\\7-5--------|\nD|-----------------------------7-------|","caption":"A minor pentatonic phrase with hammer-ons, pull-offs and slides."}],"exercise":{"title":"Legato control","steps":["Trill frets 5 and 7 on the G string for 10 seconds; then 5 and 8.","Play the phrase above, matching the volume of legato and picked notes.","Technique Lab: legato trills and hammer-pull drills."],"exerciseId":"ex-legato-hp"},"metronome":{"bpmStart":60,"bpmTarget":100,"subdivision":3,"instructions":"Triplets suit hammer-pull groups."},"mistakes":["Weak hammer-ons that are much quieter than picked notes.","Pull-offs that lift straight up and make no sound.","Unwanted strings ringing during pull-offs."],"selfCheck":["My legato notes are as loud as picked notes.","I can trill evenly for 10 seconds."],"realWorld":"Blues phrasing relies on slides and pull-offs; rock and metal shred uses long legato runs.","summary":["Hammer-ons and pull-offs sound notes without picking.","Slides connect positions vocally.","Match legato and picked volume."],"next":"l5-12-bar-blues","mastery":{"quizPass":0.67,"practice":{"exerciseId":"ex-legato-hp","bpm":80},"criteria":["Score at least 2 of 3.","Log a clean legato take at 80 bpm."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
