insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l5-12-bar-blues', 'm5-blues', 5, 'The 12-bar blues, the blues scale and turnarounds', 35, array['Play the standard and quick-change 12-bar forms with dominant 7th chords', 'Use the blues scale and its ♭5 blue note', 'Play a turnaround in the last two bars']::text[], array['l3-diatonic-chords', 'l5-minor-pentatonic', 'l1-riffs']::text[], array['chords', 'scales', 'repertoire']::text[], '[{"book":"C","section":"12-bar blues: standard form, quick change, blues scale, licks, turnarounds, call and response"},{"book":"P"}]'::jsonb, '{"quizPass":0.75,"practice":{"exerciseId":"ex-12bar-comp","bpm":90},"criteria":["Score at least 75%.","Log a clean take of the 12-bar comping exercise at 90 bpm."]}'::jsonb, 39) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l5-12-bar-blues', '{"id":"l5-12-bar-blues","level":5,"module":"m5-blues","title":"The 12-bar blues, the blues scale and turnarounds","minutes":35,"objectives":["Play the standard and quick-change 12-bar forms with dominant 7th chords","Use the blues scale and its ♭5 blue note","Play a turnaround in the last two bars"],"prerequisites":["l3-diatonic-chords","l5-minor-pentatonic","l1-riffs"],"categories":["chords","scales","repertoire"],"sources":[{"book":"C","section":"12-bar blues: standard form, quick change, blues scale, licks, turnarounds, call and response"},{"book":"P"}],"why":"The 12-bar blues is the most important song form a guitarist can know. It underlies blues, rock''n''roll, much of rock and jazz, and is the default jam-session form.","explanation":[{"type":"p","text":"The 12-bar blues uses the I, IV and V chords of a key, usually as dominant 7ths (I7, IV7, V7). In A: A7, D7, E7. The standard form is:"},{"type":"table","head":["Bars 1–4","Bars 5–8","Bars 9–12"],"rows":[["I7 | I7 | I7 | I7","IV7 | IV7 | I7 | I7","V7 | IV7 | I7 | V7"]]},{"type":"p","text":"The quick change moves to IV7 in bar 2 and back to I7 in bar 3. The final bar''s V7 (the turnaround) leads back to the top of the form; a turnaround lick in bars 11–12 signals that the form is repeating."},{"type":"p","text":"The blues scale adds one note to the minor pentatonic, the ♭5: 1 ♭3 4 ♭5 5 ♭7 (A C D E♭ E G). The ♭5 is a \"blue note\": a passing tone with a crying sound. Slide or bend through it rather than sitting on it."},{"type":"callout","tone":"source","text":"Book 3 presents the standard and quick-change forms, the blues scale, four \"must-know\" licks and two turnarounds tied to specific bars of the form. The examples below are original."},{"type":"chord","symbols":["A7","D7","E7"],"caption":"Dominant 7th chords for a blues in A."}],"guitar":[{"type":"tab","ascii":"e|-----------------------------------|\nB|-----------------------------------|\nG|-------------------------5---------|\nD|-----------------5-6-7-------------|\nA|-5-7-----5-6-7---------------------|\nE|-----8-----------------------------|","caption":"Blues-scale phrase in A using the ♭5 (E♭) as a passing note."},{"type":"tab","ascii":"     A7                         E7\ne|-5---4---3---2-------|---------------|\nB|-5---5---5---5-------|---------------|\nG|---------------2-1-0-|-1-------------|\nD|---------------------|-0-------------|\nA|---------------------|---------------|\nE|---------------------|-0-------------|","caption":"An original descending turnaround for bars 11–12 in A, landing on E7."}],"exercise":{"title":"Play the form","steps":["Play the 12-bar in A with A7–D7–E7, one strum per beat, counting bars aloud.","Play the boogie riff from Level 1 through the whole form.","Over the Jam Lab \"12-bar blues\" (Blues shuffle style), solo with the blues scale and add the turnaround in bars 11–12."],"exerciseId":"ex-12bar-comp"},"metronome":{"bpmStart":70,"bpmTarget":110,"subdivision":2,"instructions":"Use the shuffle preset."},"mistakes":["Losing your place in the form (count bars!).","Sitting on the ♭5 instead of passing through it.","Forgetting the turnaround."],"selfCheck":["I can play the 12-bar form in A and E without losing my place.","I can use the ♭5 musically."],"realWorld":"At any blues jam someone will call \"blues in A, shuffle.\" After this lesson you can join in.","summary":["I7–IV7–V7 over 12 bars.","Blues scale adds the ♭5 blue note.","Turnarounds lead back to the top."],"next":"l5-blues-phrasing","mastery":{"quizPass":0.75,"practice":{"exerciseId":"ex-12bar-comp","bpm":90},"criteria":["Score at least 75%.","Log a clean take of the 12-bar comping exercise at 90 bpm."]},"unlocks":{"scales":["blues"],"chords":["A7","D7","E7","B7"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
