insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l5-blues-phrasing', 'm5-blues', 5, 'Blues improvisation: call and response and phrase construction', 35, array['Build phrases with a beginning, middle and end', 'Use call and response', 'Leave space and repeat ideas']::text[], array['l5-12-bar-blues', 'l5-bends-vibrato', 'l5-legato']::text[], array['improvisation', 'jamming']::text[], '[{"book":"C","section":"Call and response between vocal and guitar"},{"book":"D","section":"Practice: improvise regularly, with others or a recording"},{"book":"P","note":"Phrasing pedagogy"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Complete the Jam Lab \"four-bar question-and-answer\" challenge."]}'::jsonb, 40) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l5-blues-phrasing', '{"id":"l5-blues-phrasing","level":5,"module":"m5-blues","title":"Blues improvisation: call and response and phrase construction","minutes":35,"objectives":["Build phrases with a beginning, middle and end","Use call and response","Leave space and repeat ideas"],"prerequisites":["l5-12-bar-blues","l5-bends-vibrato","l5-legato"],"categories":["improvisation","jamming"],"sources":[{"book":"C","section":"Call and response between vocal and guitar"},{"book":"D","section":"Practice: improvise regularly, with others or a recording"},{"book":"P","note":"Phrasing pedagogy"}],"why":"Knowing scales is not the same as improvising. Musical solos are made of phrases, like sentences in conversation. This lesson turns the pentatonic box into a language.","explanation":[{"type":"p","text":"A phrase is a short musical sentence, usually one or two bars, followed by a breath (rest). Build each phrase with intent: start somewhere, go somewhere, end on a strong note (often the root, or the 3rd or 5th of the current chord)."},{"type":"p","text":"Call and response: play a short phrase (the call), then answer it with a related phrase (the response). Blues singers and guitarists trade lines this way. The response can repeat the call''s rhythm with different notes, or end it differently."},{"type":"list","items":["Repeat: play an idea twice. Repetition makes solos memorable.","Space: rest as long as you played. Silence lets ideas land.","Target: land on the root when the I chord returns, or on the chord''s 3rd.","Dynamics: start quieter, build intensity toward the end of the chorus."]},{"type":"callout","tone":"tip","text":"Limit yourself. Two-note solos, one-string solos, or rhythm-only variations force creativity and break the \"run up and down the box\" habit."}],"guitar":[{"type":"tab","ascii":"         call                response\ne|-----------------|-----------------|\nB|-8b10---8-5------|-8b10---8--5-----|\nG|------------7----|-----------------|\nD|-----------------|------------7~~~-|","caption":"An original call and response. The call ends on D (the 4th, unresolved); the response ends on A, the root, with vibrato."}],"exercise":{"title":"Conversation in A","steps":["Over a 12-bar shuffle in A, play a one-bar call, rest for one bar, then answer it.","Play a full chorus using only three notes.","Complete the Jam Lab challenge \"Build a four-bar question-and-answer phrase\"."]},"mistakes":["Playing constantly without rests.","Ignoring the chord changes entirely.","Never repeating an idea."],"selfCheck":["My solos contain clear phrases with rests.","I can play a call and answer it."],"realWorld":"Many of the most loved blues solos use few notes but strong phrasing. Audiences remember melodies, not speed.","summary":["Phrases are musical sentences.","Call and response creates dialogue.","Repeat, leave space, target strong notes."],"next":"l6-pillitiere-shapes","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Complete the Jam Lab \"four-bar question-and-answer\" challenge."]},"unlocks":{"challenges":["four-bar-phrase"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l5c-1', 'l5-blues-phrasing', 'In call and response, the response…', '["Ignores the call","Answers the call with a related phrase","Is always faster","Must use different notes and rhythm"]'::jsonb, 1, 'The answer relates to the call, often by rhythm or contour.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l5c-2', 'l5-blues-phrasing', 'Why leave space in a solo?', '["To rest your hands only","It lets phrases breathe and land, like pauses in speech","Because the scale has gaps","It is not recommended"]'::jsonb, 1, 'Silence gives structure and impact.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l5c-3', 'l5-blues-phrasing', 'A strong note to end a phrase over the I chord is…', '["The ♭5","The root","A note a half step above a chord tone","The 4th"]'::jsonb, 1, 'The root (or the 3rd or 5th) sounds resolved.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l6-pillitiere-shapes', 'm6-pillitiere', 6, 'Three shapes, one system: X, Y and Z', 35, array['Explain why three notes per string gives consistent fingering', 'Recognise Pillitiere''s three per-string shapes X, Y and Z', 'Know the 7-string shape cycle X X X Y Y Z Z']::text[], array['l3-relative-minor', 'l5-pentatonic-positions']::text[], array['scales', 'fretboard', 'theory']::text[], '[{"book":"D","section":"Starting out; finger shapes; horizontal order of shapes"},{"book":"P","note":"Three-notes-per-string fingering"}]'::jsonb, '{"quizPass":0.75,"practice":{"exerciseId":"ex-alt-3nps","bpm":80},"criteria":["Score at least 75%, including generated shape questions.","Log a clean 3NPS take at 80 bpm."]}'::jsonb, 41) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l6-pillitiere-shapes', '{"id":"l6-pillitiere-shapes","level":6,"module":"m6-pillitiere","title":"Three shapes, one system: X, Y and Z","minutes":35,"objectives":["Explain why three notes per string gives consistent fingering","Recognise Pillitiere''s three per-string shapes X, Y and Z","Know the 7-string shape cycle X X X Y Y Z Z"],"prerequisites":["l3-relative-minor","l5-pentatonic-positions"],"categories":["scales","fretboard","theory"],"sources":[{"book":"D","section":"Starting out; finger shapes; horizontal order of shapes"},{"book":"P","note":"Three-notes-per-string fingering"}],"why":"Scale books often show dozens of unrelated diagrams. Pillitiere shows that every diatonic 3NPS pattern is built from just three finger shapes in a fixed order. Learn the system and you can build any pattern instead of memorising it.","explanation":[{"type":"p","text":"Three notes per string (3NPS) means every string gets exactly three consecutive scale notes. Each string then needs the same kind of hand position, and the picking hand repeats a predictable pattern. Pillitiere suggests consistent fingering for both hands; with a pick, this translates naturally into strict alternate or economy picking."},{"type":"p","text":"A major scale is made of whole steps and half steps. Three consecutive notes can only be spaced in three ways, and those are the three shapes:"},{"type":"table","head":["Shape","Steps","Frets (relative)","Fingers"],"rows":[["X","whole – whole","0 – 2 – 4","1 – 2 – 4"],["Y","half – whole","0 – 1 – 3","1 – 2 – 4"],["Z","whole – half","0 – 2 – 3","1 – 3 – 4"]]},{"type":"p","text":"Now the key insight. Imagine a guitar with unlimited strings tuned in 4ths. Playing the major scale 3NPS up across them, the shapes always appear in the same repeating order: X X X Y Y Z Z, then X X X again. The cycle is seven strings long because 7 strings × 3 notes = 21 notes = exactly three octaves of the seven-note scale."},{"type":"callout","tone":"theory","text":"Why that order? The three-note group starting on degree 1, 4 or 5 is whole–whole (X); starting on 7 or 3 is half–whole (Y); starting on 6 or 2 is whole–half (Z). Each new string starts four scale steps higher, so the starting degrees run 5, 1, 4, 7, 3, 6, 2, which gives X X X Y Y Z Z."},{"type":"callout","tone":"source","text":"This X/Y/Z model and the cycle come from Michael Pillitiere''s Building the Better Guitar Scale. The app''s theory engine re-derives the cycle mathematically, and an automated test confirms that it reproduces every 3NPS pattern in every key."}],"guitar":[{"type":"p","text":"Play each shape on one string at the 5th fret: X = 5-7-9, Y = 5-6-8, Z = 5-7-8, using the fingers in the table. Then play the six-string pattern below, which shows X X Y Y Z Z, the window of the cycle that starts on degree 1."},{"type":"pillitiere","key":"G","degree":1,"caption":"G major from degree 1 on the low E (fret 3): shapes X X Y Y Z Z."}],"exercise":{"title":"Feel the shapes","steps":["Play X, Y and Z on each string with the stated fingers until the shapes feel distinct.","Play the G major pattern above, saying the shape letter for each string.","Write out the cycle XXXYYZZ from memory and mark the six-string window for degree 1."],"exerciseId":"ex-alt-3nps"},"metronome":{"bpmStart":60,"bpmTarget":100,"subdivision":3,"instructions":"Triplets: one string per beat makes the 3NPS grouping audible."},"mistakes":["Using finger 3 for the top note of X (it is a 4-fret stretch: use finger 4).","Memorising patterns as pictures instead of shape sequences."],"selfCheck":["I can play and name X, Y and Z.","I can recite the cycle X X X Y Y Z Z."],"realWorld":"Fusion and shred players rely on 3NPS fingering for fast scale runs. This system makes every position available without memorising pages of diagrams.","summary":["3NPS gives both hands a consistent pattern.","Three shapes: X (W-W), Y (H-W), Z (W-H).","They cycle X X X Y Y Z Z."],"next":"l6-pillitiere-patterns","mastery":{"quizPass":0.75,"practice":{"exerciseId":"ex-alt-3nps","bpm":80},"criteria":["Score at least 75%, including generated shape questions.","Log a clean 3NPS take at 80 bpm."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l6x-1', 'l6-pillitiere-shapes', 'Shape Y is…', '["whole–whole","half–whole","whole–half","half–half"]'::jsonb, 1, 'Y = half step then whole step (frets 0-1-3).', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l6x-2', 'l6-pillitiere-shapes', 'The repeating 7-string order of shapes is…', '["X Y Z X Y Z X","X X X Y Y Z Z","X X Y Y Z Z Z","Z Z Y Y X X X"]'::jsonb, 1, 'X X X Y Y Z Z.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l6x-3', 'l6-pillitiere-shapes', 'Why does the cycle repeat every seven strings?', '["Guitars have seven strings","7 strings × 3 notes = 21 notes = three full octaves of a 7-note scale","There are seven shapes","It is arbitrary"]'::jsonb, 1, 'After 21 notes the scale starts again on the same degree.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l6x-4', 'l6-pillitiere-shapes', 'Which fingers play shape Z?', '["1-2-4","1-3-4","1-2-3","2-3-4"]'::jsonb, 1, 'Z (whole–half): 1-3-4.', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l6-pillitiere-patterns', 'm6-pillitiere', 6, 'Building every pattern from two facts', 40, array['Apply the two vertical shift rules', 'Build any of the seven patterns from its starting degree and first two shapes', 'Start patterns on the 6th, 5th or 4th string']::text[], array['l6-pillitiere-shapes']::text[], array['scales', 'fretboard']::text[], '[{"book":"D","section":"Vertical order of shapes; building patterns; beginning patterns on different strings; practice"},{"book":"P"}]'::jsonb, '{"quizPass":0.75,"criteria":["Score at least 75%, including generated Pattern Builder questions.","Build three random patterns correctly without help."]}'::jsonb, 42) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l6-pillitiere-patterns', '{"id":"l6-pillitiere-patterns","level":6,"module":"m6-pillitiere","title":"Building every pattern from two facts","minutes":40,"objectives":["Apply the two vertical shift rules","Build any of the seven patterns from its starting degree and first two shapes","Start patterns on the 6th, 5th or 4th string"],"prerequisites":["l6-pillitiere-shapes"],"categories":["scales","fretboard"],"sources":[{"book":"D","section":"Vertical order of shapes; building patterns; beginning patterns on different strings; practice"},{"book":"P"}],"why":"With two shift rules and one small chart, you can construct any major-scale pattern on the spot, in any key, from any string. That is fretboard freedom without memorisation.","explanation":[{"type":"p","text":"The shapes tell you where notes fall within a string. Two rules tell you where the first finger lands on the next string:"},{"type":"list","items":["Rule 1: moving from an X string to a Y string, the first finger moves up one fret.","Rule 2: crossing from the 3rd (G) string to the 2nd (B) string, the first finger moves up one fret, because G–B is a major 3rd instead of a perfect 4th.","Otherwise the first finger stays at the same fret. When both rules apply at once, the shifts add up (two frets)."]},{"type":"p","text":"To build a pattern you need only two facts: which scale degree you start on, and the first two shapes. Everything else follows from the cycle and the rules."},{"type":"table","head":["Start degree","1","2","3","4","5","6","7"],"rows":[["First shapes","XX","ZX","YZ","XY","XXX","ZZ","YY"]],"caption":"Degrees 1 and 5 both begin with X X. Degree 5 begins with three Xs."},{"type":"p","text":"Worked example: G major starting on the 7th fret of the low E string. That note is B, degree 3 of G major, so the pattern begins Y Z, then continues the cycle: Y Z Z X X X. Apply the rules string by string and the whole pattern appears."},{"type":"callout","tone":"theory","text":"The app generalises Rule 2 for other tunings: the first finger shifts by (5 − the interval between the strings in semitones). This is an extension of Pillitiere''s method and is labelled as such in the Scale Explorer."}],"guitar":[{"type":"pillitiere","key":"G","degree":3,"caption":"G major from degree 3 (B at fret 7): Y Z Z X X X. Watch the shifts at G→B and X→Y."},{"type":"pillitiere","key":"C","degree":1,"caption":"C major from degree 1 on the A string (fret 3): the same rules work from any string."},{"type":"callout","tone":"tip","text":"Open the Scale Explorer''s Pattern Builder. Choose a key and starting degree, then step through the strings: it shows each shape and which rule moved the finger."}],"exercise":{"title":"Build it, don''t recall it","steps":["Pick a random key and degree; build the pattern mentally before checking it in the Pattern Builder.","Pillitiere''s drill: choose one note (say A) and play every major scale that contains it, starting from that note, then their relative minors.","Play one scale (C major) in every position from the 6th string, then from the 5th."]},"mistakes":["Forgetting that Rule 1 and Rule 2 can add together (two frets).","Applying Rule 2 at the wrong string pair.","Confusing degree-5 (XXX) with degree-1 (XX) patterns."],"selfCheck":["I can build any pattern from the chart in under 20 seconds.","I can start a pattern on the 5th string."],"realWorld":"When the key changes mid-jam, you can build the new scale wherever your hand already is, instead of jumping back to a memorised box.","summary":["Two shift rules place the shapes vertically.","Start degree + first two shapes = the whole pattern.","Works from any string and any key."],"next":"l6-caged","mastery":{"quizPass":0.75,"criteria":["Score at least 75%, including generated Pattern Builder questions.","Build three random patterns correctly without help."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l6y-1', 'l6-pillitiere-patterns', 'Moving from an X string to a Y string, the first finger…', '["Stays put","Moves up one fret","Moves down one fret","Moves up two frets"]'::jsonb, 1, 'Rule 1: X → Y shifts up one fret.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
