insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l6y-4', 'l6-pillitiere-patterns', 'When moving X → Y AND crossing from G to B, the first finger moves up…', '["0 frets","1 fret","2 frets","3 frets"]'::jsonb, 2, 'The two shifts accumulate.', 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l6-caged', 'm6-systems', 6, 'The CAGED system: chord shapes to scale positions', 35, array['Recognise the C, A, G, E and D chord shapes as movable forms', 'Link each chord shape to a surrounding scale position', 'Compare CAGED with 3NPS']::text[], array['l6-pillitiere-shapes', 'l1-open-chords']::text[], array['scales', 'chords', 'fretboard']::text[], '[{"book":"P","note":"CAGED system"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Play C major in all five CAGED shapes."]}'::jsonb, 43) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l6-caged', '{"id":"l6-caged","level":6,"module":"m6-systems","title":"The CAGED system: chord shapes to scale positions","minutes":35,"objectives":["Recognise the C, A, G, E and D chord shapes as movable forms","Link each chord shape to a surrounding scale position","Compare CAGED with 3NPS"],"prerequisites":["l6-pillitiere-shapes","l1-open-chords"],"categories":["scales","chords","fretboard"],"sources":[{"book":"P","note":"CAGED system"}],"why":"CAGED connects chords, arpeggios and scales in five overlapping zones. It complements 3NPS: 3NPS is ideal for speed and consistency, CAGED for seeing chord tones and playing over changes.","explanation":[{"type":"p","text":"The open chord shapes C, A, G, E and D can each be moved up the neck (the nut replaced by a barre or by your first finger). For any major chord there are five shapes, and in the order C-A-G-E-D they link up the neck, each sharing notes with the next."},{"type":"p","text":"Each chord shape has a scale position around it. Playing the major scale in that position keeps the chord tones under your fingers, which is very useful for soloing over chord changes."},{"type":"table","head":["Shape","Root string","Example (C major)"],"rows":[["C shape","A string (with root also on B)","Open position"],["A shape","A string","Barre at fret 3"],["G shape","Low E string","Around frets 5–8"],["E shape","Low E string","Barre at fret 8"],["D shape","D string","Around frets 10–13"]]},{"type":"callout","tone":"warning","text":"CAGED relies on standard-tuning intervals. In Drop D or open tunings the shapes change; the Scale Explorer hides CAGED when the tuning is not standard-interval."}],"guitar":[{"type":"fretboard","root":"C","scale":"major","minFret":0,"maxFret":15,"labels":"degree","caption":"C major across the neck. In the Scale Explorer, switch to CAGED to see each shape''s chord tones highlighted inside its position."}],"exercise":{"title":"Five shapes, one chord","steps":["Play C major as each of the five shapes, from open position upward.","In each shape, play the surrounding scale position, then the chord.","Repeat for G major."]},"mistakes":["Learning CAGED shapes without connecting them.","Assuming CAGED and 3NPS conflict: they are two views of the same notes."],"selfCheck":["I can play a major chord in all five CAGED shapes."],"realWorld":"Many blues, country and jazz guitarists think in CAGED; many shredders think in 3NPS. Versatile players use both.","summary":["Five movable chord shapes link up the neck.","Each has a matching scale position.","CAGED for harmony, 3NPS for speed."],"next":"l6-minor-scales","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Play C major in all five CAGED shapes."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
