insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l6m-2', 'l6-minor-scales', 'Why use harmonic minor over the V chord in a minor key?', '["It is faster","Its raised 7th is the major 3rd of the V chord","It avoids the root","It has fewer notes"]'::jsonb, 1, 'In A minor, G♯ is the 3rd of E7.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
