insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l6-symmetrical', 'm6-systems', 6, 'Chromatic, whole-tone, diminished and exotic scales', 30, array['Understand symmetrical scales and their repeating structure', 'Know where whole-tone and diminished scales fit harmonically', 'Try a few exotic scales']::text[], array['l6-minor-scales']::text[], array['scales', 'theory']::text[], '[{"book":"P","note":"Symmetrical and exotic scales"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}'::jsonb, 45) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l6-symmetrical', '{"id":"l6-symmetrical","level":6,"module":"m6-systems","title":"Chromatic, whole-tone, diminished and exotic scales","minutes":30,"objectives":["Understand symmetrical scales and their repeating structure","Know where whole-tone and diminished scales fit harmonically","Try a few exotic scales"],"prerequisites":["l6-minor-scales"],"categories":["scales","theory"],"sources":[{"book":"P","note":"Symmetrical and exotic scales"}],"why":"Symmetrical scales add tension and colour that diatonic scales cannot. Their repeating structure also makes them easy to visualise on the guitar.","explanation":[{"type":"p","text":"The chromatic scale uses all 12 notes. It is mainly a technique and passing-tone resource."},{"type":"p","text":"The whole-tone scale (1 2 3 ♯4 ♯5 ♭7) uses only whole steps. Since every step is identical, there are only two different whole-tone scales. It fits augmented and 7♯5 chords and sounds dreamy and unresolved."},{"type":"p","text":"Diminished scales alternate half and whole steps and repeat every minor 3rd (three frets). Half-whole (1 ♭2 ♯2 3 ♯4 5 6 ♭7) fits dominant 7♭9 chords; whole-half fits diminished 7th chords. Any fingering can be moved up three frets and remain the same scale."},{"type":"p","text":"Exotic scales such as Hungarian minor, double harmonic and Hirajōshi bring folk and world colours. Explore them in the Scale Explorer, which shows their formulas, fretboard layout and audio."}],"guitar":[{"type":"fretboard","root":"A","scale":"diminished-hw","minFret":4,"maxFret":10,"labels":"interval","caption":"A half-whole diminished: notice how the pattern repeats every three frets."}],"exercise":{"title":"Colour tour","steps":["Play one octave of C whole-tone; then move it up one fret: that is the other whole-tone scale.","Play A half-whole diminished over an A7 chord in the Jam Lab (choose a one-chord funk vamp).","Audition three exotic scales in the Scale Explorer and describe each in one word."]},"mistakes":["Overusing symmetrical scales so they lose their effect.","Using half-whole over a diminished 7th chord (use whole-half)."],"selfCheck":["I can explain why there are only two whole-tone scales."],"realWorld":"Metal and fusion players use diminished runs for sudden tension; film composers use whole-tone for dream sequences.","summary":["Symmetrical = repeating interval structure.","Whole-tone fits augmented chords; diminished fits 7♭9 and dim7.","Exotic scales bring world colours."],"next":"l6-transposition","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3."]},"unlocks":{"scales":["whole-tone","diminished-hw","diminished-wh","chromatic","hungarian-minor","double-harmonic","hirajoshi"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l6s-1', 'l6-symmetrical', 'How many distinct whole-tone scales are there?', '["1","2","6","12"]'::jsonb, 1, 'Each contains six of the twelve notes; shifting by a half step gives the other six.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
