insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l6-transposition', 'm6-systems', 6, 'Transposition, horizontal movement and connecting the neck', 30, array['Transpose any shape to a new key', 'Move horizontally along strings and vertically across positions', 'Play one scale through the whole neck']::text[], array['l6-pillitiere-patterns', 'l6-caged']::text[], array['scales', 'fretboard']::text[], '[{"book":"D","section":"Patterns tie into one another; play all over the neck"},{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions.","Play a scale through the whole neck without stopping."]}'::jsonb, 46) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l6-transposition', '{"id":"l6-transposition","level":6,"module":"m6-systems","title":"Transposition, horizontal movement and connecting the neck","minutes":30,"objectives":["Transpose any shape to a new key","Move horizontally along strings and vertically across positions","Play one scale through the whole neck"],"prerequisites":["l6-pillitiere-patterns","l6-caged"],"categories":["scales","fretboard"],"sources":[{"book":"D","section":"Patterns tie into one another; play all over the neck"},{"book":"P"}],"why":"Real solos move. Connecting positions lets you take a phrase from the low register to the high register smoothly, and change keys without stopping.","explanation":[{"type":"p","text":"Transposing a movable shape is simple: move the root and everything moves with it. Up 2 frets = up a whole step; up 5 frets = up a 4th; up 7 frets = up a 5th."},{"type":"p","text":"Vertical playing stays in one position and moves across strings. Horizontal playing moves along the strings, often two or three strings at a time, using slides or shifts. Diagonal runs combine both, for example climbing 3NPS patterns one string set at a time."},{"type":"p","text":"Pillitiere points out that patterns interlock: the top two strings of one pattern are the bottom of another. Practise the \"one scale, every position\" drill until any position is reachable from any other."}],"guitar":[{"type":"tab","ascii":"e|--------------------------------7-8-10-12-|\nB|-------------------------6-8-10-----------|\nG|-------------------5-7-9------------------|\nD|-------------5-7-9------------------------|\nA|-------5-7-8------------------------------|\nE|-5-7-8------------------------------------|","caption":"An original diagonal A natural-minor run climbing from the 5th to the 12th fret."}],"exercise":{"title":"Full-neck journey","steps":["Play A minor from the lowest to the highest note on the neck, shifting position every two strings.","Play a short phrase in A minor, then the same phrase in D minor and E minor.","In the Jam Lab, pick a progression that changes key (or change key between loops) and follow it."]},"mistakes":["Shifting late so the timing stumbles.","Always shifting with the same finger regardless of context."],"selfCheck":["I can play a scale from the bottom to the top of the neck without stopping."],"realWorld":"The most engaging solos travel across registers, building from low to high. Connected positions make that possible.","summary":["Move the root and the shape follows.","Combine vertical and horizontal movement.","Patterns interlock across the whole neck."],"next":"l7-modes-intro","mastery":{"quizPass":1,"criteria":["Answer both questions.","Play a scale through the whole neck without stopping."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
