insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l7-modes-intro', 'm7-modes', 7, 'What modes really are', 30, array['Define a mode as a scale heard from a different tonal centre', 'Distinguish the parent-scale view from the formula view', 'Use Pillitiere''s shape-to-mode table']::text[], array['l6-pillitiere-patterns', 'l3-diatonic-chords']::text[], array['theory', 'scales']::text[], '[{"book":"D","section":"Modes: each scale pattern is also one of the seven modes"},{"book":"P","note":"Modal theory"}]'::jsonb, '{"quizPass":0.75,"criteria":["Score at least 75%, including generated mode questions."]}'::jsonb, 47) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l7-modes-intro', '{"id":"l7-modes-intro","level":7,"module":"m7-modes","title":"What modes really are","minutes":30,"objectives":["Define a mode as a scale heard from a different tonal centre","Distinguish the parent-scale view from the formula view","Use Pillitiere''s shape-to-mode table"],"prerequisites":["l6-pillitiere-patterns","l3-diatonic-chords"],"categories":["theory","scales"],"sources":[{"book":"D","section":"Modes: each scale pattern is also one of the seven modes"},{"book":"P","note":"Modal theory"}],"why":"Modes are often taught confusingly. The key idea is simple: the same seven notes sound completely different depending on which note feels like home, and that is determined by the harmony underneath.","explanation":[{"type":"p","text":"Play the C major scale from D to D over a D minor chord and it sounds like a distinct minor scale with a bright 6th: D Dorian. From G to G over a G7 chord it sounds bluesy: G Mixolydian. The notes are identical; the tonal centre changes the sound."},{"type":"p","text":"There are two complementary ways to think of a mode. Parent-scale view: D Dorian = the notes of C major, centred on D. Formula view: Dorian = 1 2 ♭3 4 5 6 ♭7, a minor scale with a natural 6th. The parent view helps you find the notes on the neck; the formula view tells you what it will sound like and when to use it."},{"type":"table","head":["Mode","Built on degree","Formula","Quality","Pillitiere start"],"rows":[["Ionian","1","1 2 3 4 5 6 7","Major","XX"],["Dorian","2","1 2 ♭3 4 5 6 ♭7","Minor","ZX"],["Phrygian","3","1 ♭2 ♭3 4 5 ♭6 ♭7","Minor","YZ"],["Lydian","4","1 2 3 ♯4 5 6 7","Major","XY"],["Mixolydian","5","1 2 3 4 5 6 ♭7","Major (dominant)","XXX"],["Aeolian","6","1 2 ♭3 4 5 ♭6 ♭7","Minor","ZZ"],["Locrian","7","1 ♭2 ♭3 4 ♭5 ♭6 ♭7","Diminished","YY"]]},{"type":"callout","tone":"source","text":"Pillitiere maps each of his seven pattern starts to a mode: the pattern that starts on a mode''s own first degree is that mode''s shape (Dorian = ZX, Mixolydian = XXX, and so on). To start a mode on another of its degrees, renumber the cycle from the mode''s pattern."},{"type":"callout","tone":"theory","text":"The harmony decides the mode. Noodling C major notes over a C chord sounds Ionian no matter which note you start on. To hear Dorian, the backing must make D feel like home (a D minor vamp)."}],"guitar":[{"type":"pillitiere","key":"C","degree":2,"caption":"D Dorian = C major pattern starting on degree 2 (ZX). Play it over a Dm7 drone."},{"type":"callout","tone":"tip","text":"Open the Jam Lab, choose a one-chord vamp, and play the same parent-scale notes over different root chords. Hearing the change is the lesson."}],"exercise":{"title":"Same notes, seven moods","steps":["Over a D minor drone, play C major notes resolving to D (Dorian).","Over a G7 drone, the same notes resolving to G (Mixolydian).","Over an F major drone, resolving to F (Lydian). Describe each sound."]},"mistakes":["Thinking playing C major \"starting on D\" is enough without D-centred harmony.","Memorising seven unrelated patterns instead of one system."],"selfCheck":["I can explain modes in both parent-scale and formula terms.","I can name the mode built on each degree."],"realWorld":"Modal vocabulary explains the \"flavour\" of many famous rock, film and jazz sounds, and gives you deliberate choices when improvising.","summary":["A mode = a scale heard from a new home note.","Parent view for location, formula view for sound.","Harmony defines the mode."],"next":"l7-dorian","mastery":{"quizPass":0.75,"criteria":["Score at least 75%, including generated mode questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
