insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l7i-3', 'l7-modes-intro', 'What decides which mode you hear?', '["The first note you play","The tonal centre set by the harmony","The pick direction","The string you start on"]'::jsonb, 1, 'The backing chord defines home.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
