insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l7-dorian', 'm7-modes', 7, 'Dorian: the bright minor', 30, array['Play Dorian in several positions', 'Feature its characteristic natural 6th', 'Improvise over minor vamps with a major IV']::text[], array['l7-modes-intro']::text[], array['scales', 'improvisation']::text[], '[{"book":"D","section":"Mode table: Dorian = ZX"},{"book":"P","note":"Dorian application"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Complete the Dorian Jam Lab challenge."]}'::jsonb, 48) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l7-dorian', '{"id":"l7-dorian","level":7,"module":"m7-modes","title":"Dorian: the bright minor","minutes":30,"objectives":["Play Dorian in several positions","Feature its characteristic natural 6th","Improvise over minor vamps with a major IV"],"prerequisites":["l7-modes-intro"],"categories":["scales","improvisation"],"sources":[{"book":"D","section":"Mode table: Dorian = ZX"},{"book":"P","note":"Dorian application"}],"why":"Dorian is the most-used mode after major and natural minor. Funk, soul, jazz and much Latin rock are built on its sound.","explanation":[{"type":"table","head":["","Value"],"rows":[["Formula","1 2 ♭3 4 5 6 ♭7"],["Steps","W H W W W H W"],["Characteristic note","Natural 6 (a major 6th over a minor chord)"],["Chord","m7, m6, m9, m13 (the ii chord of a major key)"],["Parent","Major scale a whole step below (D Dorian ⊂ C major)"],["Pillitiere shape","ZX"]]},{"type":"p","text":"Compared with natural minor, Dorian raises the 6th. Over a minor chord that one note shifts the mood from dark to hopeful. The giveaway harmony is a major IV chord in a minor key: Dm7 – G7 is pure D Dorian."},{"type":"p","text":"To hear it: play a D minor chord and alternate the notes B♭ (Aeolian ♭6) and B (Dorian 6). That half step is the whole difference."}],"guitar":[{"type":"fretboard","root":"D","scale":"dorian","minFret":3,"maxFret":8,"labels":"interval","caption":"D Dorian around the 5th fret. Find the natural 6 (B)."},{"type":"chord","symbols":["Dm7","G7"],"caption":"The Dorian vamp: i7 – IV7."}],"exercise":{"title":"Dorian vamp","steps":["Over the Jam Lab \"Dorian vamp\" in D, play D minor pentatonic, then add the 6th (B) and 2nd (E) to make it Dorian.","Land on B over the G7 chord: it is the chord''s 3rd.","Complete the \"Use Dorian over a minor progression\" challenge."]},"mistakes":["Playing Dorian over a progression that contains a ♭VI chord (the ♭6 belongs there, so use Aeolian).","Never emphasising the 6th, so it just sounds like minor pentatonic."],"selfCheck":["I can hear the difference between Dorian and Aeolian."],"realWorld":"Dorian powers countless funk grooves, Latin rock jams and modal jazz tunes.","summary":["1 2 ♭3 4 5 6 ♭7.","Natural 6 = bright minor.","Fits i7–IV7 vamps and ii chords."],"next":"l7-mixolydian","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Complete the Dorian Jam Lab challenge."]},"unlocks":{"scales":["dorian"],"challenges":["dorian-minor"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
