insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l7-mixolydian', 'm7-modes', 7, 'Mixolydian: the dominant sound', 30, array['Play Mixolydian and feature its ♭7', 'Use it over dominant 7th chords and ♭VII progressions', 'Blend it with minor pentatonic for blues-rock']::text[], array['l7-modes-intro', 'l5-12-bar-blues']::text[], array['scales', 'improvisation']::text[], '[{"book":"D","section":"Mode table: Mixolydian = XXX"},{"book":"P"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}'::jsonb, 49) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l7-mixolydian', '{"id":"l7-mixolydian","level":7,"module":"m7-modes","title":"Mixolydian: the dominant sound","minutes":30,"objectives":["Play Mixolydian and feature its ♭7","Use it over dominant 7th chords and ♭VII progressions","Blend it with minor pentatonic for blues-rock"],"prerequisites":["l7-modes-intro","l5-12-bar-blues"],"categories":["scales","improvisation"],"sources":[{"book":"D","section":"Mode table: Mixolydian = XXX"},{"book":"P"}],"why":"Mixolydian is the sound of classic rock, blues and jam bands: major but with an edge. It fits every chord of a 12-bar blues.","explanation":[{"type":"table","head":["","Value"],"rows":[["Formula","1 2 3 4 5 6 ♭7"],["Steps","W W H W W H W"],["Characteristic note","♭7 against a major 3rd"],["Chord","7, 9, 13 (the V chord of a major key)"],["Parent","Major scale a 4th above (G Mixolydian ⊂ C major)"],["Pillitiere shape","XXX"]]},{"type":"p","text":"Mixolydian is a major scale with a lowered 7th, which is exactly the dominant 7th chord''s tones plus 2, 4 and 6. Rock progressions using the borrowed ♭VII chord (A–G–D in A) are Mixolydian."},{"type":"p","text":"In blues, play each chord''s own Mixolydian (A Mixolydian over A7, D Mixolydian over D7) to follow the changes, or mix A Mixolydian with A minor pentatonic for the classic blend of sweet and gritty."}],"guitar":[{"type":"fretboard","root":"A","scale":"mixolydian","minFret":4,"maxFret":9,"labels":"interval","caption":"A Mixolydian around the 5th fret."},{"type":"pillitiere","key":"D","degree":5,"caption":"A Mixolydian as the D major pattern from degree 5 (XXX)."}],"exercise":{"title":"Mixolydian rock","steps":["Over the Jam Lab \"I–♭VII–IV\" in A, play A Mixolydian, landing on G over the G chord.","Over a 12-bar in A, switch Mixolydian scales with each chord.","Blend: start phrases in A minor pentatonic and resolve with the major 3rd (C♯)."]},"mistakes":["Using the major scale (with G♯) over A7: G♯ clashes with the chord''s G."],"selfCheck":["I can play Mixolydian over a dominant chord and hear the ♭7."],"realWorld":"Many classic rock anthems and jam-band improvisations are Mixolydian at heart.","summary":["1 2 3 4 5 6 ♭7.","Fits dominant chords and ♭VII rock.","Blend with minor pentatonic for blues-rock."],"next":"l7-lydian-phrygian","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3."]},"unlocks":{"scales":["mixolydian"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
