insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l7-lydian-phrygian', 'm7-modes', 7, 'Lydian and Phrygian: the brightest major and a dark minor', 35, array['Play Lydian and feature the ♯4', 'Play Phrygian and feature the ♭2', 'Choose backing harmony that brings out each sound']::text[], array['l7-modes-intro']::text[], array['scales', 'improvisation']::text[], '[{"book":"D","section":"Mode table: Lydian = XY, Phrygian = YZ"},{"book":"P"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}'::jsonb, 50) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l7-lydian-phrygian', '{"id":"l7-lydian-phrygian","level":7,"module":"m7-modes","title":"Lydian and Phrygian: the brightest major and a dark minor","minutes":35,"objectives":["Play Lydian and feature the ♯4","Play Phrygian and feature the ♭2","Choose backing harmony that brings out each sound"],"prerequisites":["l7-modes-intro"],"categories":["scales","improvisation"],"sources":[{"book":"D","section":"Mode table: Lydian = XY, Phrygian = YZ"},{"book":"P"}],"why":"Lydian''s floating ♯4 and Phrygian''s menacing ♭2 are two of the most distinctive colours in music: film scores and prog on one side, metal and flamenco on the other.","explanation":[{"type":"table","head":["","Value"],"rows":[["Lydian formula","1 2 3 ♯4 5 6 7"],["Characteristic","♯4 (raised 4th)"],["Chord","maj7, maj7♯11; the IV of a major key"],["Backing that reveals it","I – II (both major), e.g. Fmaj7 – G"],["Pillitiere shape","XY"]]},{"type":"table","head":["","Value"],"rows":[["Phrygian formula","1 ♭2 ♭3 4 5 ♭6 ♭7"],["Characteristic","♭2 (half step above the root)"],["Chord","m, m7, 7sus4♭9; the iii of a major key"],["Backing that reveals it","i – ♭II, e.g. Em – F"],["Pillitiere shape","YZ"]]},{"type":"p","text":"Lydian is the major scale with a raised 4th. Because the natural 4th clashes with a major chord''s 3rd, Lydian sounds smoother and more \"suspended in air.\" Phrygian is natural minor with a lowered 2nd; the half step above the root gives Spanish and metal tension. Its cousin, Phrygian dominant (with a major 3rd), comes in the minor-modes lesson."}],"guitar":[{"type":"fretboard","root":"F","scale":"lydian","minFret":0,"maxFret":5,"labels":"interval","caption":"F Lydian in first position: B natural is the ♯4."},{"type":"fretboard","root":"E","scale":"phrygian","minFret":0,"maxFret":5,"labels":"interval","caption":"E Phrygian in first position: F is the ♭2. The open low E makes a perfect pedal."}],"exercise":{"title":"Colour contrast","steps":["Over the Jam Lab \"Lydian float\" (I–II) in F, play F Lydian and hold the B over the G chord.","Over \"Phrygian metal (i–♭II)\" in E, chug the open E and play F–E motifs.","Ear Training → Scales level 2: distinguish Lydian from Ionian and Phrygian from Aeolian."]},"mistakes":["Playing Lydian over a plain I–IV–V (the ♯4 clashes with the IV chord).","Never using the characteristic note, so the mode is inaudible."],"selfCheck":["I can recognise Lydian and Phrygian by ear."],"realWorld":"Lydian appears in many film themes and in prog and fusion; Phrygian in metal riffs and flamenco-inspired music.","summary":["Lydian = major with ♯4, floating.","Phrygian = minor with ♭2, dark.","Harmony must support the colour."],"next":"l7-aeolian-locrian","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3."]},"unlocks":{"scales":["lydian","phrygian"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
