insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l7-aeolian-locrian', 'm7-modes', 7, 'Aeolian, Locrian and the brightness spectrum', 30, array['Place all seven modes on a bright-to-dark spectrum', 'Use Locrian over half-diminished chords', 'Compare modes as one-note changes']::text[], array['l7-dorian', 'l7-mixolydian', 'l7-lydian-phrygian']::text[], array['scales', 'theory']::text[], '[{"book":"D","section":"Mode table: Aeolian = ZZ, Locrian = YY"},{"book":"P","note":"Modal brightness"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3, including generated mode questions."]}'::jsonb, 51) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l7-aeolian-locrian', '{"id":"l7-aeolian-locrian","level":7,"module":"m7-modes","title":"Aeolian, Locrian and the brightness spectrum","minutes":30,"objectives":["Place all seven modes on a bright-to-dark spectrum","Use Locrian over half-diminished chords","Compare modes as one-note changes"],"prerequisites":["l7-dorian","l7-mixolydian","l7-lydian-phrygian"],"categories":["scales","theory"],"sources":[{"book":"D","section":"Mode table: Aeolian = ZZ, Locrian = YY"},{"book":"P","note":"Modal brightness"}],"why":"Seeing all modes as one family ordered by brightness makes choosing a mode intuitive: you pick the mood, then the mode.","explanation":[{"type":"p","text":"Order the modes from brightest to darkest and each step lowers exactly one note: Lydian (♯4) → Ionian (lower the ♯4) → Mixolydian (♭7) → Dorian (♭3) → Aeolian (♭6) → Phrygian (♭2) → Locrian (♭5)."},{"type":"table","head":["Mode","Change from previous"],"rows":[["Lydian","Brightest: 1 2 3 ♯4 5 6 7"],["Ionian","♯4 → 4"],["Mixolydian","7 → ♭7"],["Dorian","3 → ♭3"],["Aeolian","6 → ♭6"],["Phrygian","2 → ♭2"],["Locrian","5 → ♭5 (darkest)"]]},{"type":"p","text":"Aeolian is natural minor, already familiar from rock and metal. Locrian has a diminished 5th, so its root chord is diminished and never feels at rest. It is mainly used over half-diminished (m7♭5) chords, such as the ii chord in minor keys, rather than as a home key."},{"type":"callout","tone":"theory","text":"In parallel terms (all from the same root), each mode is one alteration from its neighbour. This is the basis of modal interchange."}],"guitar":[{"type":"fretboard","root":"B","scale":"locrian","minFret":5,"maxFret":9,"labels":"interval","caption":"B Locrian (notes of C major) over a Bm7♭5 chord."}],"exercise":{"title":"Parallel modes","steps":["On one root (A), play all seven modes in brightness order, one octave each.","Notice which single note changes at each step.","Over a Bm7♭5 – E7 – Am progression, use B Locrian on Bm7♭5."]},"mistakes":["Trying to build a whole song in Locrian without understanding its instability."],"selfCheck":["I can recite the brightness order and the note that changes at each step."],"realWorld":"Composers choose modes for mood: Lydian for wonder, Dorian for cool, Phrygian for menace. This map makes that choice deliberate.","summary":["Brightness order: Lydian → Locrian.","Each step lowers one note.","Locrian is for m7♭5 chords."],"next":"l7-minor-modes","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3, including generated mode questions."]},"unlocks":{"scales":["locrian"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l7a-1', 'l7-aeolian-locrian', 'Which mode is darkest?', '["Phrygian","Aeolian","Locrian","Dorian"]'::jsonb, 2, 'Locrian, with ♭2 and ♭5.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
