insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l7-minor-modes', 'm7-advanced', 7, 'Modes of harmonic and melodic minor', 35, array['Use Phrygian dominant over V7 in minor', 'Use Lydian dominant and the altered scale over dominant chords', 'Know where these modes come from']::text[], array['l7-aeolian-locrian', 'l6-minor-scales']::text[], array['scales', 'theory', 'improvisation']::text[], '[{"book":"P","note":"Modes of harmonic and melodic minor"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}'::jsonb, 52) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l7-minor-modes', '{"id":"l7-minor-modes","level":7,"module":"m7-advanced","title":"Modes of harmonic and melodic minor","minutes":35,"objectives":["Use Phrygian dominant over V7 in minor","Use Lydian dominant and the altered scale over dominant chords","Know where these modes come from"],"prerequisites":["l7-aeolian-locrian","l6-minor-scales"],"categories":["scales","theory","improvisation"],"sources":[{"book":"P","note":"Modes of harmonic and melodic minor"}],"why":"These modes supply the exotic and jazzy sounds that the major modes cannot: neoclassical drama, fusion sophistication and maximum tension over dominant chords.","explanation":[{"type":"p","text":"Any scale has modes. Harmonic minor''s 5th mode, Phrygian dominant (1 ♭2 3 4 5 ♭6 ♭7), fits the V7 chord in a minor key: E Phrygian dominant over E7 in A minor. It is the heart of neoclassical and Middle-Eastern-flavoured metal."},{"type":"p","text":"Melodic minor gives two essential jazz/fusion scales. Lydian dominant (mode 4: 1 2 3 ♯4 5 6 ♭7) fits dominant chords that do not resolve down a fifth (♭VII7, II7). The altered scale (mode 7: 1 ♭2 ♭3 ♭4 ♭5 ♭6 ♭7, read as 1 ♭9 ♯9 3 ♭5 ♯5 ♭7) fits a dominant chord resolving to I, providing every possible tension."},{"type":"table","head":["Mode","Parent","Use"],"rows":[["Phrygian dominant","Harmonic minor, mode 5","V7 in minor keys"],["Lydian dominant","Melodic minor, mode 4","Non-resolving dominants, 7♯11"],["Altered","Melodic minor, mode 7","Altered dominants resolving to I"],["Locrian ♮2","Melodic minor, mode 6","m7♭5 chords (jazz)"]]}],"guitar":[{"type":"fretboard","root":"E","scale":"phrygian-dominant","minFret":0,"maxFret":5,"labels":"interval","caption":"E Phrygian dominant in first position."}],"exercise":{"title":"Dominant colours","steps":["Over the Jam Lab \"Andalusian cadence\" in A minor, use E Phrygian dominant on E7.","Over a static D7 vamp, compare D Mixolydian with D Lydian dominant (G♯ instead of G).","Use the theory panel in the Jam Lab to see which scale the engine recommends for each chord, and why."]},"mistakes":["Using the altered scale over a static dominant vamp (it wants to resolve)."],"selfCheck":["I can choose between Mixolydian, Lydian dominant, Phrygian dominant and altered for a dominant chord."],"realWorld":"Neoclassical shred, fusion and bebop rely on these sounds; the Jam Lab''s recommendations use the same logic.","summary":["Phrygian dominant for V7 in minor.","Lydian dominant for non-resolving dominants.","Altered for maximum tension before resolution."],"next":"l7-modal-interchange","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3."]},"unlocks":{"scales":["phrygian-dominant","lydian-dominant","altered","locrian-nat2","dorian-sharp4","mixolydian-b6"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
