insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l7-modal-interchange', 'm7-advanced', 7, 'Modal interchange and modal improvisation', 35, array['Recognise borrowed chords (♭VII, ♭VI, iv in major)', 'Switch scales for borrowed chords', 'Improvise modally over static and changing harmony']::text[], array['l7-aeolian-locrian']::text[], array['theory', 'improvisation', 'chords']::text[], '[{"book":"P","note":"Modal interchange"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions correctly."]}'::jsonb, 53) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l7-modal-interchange', '{"id":"l7-modal-interchange","level":7,"module":"m7-advanced","title":"Modal interchange and modal improvisation","minutes":35,"objectives":["Recognise borrowed chords (♭VII, ♭VI, iv in major)","Switch scales for borrowed chords","Improvise modally over static and changing harmony"],"prerequisites":["l7-aeolian-locrian"],"categories":["theory","improvisation","chords"],"sources":[{"book":"P","note":"Modal interchange"}],"why":"Most rock and pop songs borrow chords from parallel modes. Recognising them tells you exactly which notes to change in your solo.","explanation":[{"type":"p","text":"Modal interchange (borrowing) means using chords from a parallel mode: the same root, a different mode. In C major, ♭VII (B♭) comes from C Mixolydian, ♭VI (A♭) and iv (Fm) come from C Aeolian, and II (D major) from C Lydian."},{"type":"p","text":"When a borrowed chord appears, adjust the scale for its duration: over B♭ in C, play C Mixolydian (B♭ instead of B) or simply the notes of B♭ major. The Jam Lab''s theory panel marks out-of-key chords and suggests the right adjustment."},{"type":"p","text":"Modal improvisation over a static chord means sustaining one mode for a long time, emphasising its characteristic note and avoiding phrases that pull toward the parent key''s tonic."}],"guitar":[{"type":"chord","symbols":["C","Bb","F","Fm","C"],"caption":"C – B♭ – F – Fm – C: ♭VII from Mixolydian, iv from Aeolian."}],"exercise":{"title":"Borrow and adjust","steps":["Play C – B♭ – F – Fm – C and identify each borrowed chord.","Solo over it, changing B to B♭ over B♭ and A to A♭ over Fm.","Pick a one-chord vamp and improvise in one mode for three minutes, featuring its characteristic note."]},"mistakes":["Ignoring borrowed chords and playing the parent scale straight through."],"selfCheck":["I can identify ♭VII, ♭VI and iv in a major key and adjust my scale."],"realWorld":"The \"minor iv\" is a classic emotional move in ballads; ♭VII is everywhere in rock.","summary":["Borrow chords from parallel modes.","Adjust the scale while the borrowed chord sounds.","Modal soloing emphasises characteristic notes."],"next":"l8-barre-chords","mastery":{"quizPass":1,"criteria":["Answer both questions correctly."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l7x-1', 'l7-modal-interchange', 'In C major, a B♭ chord is borrowed from…', '["C Lydian","C Mixolydian","C Phrygian","C Locrian"]'::jsonb, 1, 'C Mixolydian has B♭.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l7x-2', 'l7-modal-interchange', 'A minor iv chord in a major key comes from…', '["Parallel Aeolian (minor)","Parallel Lydian","Relative minor","Whole tone"]'::jsonb, 0, 'Fm in C major is from C natural minor.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l8-barre-chords', 'm8-chords', 8, 'Barre chords: E and A shapes', 35, array['Play E-shape and A-shape major and minor barre chords', 'Name barre chords from their root on the 6th or 5th string', 'Switch between open and barre chords in time']::text[], array['l1-open-chords', 'l2-root-strings']::text[], array['chords', 'technique']::text[], '[{"book":"C","section":"Barre chords: E-shape and A-shape major and minor, dominant 7th barres"},{"book":"P"}]'::jsonb, '{"quizPass":0.67,"practice":{"exerciseId":"ex-barre-changes","bpm":80},"criteria":["Score at least 2 of 3.","Log a clean barre-change take at 80 bpm."]}'::jsonb, 54) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l8-barre-chords', '{"id":"l8-barre-chords","level":8,"module":"m8-chords","title":"Barre chords: E and A shapes","minutes":35,"objectives":["Play E-shape and A-shape major and minor barre chords","Name barre chords from their root on the 6th or 5th string","Switch between open and barre chords in time"],"prerequisites":["l1-open-chords","l2-root-strings"],"categories":["chords","technique"],"sources":[{"book":"C","section":"Barre chords: E-shape and A-shape major and minor, dominant 7th barres"},{"book":"P"}],"why":"Barre chords let you play any major or minor chord with two movable shapes. They are the bridge from beginner chords to the whole neck.","explanation":[{"type":"p","text":"A barre chord is an open chord shape moved up the neck, with the first finger replacing the nut. E-shape: fret an E major chord with fingers 2, 3 and 4, then slide up and lay finger 1 across all six strings. At fret 1 that is F; at fret 3, G. The root is on the 6th string."},{"type":"p","text":"E-shape minor: the same idea starting from E minor. A-shape major: barre strings 5–1 with finger 1 and either use fingers 2-3-4 or a ring-finger mini-barre on strings 4–2 (often muting string 1). A-shape minor comes from Am. The root is on the 5th string."},{"type":"chord","symbols":["F","Fm","Bb","Bbm"],"caption":"E-shape (root on 6th string) and A-shape (root on 5th string) barre chords."},{"type":"callout","tone":"tip","text":"Roll the first finger slightly onto its bony edge, keep the elbow close to the body and let arm weight (not thumb squeeze) provide pressure. Check each string; most problems are one or two muted strings."},{"type":"callout","tone":"source","text":"Book 3 opens with exactly these four shapes plus E- and A-shape dominant 7th barres, then applies them in many riffs. The progression below is original."}],"guitar":[{"type":"p","text":"Play | F | Dm | B♭ | C | using barre chords (F at fret 1 E-shape, Dm at fret 5 A-shape, B♭ at fret 1 A-shape, C at fret 3 A-shape)."}],"exercise":{"title":"Barre fitness","steps":["Hold an F barre for 10 seconds, release, repeat 5 times (build strength gently).","Move the E-shape chromatically from fret 1 to 7 and back.","Technique Lab: barre-chord changes exercise."],"exerciseId":"ex-barre-changes"},"metronome":{"bpmStart":60,"bpmTarget":100,"subdivision":1,"instructions":"One chord per bar, then two beats per chord."},"mistakes":["Squeezing with the thumb until the hand cramps.","Barre finger flat on its soft pad, muting strings in its creases.","Ignoring which string carries the root."],"selfCheck":["All strings ring in my E- and A-shape barres.","I can find any major or minor barre chord by its root."],"realWorld":"Barre chords let you play any song in any key without a capo. Countless rock and pop songs use only E- and A-shape barres.","summary":["E shape: root on 6th string. A shape: root on 5th.","Major and minor versions of each.","Use arm weight, not grip."],"next":"l8-sevenths","mastery":{"quizPass":0.67,"practice":{"exerciseId":"ex-barre-changes","bpm":80},"criteria":["Score at least 2 of 3.","Log a clean barre-change take at 80 bpm."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
