insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l8-sevenths', 'm8-chords', 8, 'Seventh chords, sus and add chords', 35, array['Build maj7, 7, m7, m7♭5 and dim7 chords', 'Play add9, sus2 and sus4 voicings', 'Hear each chord''s colour']::text[], array['l8-barre-chords', 'l3-triads']::text[], array['chords', 'theory']::text[], '[{"book":"C","section":"Dominant seventh, minor seventh, add and sus chords, ninth chords"},{"book":"P"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3, including generated chord-spelling questions."]}'::jsonb, 55) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l8-sevenths', '{"id":"l8-sevenths","level":8,"module":"m8-chords","title":"Seventh chords, sus and add chords","minutes":35,"objectives":["Build maj7, 7, m7, m7♭5 and dim7 chords","Play add9, sus2 and sus4 voicings","Hear each chord''s colour"],"prerequisites":["l8-barre-chords","l3-triads"],"categories":["chords","theory"],"sources":[{"book":"C","section":"Dominant seventh, minor seventh, add and sus chords, ninth chords"},{"book":"P"}],"why":"Seventh chords add colour and direction: dominant 7ths drive the blues, minor 7ths give soul and funk their mellowness, major 7ths sound lush.","explanation":[{"type":"p","text":"A seventh chord adds a 7th above the root to a triad:"},{"type":"table","head":["Chord","Formula","Sound / use"],"rows":[["maj7","1 3 5 7","Lush, dreamy (I and IV)"],["7 (dominant)","1 3 5 ♭7","Bluesy, wants to resolve (V, blues I-IV-V)"],["m7","1 ♭3 5 ♭7","Mellow (ii, iii, vi)"],["m7♭5","1 ♭3 ♭5 ♭7","Unstable (vii in major, ii in minor)"],["dim7","1 ♭3 ♭5 ♭♭7","Very tense, symmetrical"]]},{"type":"p","text":"Add chords keep the triad and add a note: add9 = 1 3 5 9. Sus chords replace the 3rd: sus2 = 1 2 5, sus4 = 1 4 5. Ninth chords (9 = 1 3 5 ♭7 9) are often used as a funkier substitute for a dominant 7th."},{"type":"chord","symbols":["Cmaj7","C7","Cm7","Bm7b5","Cadd9","Dsus4","E9"],"caption":"Common voicings. Explore more in the Chord Explorer."}],"guitar":[{"type":"p","text":"Play Am7 – D7 – Gmaj7 – Cmaj7 and listen to how each chord colours the progression. Then play G – Cadd9 – G – Cadd9 (keeping fingers 3 and 4 anchored on the top strings)."}],"exercise":{"title":"Colour palette","steps":["For one root (A), play maj7, 7, m7 and m7♭5 back to back.","Play a ii–V–I in G: Am7 – D7 – Gmaj7.","Use the Chord Explorer to find three voicings of each seventh type."]},"mistakes":["Using a maj7 where a dominant 7 is needed (and vice versa): the 7th type changes everything."],"selfCheck":["I can hear the difference between maj7, 7 and m7."],"realWorld":"Blues uses dominant 7ths everywhere; neo-soul and jazz use maj7, m7 and 9 chords; pop and rock love add9 and sus chords.","summary":["Four main seventh qualities plus dim7.","Add chords add; sus chords replace the 3rd.","Each colour has a typical function."],"next":"l8-inversions","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3, including generated chord-spelling questions."]},"unlocks":{"chords":["Cmaj7","C7","Cm7","Bm7b5","Cadd9","E9","Bdim7"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
