insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l8-inversions', 'm8-chords', 8, 'Triad inversions, voice leading and drop voicings', 35, array['Play major and minor triads in root position and both inversions on three-string groups', 'Connect chords with minimal movement (voice leading)', 'Understand drop-2 voicings']::text[], array['l8-sevenths', 'l3-triads']::text[], array['chords', 'fretboard']::text[], '[{"book":"P","note":"Inversions, voice leading, drop voicings"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions.","Play I–IV–V–I in C with voice-led triads."]}'::jsonb, 56) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l8-inversions', '{"id":"l8-inversions","level":8,"module":"m8-chords","title":"Triad inversions, voice leading and drop voicings","minutes":35,"objectives":["Play major and minor triads in root position and both inversions on three-string groups","Connect chords with minimal movement (voice leading)","Understand drop-2 voicings"],"prerequisites":["l8-sevenths","l3-triads"],"categories":["chords","fretboard"],"sources":[{"book":"P","note":"Inversions, voice leading, drop voicings"}],"why":"Small triad shapes on the top strings are the secret of tasteful rhythm guitar: they sit above the band, move smoothly and outline the harmony anywhere on the neck.","explanation":[{"type":"p","text":"An inversion puts a note other than the root in the bass. Root position: 1-3-5 from low to high. First inversion: 3-5-1. Second inversion: 5-1-3. On any group of three adjacent strings you get three shapes per triad, climbing the neck."},{"type":"p","text":"Voice leading means moving from one chord to the next with the smallest possible motion of each note. Choose inversions so common tones stay put and the other notes move by step."},{"type":"p","text":"Drop voicings spread close-position chords so they fit the guitar. A drop-2 voicing takes the second-highest note of a close seventh chord and drops it an octave, giving playable four-note shapes on strings 4–1 or 5–2."},{"type":"fretboard","root":"C","chord":"maj","minFret":0,"maxFret":15,"labels":"interval","caption":"C major triad tones across the neck. Find root position and both inversions on strings 3-2-1."}],"guitar":[{"type":"tab","ascii":"   C (root)     F (2nd inv)  G (2nd inv)  C (1st inv)\ne|-3------------5------------7------------8----|\nB|-5------------6------------8------------8----|\nG|-5------------5------------7------------9----|","caption":"Original voice-led triads on the top three strings."}],"exercise":{"title":"Triads everywhere","steps":["Play C major on strings 3-2-1 in all three inversions up the neck.","Play I–IV–V–I in C using the nearest inversion each time.","Find drop-2 maj7 and m7 voicings on strings 4-3-2-1 in the Chord Explorer."]},"mistakes":["Jumping around the neck instead of choosing the nearest inversion."],"selfCheck":["I can play any major or minor triad in three inversions on the top strings."],"realWorld":"Funk, soul and pop guitarists use small triads to stay out of the bass and keyboard range and still define the chords.","summary":["Three inversions per triad per string set.","Voice leading: minimal motion.","Drop voicings make 7th chords playable."],"next":"l8-extended","mastery":{"quizPass":1,"criteria":["Answer both questions.","Play I–IV–V–I in C with voice-led triads."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
