insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l8-extended', 'm8-chords', 8, 'Extended and altered chords', 30, array['Build 9th, 11th and 13th chords', 'Understand altered dominants (♭9, ♯9, ♭5, ♯5)', 'Choose which notes to omit in guitar voicings']::text[], array['l8-sevenths']::text[], array['chords', 'theory']::text[], '[{"book":"C","section":"Ninth chords; m11 extension"},{"book":"P","note":"Extended and altered harmony"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3."]}'::jsonb, 57) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l8-extended', '{"id":"l8-extended","level":8,"module":"m8-chords","title":"Extended and altered chords","minutes":30,"objectives":["Build 9th, 11th and 13th chords","Understand altered dominants (♭9, ♯9, ♭5, ♯5)","Choose which notes to omit in guitar voicings"],"prerequisites":["l8-sevenths"],"categories":["chords","theory"],"sources":[{"book":"C","section":"Ninth chords; m11 extension"},{"book":"P","note":"Extended and altered harmony"}],"why":"Extensions add sophistication and tension; altered dominants are the spice of jazz, fusion and funk.","explanation":[{"type":"p","text":"Keep stacking thirds above a seventh chord and you reach the 9th, 11th and 13th (the 2nd, 4th and 6th an octave up). A 13 chord technically contains 1 3 5 ♭7 9 11 13, far too many for six strings, so guitarists omit notes: the 5th first (it adds little), the 11th on dominant and major chords (it clashes with the 3rd), often the root if a bassist plays it."},{"type":"p","text":"Altered chords change the 5th or 9th of a dominant chord: 7♭9, 7♯9 (the \"Hendrix chord\", with both major 3rd and ♯9), 7♭5, 7♯5. They create strong tension before resolving to the tonic."},{"type":"chord","symbols":["A9","Am11","G13","E7#9","B7b9"],"caption":"Typical guitar voicings with notes omitted."}],"guitar":[{"type":"p","text":"Play E7♯9 (x7678x) and resolve it to A. Then play a funk vamp on E9 with short, staccato strums."}],"exercise":{"title":"Tension and colour","steps":["Play Dm9 – G13 – Cmaj9.","Resolve B7♭9 to Em and B7 to Em; compare.","In the Chord Explorer, display the formula and note which tones each voicing omits."]},"mistakes":["Trying to fit every extension into one voicing."],"selfCheck":["I can explain which notes are safe to omit."],"realWorld":"Funk rhythm guitar lives on 9th chords; jazz on 13ths and altered dominants.","summary":["Extensions: 9, 11, 13.","Alterations: ♭9 ♯9 ♭5 ♯5 on dominants.","Omit the 5th first."],"next":"l8-chord-tones","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3."]},"unlocks":{"chords":["A9","Am11","G13","E7#9","B7b9"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
