insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l8-chord-tones', 'm8-harmony', 8, 'Chord tones and arpeggios', 35, array['Play arpeggios of triads and seventh chords', 'See chord tones inside scale positions', 'Target chord tones while soloing']::text[], array['l8-sevenths', 'l6-caged']::text[], array['chords', 'improvisation', 'fretboard']::text[], '[{"book":"A","section":"Arpeggios (broken chords)"},{"book":"C","section":"Arpeggio riffs; arpeggiated minor triads in minor blues"},{"book":"P","note":"Chord-tone soloing"}]'::jsonb, '{"quizPass":0.67,"practice":{"exerciseId":"ex-arp-triads","bpm":80},"criteria":["Score at least 2 of 3.","Log a clean arpeggio take at 80 bpm."]}'::jsonb, 58) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l8-chord-tones', '{"id":"l8-chord-tones","level":8,"module":"m8-harmony","title":"Chord tones and arpeggios","minutes":35,"objectives":["Play arpeggios of triads and seventh chords","See chord tones inside scale positions","Target chord tones while soloing"],"prerequisites":["l8-sevenths","l6-caged"],"categories":["chords","improvisation","fretboard"],"sources":[{"book":"A","section":"Arpeggios (broken chords)"},{"book":"C","section":"Arpeggio riffs; arpeggiated minor triads in minor blues"},{"book":"P","note":"Chord-tone soloing"}],"why":"Chord tones are the strongest notes over any chord. Soloists who target them sound like they are following the changes rather than running scales over them.","explanation":[{"type":"p","text":"An arpeggio is a chord played one note at a time. Practising arpeggios teaches you where the root, 3rd, 5th and 7th of every chord sit on the neck, inside the scale shapes you already know."},{"type":"p","text":"Chord-tone targeting means landing on a chord tone, often the 3rd or 7th, on strong beats, especially when the chord changes. Non-chord tones (passing notes) fill the space between targets."},{"type":"fretboard","root":"A","chord":"m7","minFret":4,"maxFret":9,"labels":"interval","caption":"Am7 arpeggio (1 ♭3 5 ♭7) around the 5th fret, inside the A minor pentatonic box."},{"type":"callout","tone":"theory","text":"The 3rd and 7th are called guide tones: they define the chord quality. Moving smoothly between the guide tones of successive chords creates lines that outline the harmony by themselves."}],"guitar":[{"type":"tab","ascii":"e|---------------------5-8-----|\nB|-----------------5-8---------|\nG|-------------5-7-------------|\nD|---------5-7-----------------|\nA|-----7-----------------------|\nE|-5-8-------------------------|","caption":"Am7 arpeggio, ascending (A C E G across two octaves, with one passing note D on the G string)."}],"exercise":{"title":"Follow the changes","steps":["Arpeggiate Am7, Dm7 and Em7 in position 1 of A minor.","Over a 12-bar blues, land on each chord''s 3rd at the change (C♯ on A7, F♯ on D7, G♯ on E7).","Complete the \"Target the 3rd of every chord\" and \"Resolve every phrase to a chord tone\" challenges."],"exerciseId":"ex-arp-triads"},"mistakes":["Playing arpeggios as exercises only and never in solos."],"selfCheck":["I can find the 3rd of any chord in the position I''m playing."],"realWorld":"This is how blues, jazz and fusion players make solos \"speak the changes.\"","summary":["Arpeggios map chord tones.","Target 3rds and 7ths at changes.","Passing notes connect targets."],"next":"l8-functional","mastery":{"quizPass":0.67,"practice":{"exerciseId":"ex-arp-triads","bpm":80},"criteria":["Score at least 2 of 3.","Log a clean arpeggio take at 80 bpm."]},"unlocks":{"challenges":["target-thirds","resolve-chord-tones"],"trainerModes":["chord-tones"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
