insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l8-functional', 'm8-harmony', 8, 'Roman numerals, functional harmony, secondary dominants and substitutions', 40, array['Analyse progressions with Roman numerals', 'Explain tonic, subdominant and dominant function', 'Recognise secondary dominants and common substitutions']::text[], array['l3-diatonic-chords', 'l8-sevenths']::text[], array['theory', 'chords']::text[], '[{"book":"C","section":"Chord numbers"},{"book":"P","note":"Functional harmony"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3, including generated numeral questions."]}'::jsonb, 59) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l8-functional', '{"id":"l8-functional","level":8,"module":"m8-harmony","title":"Roman numerals, functional harmony, secondary dominants and substitutions","minutes":40,"objectives":["Analyse progressions with Roman numerals","Explain tonic, subdominant and dominant function","Recognise secondary dominants and common substitutions"],"prerequisites":["l3-diatonic-chords","l8-sevenths"],"categories":["theory","chords"],"sources":[{"book":"C","section":"Chord numbers"},{"book":"P","note":"Functional harmony"}],"why":"Functional harmony explains why progressions move the way they do. It lets you predict chords, write convincing progressions and choose scales when chords leave the key.","explanation":[{"type":"p","text":"Diatonic chords group into three functions. Tonic (I, iii, vi): stable, home. Subdominant (ii, IV): moving away. Dominant (V, vii°): tension that wants to resolve to tonic. Most progressions follow tonic → subdominant → dominant → tonic."},{"type":"p","text":"The V7 chord resolves strongly because its 3rd (the leading tone) rises a half step to the tonic and its ♭7 falls a half step to the tonic chord''s 3rd."},{"type":"p","text":"Secondary dominants temporarily treat another chord as a tonic: V7/V (D7 in C) leads to G; V7/vi (E7 in C) leads to Am. They are non-diatonic dominant chords a perfect 5th above their target."},{"type":"list","items":["Relative substitution: replace I with vi or iii (same function).","Tritone substitution: replace V7 with a dominant 7th a tritone away (D♭7 for G7 in C); both share the same 3rd and 7th.","Backdoor: ♭VII7 → I (B♭7 → C)."]}],"guitar":[{"type":"chord","symbols":["C","A7","Dm7","G7","C"],"caption":"I – V7/ii – ii7 – V7 – I: a secondary dominant leading to Dm7."}],"exercise":{"title":"Analyse and play","steps":["Analyse C – A7 – Dm7 – G7 – C with numerals.","Replace G7 with D♭7 (tritone sub) and listen.","Use the Jam Lab theory panel to see how the engine labels secondary dominants and out-of-key notes."]},"mistakes":["Labelling a secondary dominant as a \"wrong\" chord rather than understanding its target."],"selfCheck":["I can analyse a progression containing a secondary dominant."],"realWorld":"Jazz standards, soul, Beatles-era pop and gospel use secondary dominants constantly.","summary":["Tonic, subdominant, dominant.","Secondary dominants point to other chords.","Substitutions keep function, change colour."],"next":"l8-chord-scale","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3, including generated numeral questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
