insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l8-chord-scale', 'm8-harmony', 8, 'Chord–scale relationships: playing over changes', 40, array['Pick a scale for each chord based on key context', 'Identify notes that change between chords', 'Improvise over a changing progression']::text[], array['l8-chord-tones', 'l8-functional', 'l7-minor-modes']::text[], array['improvisation', 'theory']::text[], '[{"book":"P","note":"Chord–scale theory"}]'::jsonb, '{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Complete the chord-scale Jam Lab challenge."]}'::jsonb, 60) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l8-chord-scale', '{"id":"l8-chord-scale","level":8,"module":"m8-harmony","title":"Chord–scale relationships: playing over changes","minutes":40,"objectives":["Pick a scale for each chord based on key context","Identify notes that change between chords","Improvise over a changing progression"],"prerequisites":["l8-chord-tones","l8-functional","l7-minor-modes"],"categories":["improvisation","theory"],"sources":[{"book":"P","note":"Chord–scale theory"}],"why":"Understanding why a scale fits a chord turns improvising over changes from guesswork into informed choice.","explanation":[{"type":"p","text":"The academy''s rule (also used by the Jam Lab engine): for each chord, choose a scale built on the chord root that (1) contains every chord tone and (2) shares as many notes as possible with the prevailing key. For diatonic chords this gives the familiar modes: ii7 → Dorian, V7 → Mixolydian, IVmaj7 → Lydian. For non-diatonic chords it changes exactly the notes the chord requires."},{"type":"p","text":"Example in A minor: Am7 (Aeolian), Dm7 (Dorian), E7 (Phrygian dominant, because the chord''s G♯ replaces the key''s G). Only one note changes, and you change it only while E7 sounds."},{"type":"p","text":"Tension notes: scale notes a half step above a chord tone (e.g. F over C major) clash when held. Use them as passing notes resolving down."}],"guitar":[{"type":"fretboard","root":"E","scale":"phrygian-dominant","minFret":4,"maxFret":9,"labels":"interval","caption":"E Phrygian dominant over E7 in A minor: the only change from A minor is G♯."}],"exercise":{"title":"Changes, not keys","steps":["Over a jazz turnaround (Imaj7–vi7–ii7–V7) in C, follow the scale recommendations in the Jam Lab theory panel.","Over the Andalusian cadence, keep A minor but switch G to G♯ on E7.","Complete the \"Follow the chord-scale map\" challenge."]},"mistakes":["Changing scales so mechanically that phrases lose continuity; connect them via nearby chord tones."],"selfCheck":["I can explain why a scale fits a chord in context."],"realWorld":"This is the core skill of jazz and fusion improvisation and of any rock soloist who wants solos that follow the song.","summary":["Scale contains chord tones and stays close to the key.","Change only the notes the chord requires.","Treat tension notes as passing tones."],"next":"l9-picking-systems","mastery":{"quizPass":0.67,"criteria":["Score at least 2 of 3.","Complete the chord-scale Jam Lab challenge."]},"unlocks":{"challenges":["chord-scale-tour"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
