insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l8x-3', 'l8-chord-scale', 'A tension note is…', '["Any chord tone","A scale note a half step above a chord tone","The root","Any note outside the key"]'::jsonb, 1, 'Held against the chord tone below it, it clashes.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l9-picking-systems', 'm9-picking', 9, 'Picking systems: strict alternate, economy, directional; escape motions', 40, array['Compare strict alternate, economy and directional picking', 'Understand inside and outside string changes', 'Identify your escape motion and choose fingerings that suit it']::text[], array['l1-alternate-picking', 'l6-pillitiere-shapes', 'l4-metal-rhythm']::text[], array['technique']::text[], '[{"book":"P","note":"Picking mechanics: escape motions, string changes, economy and directional picking"}]'::jsonb, '{"quizPass":0.67,"practice":{"exerciseId":"ex-alt-inside-outside","bpm":100},"criteria":["Score at least 2 of 3.","Log a clean inside/outside picking take at 100 bpm sixteenths."]}'::jsonb, 61) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l9-picking-systems', '{"id":"l9-picking-systems","level":9,"module":"m9-picking","title":"Picking systems: strict alternate, economy, directional; escape motions","minutes":40,"objectives":["Compare strict alternate, economy and directional picking","Understand inside and outside string changes","Identify your escape motion and choose fingerings that suit it"],"prerequisites":["l1-alternate-picking","l6-pillitiere-shapes","l4-metal-rhythm"],"categories":["technique"],"sources":[{"book":"P","note":"Picking mechanics: escape motions, string changes, economy and directional picking"}],"why":"At speed, string changes are where picking breaks down. Knowing the mechanics lets you pick the right system for each phrase and practise efficiently instead of fighting your own hand.","explanation":[{"type":"p","text":"Strict alternate picking always alternates, regardless of string changes. Economy picking uses alternate picking on a string but, when moving to the next string in the same direction, continues with the same stroke (a mini sweep). Directional picking is a broader idea: choose stroke directions so that every string change moves the pick in the direction it is already travelling."},{"type":"p","text":"Inside picking: the pick changes strings between them (a downstroke on the lower string followed by an upstroke on the higher string, crossing \"inside\" the pair). Outside picking: the pick goes around the outside of the two strings. Most players find one of these easier."},{"type":"p","text":"Escape motion: to move between strings, the pick must leave the plane of the strings after a stroke. Many players naturally escape on downstrokes (downstroke escape, \"DSX\"), others on upstrokes (\"USX\"), some both. Fingerings with an even number of notes per string suit one escape; 3NPS fingerings combine naturally with economy picking."},{"type":"table","head":["System","Strengths","Watch out for"],"rows":[["Strict alternate","Rhythmic consistency, simple rule","Awkward inside/outside changes"],["Economy","Efficient on 3NPS scales and sweeps","Uneven rhythm if the sweep rushes"],["Directional / mixed","Optimises each string change","Requires planning"]]},{"type":"callout","tone":"warning","text":"No system is \"correct.\" Measure: if a pattern stays clean at higher tempos with one system, that is the right system for you and that phrase."}],"guitar":[{"type":"tab","ascii":"e|----------------------------|\nB|-------5-7-8-----------------|\nG|-5-7-9-------9-7-5-----------|","caption":"Original 3NPS fragment: try strict alternate (D U D | U D U), then economy (D U D | D U D with a sweep across the change)."}],"exercise":{"title":"Find your system","steps":["Play the fragment with strict alternate picking at 80 BPM sixteenths, then economy picking.","Practise a two-string inside-picking pattern, then an outside one, and note which is cleaner at 100 BPM.","Technique Lab: inside/outside picking exercise; log your clean tempo for each."],"exerciseId":"ex-alt-inside-outside"},"metronome":{"bpmStart":70,"bpmTarget":130,"subdivision":4,"instructions":"Sixteenths. Raise tempo only after two clean takes."},"mistakes":["Assuming strict alternate is always superior.","Economy sweeps that rush the rhythm.","Large pick motions that hide the real escape issue."],"selfCheck":["I know whether inside or outside picking is easier for me.","I can play a 3NPS run with both strict alternate and economy picking."],"realWorld":"Players famous for fast picking each built a system around their natural escape motion. Measuring your own is the shortcut.","summary":["Three systems: strict, economy, directional.","Inside vs outside string changes.","Match fingerings to your escape motion."],"next":"l9-speed-system","mastery":{"quizPass":0.67,"practice":{"exerciseId":"ex-alt-inside-outside","bpm":100},"criteria":["Score at least 2 of 3.","Log a clean inside/outside picking take at 100 bpm sixteenths."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9p-1', 'l9-picking-systems', 'Economy picking differs from strict alternate picking because…', '["It never uses upstrokes","It continues the same stroke direction when moving to the next string in that direction","It uses fingers","It only works on one string"]'::jsonb, 1, 'It sweeps across string changes in the direction of travel.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9p-2', 'l9-picking-systems', '"Outside picking" means the pick…', '["Changes strings between them","Travels around the outside of the two strings","Plays only outer strings","Uses hybrid picking"]'::jsonb, 1, 'Outside = around the pair rather than between.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9p-3', 'l9-picking-systems', 'An escape motion is…', '["Muting technique","The pick leaving the string plane after a stroke so it can change strings","A slide","A pull-off"]'::jsonb, 1, 'Without escaping, the pick would hit the next string mid-motion.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l9-speed-system', 'm9-picking', 9, 'A measurable speed-development system', 40, array['Establish a clean baseline tempo', 'Use BPM ladders, bursts and rest to build speed', 'Track BPM and timing accuracy over time']::text[], array['l9-picking-systems']::text[], array['technique', 'rhythm']::text[], '[{"book":"P","note":"Speed-development methodology"}]'::jsonb, '{"quizPass":0.67,"practice":{"exerciseId":"ex-sync-burst","bpm":110},"criteria":["Score at least 2 of 3.","Log a clean take at 110 bpm sixteenths."]}'::jsonb, 62) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l9-speed-system', '{"id":"l9-speed-system","level":9,"module":"m9-picking","title":"A measurable speed-development system","minutes":40,"objectives":["Establish a clean baseline tempo","Use BPM ladders, bursts and rest to build speed","Track BPM and timing accuracy over time"],"prerequisites":["l9-picking-systems"],"categories":["technique","rhythm"],"sources":[{"book":"P","note":"Speed-development methodology"}],"why":"Speed is a consequence of accuracy, relaxation and coordination, not of forcing. A measurable system prevents plateaus and protects your hands.","explanation":[{"type":"list","items":["Baseline: find the fastest tempo at which you play an exercise perfectly five times in a row, relaxed. Log it.","Ladder: practise at 85% of baseline for accuracy, then step up 3–5 BPM per clean take. When two takes fail, drop 8–10 BPM.","Bursts: play short bursts (one beat or four notes) well above your baseline, then stop. Bursts teach the motion at speed without endurance strain.","Synchronisation: play slowly with exaggerated precision, checking that fretting and picking land together (the Playing Analyzer measures timing).","Endurance: once clean, extend the duration at a comfortable tempo (30 s → 60 s → 2 min).","Rest: take breaks every 20–25 minutes and stop at any pain."],"ordered":true},{"type":"p","text":"The Technique Lab and Practice Studio log every take''s tempo and whether it was clean. The scheduler raises your target by 4 BPM after two clean takes and lowers it after a struggle, which is the ladder applied automatically."},{"type":"callout","tone":"theory","text":"Tension is the speed killer. At the edge of your speed, focus on the most relaxed motion possible, not the hardest attack."}],"guitar":[{"type":"tab","ascii":"e|-------------------------------|\nB|-------------------------------|\nG|-------------------------------|\nD|-------------------------------|\nA|-------------------------------|\nE|-5-6-7-8-5-6-7-8-5-6-7-8-5-6-7-8-|","caption":"A simple four-note group for bursts: play one group as fast as possible cleanly, then stop."}],"exercise":{"title":"Ladder and bursts","steps":["Find your clean baseline on the Synchronisation exercise and log it.","Run a ladder from 85% upward until two failed takes.","Do 10 bursts of one beat at baseline + 20 BPM."],"exerciseId":"ex-sync-burst"},"metronome":{"bpmStart":80,"bpmTarget":160,"subdivision":4,"instructions":"Use tap tempo to set your baseline, then the presets to step up."},"mistakes":["Practising at maximum speed every session.","Ignoring timing accuracy because notes \"felt\" fast.","Practising through pain."],"selfCheck":["I have a logged baseline for at least three exercises.","My progress chart shows a rising clean tempo."],"realWorld":"Professional shredders track tempos and practise systematically. This turns \"practice until you improve\" into measurable progress.","summary":["Baseline → ladder → bursts → endurance.","Measure clean tempo and timing.","Relaxation is speed."],"next":"l9-legato-advanced","mastery":{"quizPass":0.67,"practice":{"exerciseId":"ex-sync-burst","bpm":110},"criteria":["Score at least 2 of 3.","Log a clean take at 110 bpm sixteenths."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9s-1', 'l9-speed-system', 'What is a clean baseline?', '["The fastest tempo you can attempt","The fastest tempo you play perfectly several times in a row, relaxed","Always 120 BPM","The slowest tempo"]'::jsonb, 1, 'Baseline = reliable, relaxed, clean speed.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
