insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9s-3', 'l9-speed-system', 'After two failed takes in a ladder you should…', '["Keep going faster","Drop 8–10 BPM","Stop practising for the week","Switch to a thinner pick"]'::jsonb, 1, 'Return to accuracy before climbing again.', 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l9-legato-advanced', 'm9-techniques', 9, 'Three-notes-per-string legato and finger independence', 35, array['Play 3NPS legato runs with even volume', 'Build finger independence and strength', 'Increase legato endurance']::text[], array['l5-legato', 'l6-pillitiere-patterns']::text[], array['technique']::text[], '[{"book":"D","section":"3NPS shapes provide consistent left-hand fingerings"},{"book":"P","note":"Legato technique"}]'::jsonb, '{"quizPass":1,"practice":{"exerciseId":"ex-legato-3nps","bpm":90},"criteria":["Answer both questions.","Log a clean 3NPS legato take at 90 bpm (triplets)."]}'::jsonb, 63) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l9-legato-advanced', '{"id":"l9-legato-advanced","level":9,"module":"m9-techniques","title":"Three-notes-per-string legato and finger independence","minutes":35,"objectives":["Play 3NPS legato runs with even volume","Build finger independence and strength","Increase legato endurance"],"prerequisites":["l5-legato","l6-pillitiere-patterns"],"categories":["technique"],"sources":[{"book":"D","section":"3NPS shapes provide consistent left-hand fingerings"},{"book":"P","note":"Legato technique"}],"why":"Legato gives fluid, saxophone-like lines and lets you play fast with little picking. Pillitiere''s X/Y/Z shapes are ideal legato units.","explanation":[{"type":"p","text":"In 3NPS legato, pick only the first note on each string, then hammer on (ascending) or pull off (descending) the other two. Each Pillitiere shape (X, Y, Z) becomes a three-note legato cell with consistent fingering."},{"type":"p","text":"Hammer-ons from nowhere (hammering a note on a new string without picking) allow fully legato lines. Mute idle strings with the fretting hand''s underside and the picking-hand palm."},{"type":"list","items":["Finger independence: play 1-3-2-4 and 1-4-2-3 permutations on one string.","Strength: trill pairs (1-2, 1-3, 1-4, 2-3, 2-4, 3-4) for 15 seconds each.","Endurance: play a 3NPS scale up and down legato for 1 minute without volume drop."]}],"guitar":[{"type":"tab","ascii":"e|-------------------------------------7h8h10--|\nB|-----------------------------6h8h10----------|\nG|----------------------5h7h9------------------|\nD|---------------5h7h9-------------------------|\nA|--------5h7h8--------------------------------|\nE|-5h7h8---------------------------------------|","caption":"A natural-minor 3NPS legato run (A minor = C major from degree 6, so the shapes are Z Z X X X Y). Pick only the first note on each string."}],"exercise":{"title":"Legato engine","steps":["Trill each finger pair for 15 s.","Play the 3NPS legato run up and down at a steady tempo.","Technique Lab: 3NPS legato exercise; log clean tempo."],"exerciseId":"ex-legato-3nps"},"metronome":{"bpmStart":60,"bpmTarget":120,"subdivision":3,"instructions":"Triplets: one string per beat."},"mistakes":["Volume drop on hammered notes.","Unmuted strings ringing during legato.","Pull-offs that lift straight up."],"selfCheck":["All three notes per string are equally loud.","Idle strings stay silent."],"realWorld":"Fluid rock and fusion legato lines are built from exactly these cells.","summary":["One pick per string, the rest legato.","X/Y/Z shapes as legato cells.","Mute idle strings; keep volume even."],"next":"l9-sweep","mastery":{"quizPass":1,"practice":{"exerciseId":"ex-legato-3nps","bpm":90},"criteria":["Answer both questions.","Log a clean 3NPS legato take at 90 bpm (triplets)."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9l-1', 'l9-legato-advanced', 'In 3NPS legato, how many notes per string are usually picked?', '["All three","One","Two","None ever"]'::jsonb, 1, 'Pick the first, hammer or pull the others.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
