insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l9-sweep', 'm9-techniques', 9, 'Sweep picking and arpeggio sweeping', 40, array['Sweep a three-string triad cleanly', 'Roll fingers to keep notes separate', 'Extend to five-string arpeggios']::text[], array['l9-picking-systems', 'l8-chord-tones']::text[], array['technique', 'chords']::text[], '[{"book":"P","note":"Sweep picking"}]'::jsonb, '{"quizPass":0.67,"practice":{"exerciseId":"ex-sweep-3string","bpm":80},"criteria":["Score at least 2 of 3.","Log a clean three-string sweep at 80 bpm triplets."]}'::jsonb, 64) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l9-sweep', '{"id":"l9-sweep","level":9,"module":"m9-techniques","title":"Sweep picking and arpeggio sweeping","minutes":40,"objectives":["Sweep a three-string triad cleanly","Roll fingers to keep notes separate","Extend to five-string arpeggios"],"prerequisites":["l9-picking-systems","l8-chord-tones"],"categories":["technique","chords"],"sources":[{"book":"P","note":"Sweep picking"}],"why":"Sweep picking plays arpeggios at high speed with a single raking motion. It requires solid picking coordination and arpeggio knowledge, which is why it comes after both.","explanation":[{"type":"p","text":"A sweep is one continuous pick motion across several strings, one note per string: a downward sweep for ascending notes, an upward sweep descending. The pick should \"fall\" through the strings with a controlled push, not a strum."},{"type":"p","text":"The fretting hand must let each note sound and then mute it before the next, otherwise the arpeggio becomes a strummed chord. Rolling the fingertip across adjacent strings at the same fret, and releasing pressure after each note, keeps notes separate."},{"type":"callout","tone":"warning","text":"Practise sweeps slowly enough that each note is distinct. A blurry sweep at speed is worse than a clean one at half speed."}],"guitar":[{"type":"tab","ascii":"e|-----------5---------------|\nB|---------5---5-------------|\nG|-------5-------5-----------|\nD|-----7-----------7---------|\nA|-5h8---------------8p5-----|","caption":"Original five-string A minor arpeggio: downward sweep from D to e, upward sweep back, with legato on the A string."},{"type":"tab","ascii":"e|-----8-------|\nB|---8---8-----|\nG|-9-------9---|","caption":"Three-string C major triad: start here."}],"exercise":{"title":"Sweep ladder","steps":["Three-string triad sweep at 50 BPM triplets, checking note separation.","Five-string A minor arpeggio, very slowly.","Technique Lab: three-string then five-string sweep exercises."],"exerciseId":"ex-sweep-3string"},"metronome":{"bpmStart":50,"bpmTarget":120,"subdivision":3,"instructions":"Triplets suit three-string sweeps."},"mistakes":["Notes ringing together like a strum.","Uneven rhythm: the sweep rushes.","Starting too fast."],"selfCheck":["Every note of my three-string sweep is separate."],"realWorld":"Neoclassical and technical metal guitarists use sweeps for fast arpeggios.","summary":["One motion per direction.","Separate notes with rolling and muting.","Slow and clean first."],"next":"l9-tapping","mastery":{"quizPass":0.67,"practice":{"exerciseId":"ex-sweep-3string","bpm":80},"criteria":["Score at least 2 of 3.","Log a clean three-string sweep at 80 bpm triplets."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9w-1', 'l9-sweep', 'In a sweep, the pick…', '["Alternates strictly","Moves in one continuous motion across strings","Stays on one string","Is replaced by fingers"]'::jsonb, 1, 'One stroke direction per sweep.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
