insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l9-tapping', 'm9-techniques', 9, 'Tapping and two-handed tapping', 35, array['Tap notes with the picking hand', 'Play triplet tapping patterns', 'Mute effectively while tapping']::text[], array['l9-legato-advanced']::text[], array['technique']::text[], '[{"book":"P","note":"Tapping technique"}]'::jsonb, '{"quizPass":1,"practice":{"exerciseId":"ex-tap-triplet","bpm":90},"criteria":["Answer both questions.","Log a clean tapping take at 90 bpm."]}'::jsonb, 65) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l9-tapping', '{"id":"l9-tapping","level":9,"module":"m9-techniques","title":"Tapping and two-handed tapping","minutes":35,"objectives":["Tap notes with the picking hand","Play triplet tapping patterns","Mute effectively while tapping"],"prerequisites":["l9-legato-advanced"],"categories":["technique"],"sources":[{"book":"P","note":"Tapping technique"}],"why":"Tapping extends legato to wide intervals and very fast note groups, a signature sound in rock and metal.","explanation":[{"type":"p","text":"Tap the string with the index or middle finger of the picking hand (holding the pick with the remaining fingers), then pull off to a fretted note, then pull off or hammer within the fretting hand. A classic pattern: tap 12, pull off to 5, hammer to 8, repeat, in triplets."},{"type":"p","text":"Muting is crucial: the fretting hand''s spare fingers mute strings below; the picking-hand palm mutes strings above. Some players use a fret wrap or hair tie at the nut while practising."},{"type":"callout","tone":"tip","text":"Pull off slightly downward (toward the floor) with the tapping finger to pluck the string, just like a fretting-hand pull-off."}],"guitar":[{"type":"tab","ascii":"         T     T     T     T\nB|-12p5h8-12p5h8-13p5h8-13p5h8-|","caption":"Original triplet tapping cell on the B string (T = tap)."}],"exercise":{"title":"Tap triplets","steps":["Tap 12-5-8 triplets on the B string at 60 BPM, focusing on evenness.","Move the tapped note to 13, 15 and 17 while keeping the fretted notes.","Technique Lab: one-string triplet tapping exercise."],"exerciseId":"ex-tap-triplet"},"metronome":{"bpmStart":60,"bpmTarget":140,"subdivision":3,"instructions":"One tap per beat."},"mistakes":["Tapped note quieter than the others.","Open strings ringing."],"selfCheck":["My tapping triplets are even and quiet strings stay silent."],"realWorld":"Tapping licks are a hallmark of 1980s rock and modern technical metal.","summary":["Tap, pull off, hammer.","Triplet cells for evenness.","Mute with both hands."],"next":"l9-skipping-hybrid","mastery":{"quizPass":1,"practice":{"exerciseId":"ex-tap-triplet","bpm":90},"criteria":["Answer both questions.","Log a clean tapping take at 90 bpm."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9t-1', 'l9-tapping', 'In a tap–pull-off–hammer-on cell, the tapping finger…', '["Picks the string","Taps then pulls off to the fretted note","Bends the string","Mutes only"]'::jsonb, 1, 'Tap, then pull off to sound the fretted note.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9t-2', 'l9-tapping', 'Why is muting critical for tapping?', '["Tapping is quiet","Hammer and pull motions set other strings ringing","It changes the key","It is not critical"]'::jsonb, 1, 'Legato motions excite idle strings.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l9-skipping-hybrid', 'm9-techniques', 9, 'String skipping and hybrid picking', 35, array['Skip strings accurately with alternate picking', 'Play wide-interval arpeggios', 'Combine pick and fingers (hybrid picking)']::text[], array['l9-picking-systems']::text[], array['technique']::text[], '[{"book":"C","section":"Hybrid picking in a blues turnaround"},{"book":"P"}]'::jsonb, '{"quizPass":1,"practice":{"exerciseId":"ex-skip-octaves","bpm":90},"criteria":["Answer both questions.","Log a clean string-skipping take at 90 bpm."]}'::jsonb, 66) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l9-skipping-hybrid', '{"id":"l9-skipping-hybrid","level":9,"module":"m9-techniques","title":"String skipping and hybrid picking","minutes":35,"objectives":["Skip strings accurately with alternate picking","Play wide-interval arpeggios","Combine pick and fingers (hybrid picking)"],"prerequisites":["l9-picking-systems"],"categories":["technique"],"sources":[{"book":"C","section":"Hybrid picking in a blues turnaround"},{"book":"P"}],"why":"String skipping creates wide, modern intervals; hybrid picking lets you play country-style double stops, chicken pickin'' and clean arpeggios.","explanation":[{"type":"p","text":"String skipping means jumping over one or more strings between notes. Keep the pick motion small and aim for the target string; mute the skipped string with the palm."},{"type":"p","text":"Hybrid picking holds the pick between thumb and index and uses the middle and ring fingers to pluck higher strings. It allows simultaneous notes on non-adjacent strings and snappy, percussive attacks."}],"guitar":[{"type":"tab","ascii":"e|-------5-8-----------|\nB|---------------------|\nG|-5-7---------7-5-----|","caption":"Original string-skipping figure (G to high E, skipping B)."},{"type":"tab","ascii":"e|---3-----3-----|\nB|---------------|\nG|-0-----0-------|\n     m     m      (pick on G, middle finger on e)","caption":"Hybrid-picking pattern."}],"exercise":{"title":"Skip and pluck","steps":["Octave skips: play notes on the E and D strings an octave apart, alternating, 2 minutes.","Play the skipping figure cleanly at 80 BPM.","Hybrid-pick G string with the pick and high E with the middle finger."],"exerciseId":"ex-skip-octaves"},"metronome":{"bpmStart":60,"bpmTarget":120,"subdivision":2,"instructions":"Eighths, then sixteenths."},"mistakes":["Hitting the skipped string.","Fingers plucking too hard compared with the pick."],"selfCheck":["I can skip strings at 100 BPM without hitting the wrong string."],"realWorld":"Country, rockabilly and modern rock use hybrid picking; string-skipping arpeggios are common in rock solos.","summary":["Small motions, accurate aim.","Mute skipped strings.","Pick + fingers = hybrid."],"next":"l9-expressive","mastery":{"quizPass":1,"practice":{"exerciseId":"ex-skip-octaves","bpm":90},"criteria":["Answer both questions.","Log a clean string-skipping take at 90 bpm."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
