insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l9h-2', 'l9-skipping-hybrid', 'In string skipping, the skipped string should be…', '["Played lightly","Muted","Bent","Retuned"]'::jsonb, 1, 'Mute it to avoid accidental noise.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l9-expressive', 'm9-techniques', 9, 'Expressive tools: bend accuracy, pre-bends, vibrato control, harmonics, whammy, tremolo and trills', 40, array['Bend accurately to quarter, half, whole and 1½ steps', 'Use pre-bends and releases', 'Produce natural, pinch and artificial harmonics', 'Apply tremolo picking, trills, octaves and whammy techniques']::text[], array['l5-bends-vibrato', 'l9-speed-system']::text[], array['technique']::text[], '[{"book":"C","section":"Pre-bends, trills"},{"book":"P","note":"Advanced expressive techniques"}]'::jsonb, '{"quizPass":0.67,"practice":{"exerciseId":"ex-tremolo","bpm":120},"criteria":["Score at least 2 of 3.","Log a clean tremolo-picking take at 120 bpm."]}'::jsonb, 67) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l9-expressive', '{"id":"l9-expressive","level":9,"module":"m9-techniques","title":"Expressive tools: bend accuracy, pre-bends, vibrato control, harmonics, whammy, tremolo and trills","minutes":40,"objectives":["Bend accurately to quarter, half, whole and 1½ steps","Use pre-bends and releases","Produce natural, pinch and artificial harmonics","Apply tremolo picking, trills, octaves and whammy techniques"],"prerequisites":["l5-bends-vibrato","l9-speed-system"],"categories":["technique"],"sources":[{"book":"C","section":"Pre-bends, trills"},{"book":"P","note":"Advanced expressive techniques"}],"why":"Technique becomes music through expression. These tools give you a personal voice: pitch inflection, shimmering harmonics and dramatic textures.","explanation":[{"type":"table","head":["Technique","How"],"rows":[["Pre-bend","Bend silently to the target pitch, pick, then release down. Accuracy depends on muscle memory: check against the target note."],["Bend accuracy","Practise ¼, ½, 1 and 1½ step bends against fretted target notes and the tuner."],["Vibrato control","Choose speed and width deliberately; synchronise with the tempo (e.g. eighth-note cycles)."],["Natural harmonics","Touch the string lightly directly above frets 12, 7 or 5 and pick; lift immediately."],["Pinch harmonics","Let the side of the thumb graze the string just after the pick strikes; move along the string to find the squeal."],["Artificial harmonics","Fret a note, touch the string 12 frets higher with the picking-hand index and pluck with the thumb or ring finger."],["Tremolo picking","Rapid, even alternate picking of one note; relax the wrist and lock to sixteenths or thirty-seconds."],["Trills","Rapid hammer-pull between two frets."],["Octaves","Fret a note and its octave two strings up; mute the string between with the underside of the first finger."],["Whammy bar","Dips, dive-bombs, vibrato and flutter; keep the guitar in tune by returning the bar gently."],["Muting","Combine palm and fretting-hand muting for silence under high gain."]]},{"type":"callout","tone":"warning","text":"Whammy techniques require a tremolo bridge. On fixed-bridge guitars, practise bends and vibrato instead."}],"guitar":[{"type":"tab","ascii":"e|---------------------------------|\nB|-<12>--<7>--<5>-----------8--10--|\nG|-----------------7pb9~r7---------|\nD|--------------------------5--7---|","caption":"Natural harmonics at 12, 7 and 5; a pre-bend with vibrato and release; then octaves (D string + B string, G string muted)."}],"exercise":{"title":"Expression workout","steps":["Bend fret 7 on the G string to ½, 1 and 1½ steps, checking with the tuner.","Play natural harmonics at 12, 7 and 5 on all strings.","Tremolo-pick one note for 30 seconds at 16ths, 120 BPM.","Technique Lab: tremolo and harmonics exercises."],"exerciseId":"ex-tremolo"},"metronome":{"bpmStart":80,"bpmTarget":160,"subdivision":4,"instructions":"Sixteenths for tremolo picking."},"mistakes":["Flat bends and pre-bends.","Pressing too hard for harmonics (touch lightly).","Tense tremolo picking."],"selfCheck":["My 1½-step bends are in tune.","I can produce pinch harmonics on demand."],"realWorld":"Expressive control is what makes a guitarist recognisable after a single note.","summary":["Accurate bends and controlled vibrato.","Three kinds of harmonics.","Tremolo, trills, octaves and whammy for texture."],"next":"l10-motifs","mastery":{"quizPass":0.67,"practice":{"exerciseId":"ex-tremolo","bpm":120},"criteria":["Score at least 2 of 3.","Log a clean tremolo-picking take at 120 bpm."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
