insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l10-motifs', 'm10-language', 10, 'Motifs: repetition, variation and development', 35, array['Invent short motifs', 'Develop them by repetition, rhythmic change, transposition and extension', 'Build a solo from one idea']::text[], array['l5-blues-phrasing']::text[], array['improvisation']::text[], '[{"book":"P","note":"Motivic development"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions.","Complete the motif challenge."]}'::jsonb, 68) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l10-motifs', '{"id":"l10-motifs","level":10,"module":"m10-language","title":"Motifs: repetition, variation and development","minutes":35,"objectives":["Invent short motifs","Develop them by repetition, rhythmic change, transposition and extension","Build a solo from one idea"],"prerequisites":["l5-blues-phrasing"],"categories":["improvisation"],"sources":[{"book":"P","note":"Motivic development"}],"why":"Memorable solos are built from ideas that return and evolve. Motivic development gives solos coherence and makes them sound composed even when improvised.","explanation":[{"type":"p","text":"A motif is a short musical idea, 3 to 6 notes with a distinctive rhythm. Development techniques: repeat it exactly; change one note; change the rhythm; start it on a different beat; move it to another scale degree (sequence); extend or shorten it; invert its direction."},{"type":"p","text":"A solo built on one motif feels like a story: statement, variations, climax, return."}],"guitar":[{"type":"tab","ascii":"   motif          sequence (up a step)   rhythmic variation\nB|-8-5-----------10-8-----------8--8-5--|\nG|------7-----------9-------------------|\nD|---------------------------------7----|","caption":"Original A minor motif, its sequence, and a rhythmic variation ending lower."}],"exercise":{"title":"One idea, one solo","steps":["Invent a motif over an A minor groove.","Play it 8 times, varying it each time with a different technique.","Complete the \"Develop a motif\" Jam Lab challenge."]},"mistakes":["Abandoning ideas after one play.","Varying so much that the motif is unrecognisable."],"selfCheck":["I can develop one motif across a whole chorus."],"realWorld":"Many classic guitar solos are built from a single developed idea.","summary":["Short, rhythmic ideas.","Repeat, vary, sequence, extend.","Tell a story with one motif."],"next":"l10-targeting","mastery":{"quizPass":1,"criteria":["Answer both questions.","Complete the motif challenge."]},"unlocks":{"challenges":["motif"]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
