insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l10m-2', 'l10-motifs', 'Why use motifs?', '["They give solos coherence and memorability","They make solos longer","They avoid chord tones","They are faster"]'::jsonb, 0, 'Recurring ideas make music easier to follow and remember.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l10-targeting', 'm10-language', 10, 'Target notes, connecting scales and blending pentatonic with modes', 35, array['Plan target notes for each chord', 'Connect scale positions around targets', 'Blend pentatonic and modal sounds']::text[], array['l8-chord-tones', 'l10-motifs']::text[], array['improvisation']::text[], '[{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions."]}'::jsonb, 69) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l10-targeting', '{"id":"l10-targeting","level":10,"module":"m10-language","title":"Target notes, connecting scales and blending pentatonic with modes","minutes":35,"objectives":["Plan target notes for each chord","Connect scale positions around targets","Blend pentatonic and modal sounds"],"prerequisites":["l8-chord-tones","l10-motifs"],"categories":["improvisation"],"sources":[{"book":"P"}],"why":"Targets are the skeleton of a solo; scales are the muscles. Planning where phrases land makes improvisation purposeful.","explanation":[{"type":"p","text":"Choose a target note for each chord change (usually the 3rd or 7th) and improvise toward it. Arriving exactly on the beat of the change makes the harmony audible in your line."},{"type":"p","text":"Pentatonic–modal blending: the pentatonic is a five-note skeleton of a seven-note mode. Add the two missing notes for colour: A minor pentatonic + B + F♯ = A Dorian; + B + F = A Aeolian. Start phrases with pentatonic licks and finish with the mode''s characteristic note."}],"guitar":[{"type":"fretboard","root":"A","scale":"dorian","minFret":4,"maxFret":9,"labels":"interval","caption":"A Dorian: the minor pentatonic plus 2 (B) and 6 (F♯)."}],"exercise":{"title":"Aim and fire","steps":["Over a I–IV–V in A, write down the 3rd of each chord, then improvise landing on each.","Over an A Dorian vamp, alternate between pentatonic phrases and phrases featuring F♯."]},"mistakes":["Choosing targets but arriving late."],"selfCheck":["I can hit planned targets on chord changes."],"realWorld":"Rock players blend pentatonic and modal sounds constantly; jazz players plan targets.","summary":["Plan targets, arrive on time.","Pentatonic = skeleton; modes add colour."],"next":"l10-chromatic","mastery":{"quizPass":1,"criteria":["Answer both questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l10t-1', 'l10-targeting', 'A minor pentatonic plus 2 and 6 gives…', '["A Aeolian","A Dorian","A Phrygian","A Lydian"]'::jsonb, 1, 'The natural 6 makes it Dorian.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
