insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l10-chromatic', 'm10-language', 10, 'Chromatic approaches, passing tones and enclosures', 35, array['Approach target notes chromatically', 'Use passing tones between scale notes', 'Play enclosures around targets']::text[], array['l10-targeting']::text[], array['improvisation']::text[], '[{"book":"C","section":"Blues scale ♭5 as a passing note"},{"book":"P","note":"Chromatic approach techniques"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions."]}'::jsonb, 70) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l10-chromatic', '{"id":"l10-chromatic","level":10,"module":"m10-language","title":"Chromatic approaches, passing tones and enclosures","minutes":35,"objectives":["Approach target notes chromatically","Use passing tones between scale notes","Play enclosures around targets"],"prerequisites":["l10-targeting"],"categories":["improvisation"],"sources":[{"book":"C","section":"Blues scale ♭5 as a passing note"},{"book":"P","note":"Chromatic approach techniques"}],"why":"Chromatic notes add sophistication and forward motion. Placed on weak beats and resolving to chord tones, \"outside\" notes sound intentional.","explanation":[{"type":"p","text":"A chromatic approach note sits a half step below (or above) a target and resolves to it. Passing tones connect two scale notes by half steps (the blues scale''s ♭5 between 4 and 5 is the classic example). An enclosure surrounds a target: a note above, a note below, then the target."},{"type":"p","text":"Rule of thumb: put the chromatic note on a weak beat or off-beat and the target on the strong beat."}],"guitar":[{"type":"tab","ascii":"G|-------------------------|\nB|-4-5-----6-4-5-----------|\n   ^approach  ^enclosure → E (B string, fret 5)","caption":"Original: chromatic approach from below, then an enclosure (above, below, target)."}],"exercise":{"title":"Outside, then home","steps":["Over A7, approach C♯ (the 3rd) from C and from D.","Enclose E (the 5th) over A7 with F and D♯.","Use one chromatic approach per phrase in a blues solo."]},"mistakes":["Landing chromatic notes on strong beats."],"selfCheck":["I can enclose any chord tone."],"realWorld":"Bebop lines and blues licks use approaches and passing tones constantly.","summary":["Approach from a half step away.","Passing tones connect scale notes.","Enclose targets; resolve on strong beats."],"next":"l10-rhythm-space","mastery":{"quizPass":1,"criteria":["Answer both questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l10c-1', 'l10-chromatic', 'An enclosure is…', '["A slide into the target","Notes above and below the target before resolving to it","A bend","A rest"]'::jsonb, 1, 'Surround, then resolve.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l10c-2', 'l10-chromatic', 'Chromatic approach notes sound best on…', '["Strong beats","Weak beats or off-beats, resolving to strong-beat targets","Only the last note","Anywhere, equally"]'::jsonb, 1, 'Tension on weak beats, resolution on strong beats.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l10-rhythm-space', 'm10-language', 10, 'Rhythmic variation, space, phrasing, tension and resolution', 35, array['Vary rhythm deliberately', 'Shape solos with space and dynamics', 'Build and release tension across a solo']::text[], array['l10-motifs', 'l4-subdivisions']::text[], array['improvisation', 'rhythm']::text[], '[{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions."]}'::jsonb, 71) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l10-rhythm-space', '{"id":"l10-rhythm-space","level":10,"module":"m10-language","title":"Rhythmic variation, space, phrasing, tension and resolution","minutes":35,"objectives":["Vary rhythm deliberately","Shape solos with space and dynamics","Build and release tension across a solo"],"prerequisites":["l10-motifs","l4-subdivisions"],"categories":["improvisation","rhythm"],"sources":[{"book":"P"}],"why":"Rhythm and space are the most overlooked improvisation tools. The same notes with better rhythm sound like a different, better solo.","explanation":[{"type":"list","items":["Rhythmic displacement: start a phrase on a different beat or off-beat.","Density contrast: alternate sparse long notes with bursts of fast notes.","Space: rests as long as phrases.","Tension sources: high register, repetition, chromaticism, faster notes, held bends.","Resolution: return to chord tones, lower register, longer notes."]},{"type":"p","text":"Shape a solo like a story: low and sparse at the start, building intensity, a climax (often the highest note), then resolution. Dynamics matter: use the guitar''s volume knob and picking strength."}],"guitar":[{"type":"p","text":"Improvise one chorus using only quarter notes, the next using only eighths, the next mixing them with long rests. Record each and compare."}],"exercise":{"title":"Rhythm-first solo","steps":["Over a minor groove, improvise with only two notes but varied rhythm.","Plan a chorus: bars 1–4 sparse, 5–8 busier, 9–12 climax and resolve."]},"mistakes":["Constant eighth notes with no space.","Climaxing in the first bar."],"selfCheck":["My solos have a clear shape."],"realWorld":"Great soloists are recognisable by their rhythmic phrasing as much as their note choice.","summary":["Vary rhythm and density.","Use space.","Shape tension and resolution."],"next":"l10-styles","mastery":{"quizPass":1,"criteria":["Answer both questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l10r-1', 'l10-rhythm-space', 'Which builds tension?', '["Long notes on the root","Ascending to a high register with faster notes","Silence","Ending on the root"]'::jsonb, 1, 'Register and density increase tension.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l10r-2', 'l10-rhythm-space', 'Rhythmic displacement means…', '["Playing out of time","Starting a phrase on a different beat","Changing tempo","Playing faster"]'::jsonb, 1, 'Same idea, new position in the bar.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l10-styles', 'm10-styles', 10, 'Improvising in style: blues, rock, metal and fusion', 40, array['Recognise the vocabulary of four styles', 'Adapt scale choice, technique and phrasing to style', 'Improvise at different tempos']::text[], array['l10-rhythm-space', 'l10-chromatic']::text[], array['improvisation', 'jamming']::text[], '[{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions."]}'::jsonb, 72) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l10-styles', '{"id":"l10-styles","level":10,"module":"m10-styles","title":"Improvising in style: blues, rock, metal and fusion","minutes":40,"objectives":["Recognise the vocabulary of four styles","Adapt scale choice, technique and phrasing to style","Improvise at different tempos"],"prerequisites":["l10-rhythm-space","l10-chromatic"],"categories":["improvisation","jamming"],"sources":[{"book":"P"}],"why":"Each style has its own language. Speaking it convincingly means adapting scales, techniques, tone and rhythm, not just notes.","explanation":[{"type":"table","head":["Style","Scales","Techniques","Phrasing"],"rows":[["Blues","Minor & major pentatonic, blues scale, Mixolydian","Bends, vibrato, slides, call & response","Vocal, behind the beat, lots of space"],["Rock","Pentatonic + Aeolian/Dorian/Mixolydian","Bends, legato, double stops, repeated licks","Riff-based, energetic, on the beat"],["Metal","Aeolian, Phrygian, harmonic minor, diminished","Alternate picking, sweeps, tapping, tremolo","Precise, fast runs, dramatic climaxes"],["Fusion","Dorian, Lydian, melodic minor modes, chromaticism","Legato, outside playing, wide intervals","Long lines, chord-scale awareness"]]},{"type":"p","text":"Tempo changes the vocabulary too: slow blues allows long held notes; fast tempos favour shorter motifs and rhythmic punch."}],"guitar":[{"type":"p","text":"In the Jam Lab, play the same 4-bar idea over Blues, Hard rock, Heavy metal and Fusion styles, adapting it to each."}],"exercise":{"title":"Style switching","steps":["Improvise one chorus in each style with appropriate scales and techniques.","Try each at a slow and a fast tempo."]},"mistakes":["Playing the same licks in every style."],"selfCheck":["Bandmates could tell which style I am improvising in."],"realWorld":"Session players switch styles daily; versatility is employability.","summary":["Styles differ in scales, technique, phrasing and tone.","Adapt to tempo."],"next":"l11-key-finding","mastery":{"quizPass":1,"criteria":["Answer both questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l10s-1', 'l10-styles', 'Which scale is most associated with neoclassical metal?', '["Major pentatonic","Harmonic minor","Mixolydian","Whole tone"]'::jsonb, 1, 'Harmonic minor and Phrygian dominant.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
