insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l11-key-finding', 'm11-jamming', 11, 'Finding the key and hearing chord changes', 35, array['Find the key of a song by ear', 'Recognise common chord changes by ear', 'Follow a progression you have never heard before']::text[], array['l3-diatonic-chords', 'l2-pitch']::text[], array['ear', 'jamming']::text[], '[{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions.","Reach 80% on progression ear training level 1."]}'::jsonb, 73) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l11-key-finding', '{"id":"l11-key-finding","level":11,"module":"m11-jamming","title":"Finding the key and hearing chord changes","minutes":35,"objectives":["Find the key of a song by ear","Recognise common chord changes by ear","Follow a progression you have never heard before"],"prerequisites":["l3-diatonic-chords","l2-pitch"],"categories":["ear","jamming"],"sources":[{"book":"P"}],"why":"In real jams nobody hands you a chart. Hearing the key and the changes lets you join in within seconds.","explanation":[{"type":"list","items":["Find home: hum the note the song feels like it rests on. Find it on the guitar.","Test major or minor: play a major then a minor chord on that note; one will fit.","Check with the scale: play the key''s scale quietly; if no notes clash, you have it.","Hear changes: follow the bass. Rising a 4th (or falling a 5th) is often I → IV; rising a 5th, I → V; falling a minor 3rd, I → vi."],"ordered":true},{"type":"callout","tone":"tip","text":"Most songs use I, IV, V and vi. Guess those first."}],"guitar":[{"type":"p","text":"Ear Training → Progressions levels 1–2. Then play along with any song you like: find the key in under 30 seconds."}],"exercise":{"title":"Key detective","steps":["Find the key of three songs by ear.","Write the progression of one as Roman numerals.","Reach 80% in progression ear training level 1."]},"mistakes":["Assuming the first chord is the key."],"selfCheck":["I can find the key of most songs in under a minute."],"realWorld":"This is the core jam-session skill.","summary":["Find home, test quality, check with the scale.","Follow the bass to hear changes."],"next":"l11-band","mastery":{"quizPass":1,"criteria":["Answer both questions.","Reach 80% on progression ear training level 1."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l11k-1', 'l11-key-finding', 'The quickest way to find a song''s key is to…', '["Look at the singer","Find the note the music resolves to, then test major/minor","Count bars","Use the highest note"]'::jsonb, 1, 'Home note first, then quality.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
