insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l11-band', 'm11-jamming', 11, 'Playing with drummers and bassists: groove, comping and trading solos', 35, array['Lock in with a rhythm section', 'Comp tastefully behind a soloist or singer', 'Trade solos (fours and eights)']::text[], array['l4-groove', 'l8-inversions']::text[], array['jamming', 'rhythm']::text[], '[{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions."]}'::jsonb, 74) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l11-band', '{"id":"l11-band","level":11,"module":"m11-jamming","title":"Playing with drummers and bassists: groove, comping and trading solos","minutes":35,"objectives":["Lock in with a rhythm section","Comp tastefully behind a soloist or singer","Trade solos (fours and eights)"],"prerequisites":["l4-groove","l8-inversions"],"categories":["jamming","rhythm"],"sources":[{"book":"P"}],"why":"In a band, what you leave out matters as much as what you play. Rhythm-section awareness makes you the guitarist people want to play with.","explanation":[{"type":"list","items":["Lock with the kick drum and the bass; accent where they accent.","Stay out of the bass register when comping: use triads and small voicings on the top strings.","Comping: support the soloist with sparse, rhythmic chords; respond to their phrases.","Trading fours: soloists alternate 4-bar solos; listen and pick up the previous player''s idea.","Dynamics: play softer behind vocals, build into choruses."]}],"guitar":[{"type":"p","text":"In the Jam Lab, mute the chord track and comp with small triads over drums and bass. Then alternate 4 bars of comping with 4 bars of soloing."}],"exercise":{"title":"Band simulation","steps":["Comp over the \"Funk\" style using short 9th-chord stabs on the off-beats.","Trade fours with yourself: 4 bars solo, 4 bars comp, for three choruses."]},"mistakes":["Playing full six-string chords that clash with keys and bass.","Overplaying behind the soloist."],"selfCheck":["I can comp without getting in the way."],"realWorld":"Every band rehearsal and jam session uses these skills.","summary":["Lock with kick and bass.","Comp small and sparse.","Trade solos by listening."],"next":"l11-song-structure","mastery":{"quizPass":1,"criteria":["Answer both questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l11b-1', 'l11-band', 'When comping behind a soloist you should…', '["Play as much as possible","Play sparse, supportive rhythms and leave space","Solo at the same time","Stop playing"]'::jsonb, 1, 'Support, do not compete.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l11b-2', 'l11-band', '"Trading fours" means…', '["Playing four chords","Soloists alternating four-bar solos","Four guitarists","Changing tuning four times"]'::jsonb, 1, 'Alternating short solos.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l11-song-structure', 'm11-jamming', 11, 'Song structure, chart navigation and live performance', 30, array['Recognise intro, verse, chorus, bridge and outro', 'Read repeat signs, endings, D.S. and coda', 'Prepare for performance']::text[], array['l11-band']::text[], array['repertoire', 'jamming']::text[], '[{"book":"B","section":"Chart navigation: rhythm figures, endings, D.S./coda markings"},{"book":"A","section":"1st and 2nd endings"},{"book":"P","note":"Performance preparation"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions.","Play a complete song without stopping."]}'::jsonb, 75) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l11-song-structure', '{"id":"l11-song-structure","level":11,"module":"m11-jamming","title":"Song structure, chart navigation and live performance","minutes":30,"objectives":["Recognise intro, verse, chorus, bridge and outro","Read repeat signs, endings, D.S. and coda","Prepare for performance"],"prerequisites":["l11-band"],"categories":["repertoire","jamming"],"sources":[{"book":"B","section":"Chart navigation: rhythm figures, endings, D.S./coda markings"},{"book":"A","section":"1st and 2nd endings"},{"book":"P","note":"Performance preparation"}],"why":"Knowing where you are in a song, and how charts tell you where to go, prevents train wrecks on stage.","explanation":[{"type":"p","text":"Common forms: verse–chorus (V C V C bridge C), AABA (32-bar standards), and the 12-bar blues. Charts compress repetition with symbols: repeat signs (|: :|), 1st and 2nd endings, D.S. (go back to the sign), D.C. (go back to the start), \"al Coda\" (jump to the coda when you reach the coda symbol)."},{"type":"list","items":["Performance checklist: tuned instrument and spare strings, set list with keys and tempos, a backup cable, a quick sound check routine, and a plan for mistakes: keep going, never stop.","Rehearse transitions between sections more than the sections themselves."]}],"guitar":[{"type":"p","text":"In the Tab Editor, write a two-section exercise with a repeat and first/second endings; check the playback order."}],"exercise":{"title":"Gig ready","steps":["Map the structure of a song you know (sections and bar counts).","Play it start to finish without stopping, even through mistakes.","Record yourself performing it."]},"mistakes":["Stopping after a mistake.","Not knowing how many bars each section lasts."],"selfCheck":["I can play a full song without stopping."],"realWorld":"Professional musicians rehearse structure and transitions so performances stay solid under pressure.","summary":["Know the form.","Read navigation symbols.","Never stop on stage."],"next":"l12-advanced-harmony","mastery":{"quizPass":1,"criteria":["Answer both questions.","Play a complete song without stopping."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l11s-1', 'l11-song-structure', '"D.S. al Coda" means…', '["Play faster","Go back to the sign, then jump to the coda at the coda symbol","End now","Repeat the first bar"]'::jsonb, 1, 'Back to the segno, then to the coda.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l11s-2', 'l11-song-structure', 'If you make a mistake on stage you should…', '["Stop and restart","Keep going in time","Apologise","Play louder"]'::jsonb, 1, 'The audience rarely notices if you keep the groove.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l12-advanced-harmony', 'm12-artistry', 12, 'Advanced harmony and arpeggios for jazz and fusion', 40, array['Use extended arpeggios (maj9, m11, 13)', 'Apply upper-structure triads', 'Navigate ii–V–I progressions with chord-scale awareness']::text[], array['l8-chord-scale', 'l8-extended']::text[], array['theory', 'improvisation', 'chords']::text[], '[{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions."]}'::jsonb, 76) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l12-advanced-harmony', '{"id":"l12-advanced-harmony","level":12,"module":"m12-artistry","title":"Advanced harmony and arpeggios for jazz and fusion","minutes":40,"objectives":["Use extended arpeggios (maj9, m11, 13)","Apply upper-structure triads","Navigate ii–V–I progressions with chord-scale awareness"],"prerequisites":["l8-chord-scale","l8-extended"],"categories":["theory","improvisation","chords"],"sources":[{"book":"P"}],"why":"Advanced harmony unlocks jazz, fusion and sophisticated rock. Thinking in extensions and upper structures gives instant, colourful vocabulary.","explanation":[{"type":"p","text":"Extended arpeggios continue the stack of thirds: Cmaj9 = C E G B D. Playing the arpeggio from the 3rd (E G B D = Em7) over C gives a Cmaj9 sound: this \"arpeggio substitution\" is a quick way to access extensions."},{"type":"p","text":"Upper-structure triads: over a dominant chord, play a triad built on another degree to imply tensions. Over C7, a D major triad (D F♯ A) implies 9, ♯11 and 13; an A♭ major triad implies ♭13, root and ♯9."},{"type":"p","text":"ii–V–I navigation: Dm7 (Dorian) – G7 (Mixolydian or altered) – Cmaj7 (Ionian/Lydian). Connect guide tones: F (♭3 of Dm7) → F (♭7 of G7) → E (3 of Cmaj7)."}],"guitar":[{"type":"chord","symbols":["Dm9","G13","Cmaj9"],"caption":"A lush ii–V–I."}],"exercise":{"title":"Extensions in context","steps":["Over Cmaj7, play Em7 and G major arpeggios: hear the 9 and 7.","Over G7, try a D triad and then an E♭ triad (♭13, root, ♭9 colours).","Play guide-tone lines through a ii–V–I in three keys."]},"mistakes":["Using upper structures without resolving."],"selfCheck":["I can outline a ii–V–I with guide tones."],"realWorld":"Jazz guitarists use these devices daily; fusion and prog players borrow them for colour.","summary":["Extended arpeggios and substitutions.","Upper-structure triads.","Guide-tone lines through ii–V–I."],"next":"l12-neoclassical-prog","mastery":{"quizPass":1,"criteria":["Answer both questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l12a-1', 'l12-advanced-harmony', 'Playing Em7 over C produces which sound?', '["C7","Cmaj9","Cm7","Csus4"]'::jsonb, 1, 'E G B D over C = 3 5 7 9.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l12a-2', 'l12-advanced-harmony', 'Over C7, a D major triad implies…', '["♭9 ♯9","9 ♯11 13","♭5 ♯5","Root 3 5"]'::jsonb, 1, 'D F♯ A = 9, ♯11, 13 of C.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l12-neoclassical-prog', 'm12-artistry', 12, 'Neoclassical guitar and progressive metal', 40, array['Use harmonic minor, diminished arpeggios and pedal-point lines', 'Play in odd meters and with polyrhythms', 'Combine extended-range guitars and drop tunings musically']::text[], array['l9-sweep', 'l7-minor-modes', 'l4-tempo-time']::text[], array['technique', 'rhythm', 'scales']::text[], '[{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions."]}'::jsonb, 77) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l12-neoclassical-prog', '{"id":"l12-neoclassical-prog","level":12,"module":"m12-artistry","title":"Neoclassical guitar and progressive metal","minutes":40,"objectives":["Use harmonic minor, diminished arpeggios and pedal-point lines","Play in odd meters and with polyrhythms","Combine extended-range guitars and drop tunings musically"],"prerequisites":["l9-sweep","l7-minor-modes","l4-tempo-time"],"categories":["technique","rhythm","scales"],"sources":[{"book":"P"}],"why":"Neoclassical and progressive metal combine advanced technique with classical harmony and complex rhythm. They test everything you have learned.","explanation":[{"type":"list","items":["Neoclassical vocabulary: harmonic minor and Phrygian dominant runs, diminished 7th arpeggios (movable every three frets), pedal-point sequences (alternating a fixed note with a moving line), sweep-picked arpeggios following classical progressions (i–iv–V–i).","Progressive metal: odd meters (7/8, 5/4, 11/8), riffs that cycle against the bar line, polyrhythms (e.g. a 3-note riff over a 4/4 drum pattern), extended-range guitars and drop tunings, syncopated palm-muted riffs, and clean, ambient sections."]},{"type":"p","text":"Use the metronome''s odd-meter presets and the Jam Lab''s Progressive metal and Neoclassical styles. The fretboard and tab editor support 7- and 8-string tunings."}],"guitar":[{"type":"tab","ascii":"B|-10-9-10-6-10-9-10-5-10-9-10-6-10-9-10-3-|\n   pedal point on B string fret 10 (A harmonic minor)","caption":"Original pedal-point figure in A harmonic minor (G♯ at fret 9)."}],"exercise":{"title":"Prog and neoclassical lab","steps":["Play the pedal-point figure, then invent your own.","Play a 7/8 riff (2+2+3) on a low string for two minutes against the metronome.","Try an 8-string drop-E tuning on the fretboard and write a riff in the Tab Editor."]},"mistakes":["Technique without musical purpose.","Losing the downbeat in odd meters."],"selfCheck":["I can play a 7/8 riff and a pedal-point line in time."],"realWorld":"These styles demand precision and imagination in equal measure.","summary":["Harmonic minor, diminished, pedal points.","Odd meters and polyrhythms.","Extended range used musically."],"next":"l12-composition","mastery":{"quizPass":1,"criteria":["Answer both questions."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
