insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l12-composition', 'm12-artistry', 12, 'Composition, solo construction and signature phrasing', 40, array['Compose a short piece with sections', 'Construct a composed solo', 'Develop personal signature phrases']::text[], array['l10-styles', 'l11-song-structure']::text[], array['improvisation', 'repertoire']::text[], '[{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions.","Save an original 16-bar piece in the Tab Editor."]}'::jsonb, 78) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l12-composition', '{"id":"l12-composition","level":12,"module":"m12-artistry","title":"Composition, solo construction and signature phrasing","minutes":40,"objectives":["Compose a short piece with sections","Construct a composed solo","Develop personal signature phrases"],"prerequisites":["l10-styles","l11-song-structure"],"categories":["improvisation","repertoire"],"sources":[{"book":"P"}],"why":"Composition turns everything you know into something only you could have written. Composed solos and signature phrases become your musical identity.","explanation":[{"type":"list","items":["Start with a riff or chord progression (use the Jam Lab or Tab Editor).","Build sections: verse, chorus, bridge, contrasting in register, rhythm or key.","Compose a solo: write a motif, develop it, plan the climax, end on a resolving note.","Refine: cut what is unnecessary; every note should have a reason."],"ordered":true},{"type":"p","text":"Signature phrasing: notice the licks you naturally return to, then refine them: a particular bend, a rhythmic quirk, a favourite interval. Consistent use of personal devices is what makes famous players instantly recognisable."}],"guitar":[{"type":"p","text":"Write a 16-bar piece in the Tab Editor with a riff section and a composed 8-bar solo; save it as a custom exercise and practise it in the Practice Studio."}],"exercise":{"title":"Write it","steps":["Compose a 16-bar piece.","Record it and listen back critically.","List three phrases that feel like \"you\"."]},"mistakes":["Never finishing a piece.","Over-complicating."],"selfCheck":["I have finished and recorded an original piece."],"realWorld":"Original music is the destination of musical training.","summary":["Riff → sections → solo → refine.","Develop signature devices."],"next":"l12-transcription","mastery":{"quizPass":1,"criteria":["Answer both questions.","Save an original 16-bar piece in the Tab Editor."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l12c-1', 'l12-composition', 'A strong composed solo usually…', '["Uses every technique","Develops a motif toward a planned climax and resolution","Avoids repetition","Stays in one register"]'::jsonb, 1, 'Structure and development.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l12c-2', 'l12-composition', 'Signature phrasing comes from…', '["Copying one player exactly","Refining the devices you naturally return to","Avoiding all licks","Speed only"]'::jsonb, 1, 'Your recurring choices become your voice.', 1) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
insert into public.lessons (id, module_id, level_id, title, minutes, objectives, prerequisites, categories, sources, mastery, sort_order) values ('l12-transcription', 'm12-artistry', 12, 'Transcription, ear training, analysis and your guitar identity', 40, array['Transcribe solos and riffs by ear', 'Analyse what makes them work', 'Plan your ongoing development']::text[], array['l11-key-finding', 'l12-composition']::text[], array['ear', 'theory', 'repertoire']::text[], '[{"book":"D","section":"Practice: continuous mental reinforcement through improvising"},{"book":"P"}]'::jsonb, '{"quizPass":1,"criteria":["Answer both questions.","Transcribe and analyse 8 bars."]}'::jsonb, 79) on conflict (id) do update set module_id = excluded.module_id, level_id = excluded.level_id, title = excluded.title, minutes = excluded.minutes, objectives = excluded.objectives, prerequisites = excluded.prerequisites, categories = excluded.categories, sources = excluded.sources, mastery = excluded.mastery, sort_order = excluded.sort_order;
insert into public.lesson_content (lesson_id, content) values ('l12-transcription', '{"id":"l12-transcription","level":12,"module":"m12-artistry","title":"Transcription, ear training, analysis and your guitar identity","minutes":40,"objectives":["Transcribe solos and riffs by ear","Analyse what makes them work","Plan your ongoing development"],"prerequisites":["l11-key-finding","l12-composition"],"categories":["ear","theory","repertoire"],"sources":[{"book":"D","section":"Practice: continuous mental reinforcement through improvising"},{"book":"P"}],"why":"Transcription is how generations of musicians learned: by ear, from records. Analysing what you transcribe turns other people''s ideas into your vocabulary.","explanation":[{"type":"list","items":["Choose a short passage (4–8 bars).","Find the key and the chords first.","Sing each phrase, then find it on the guitar, a few notes at a time.","Write it in the Tab Editor, including rhythm and techniques.","Analyse: which scale, which chord tones on strong beats, which techniques, why it works.","Make it yours: play the idea in other keys and over other chords."],"ordered":true},{"type":"p","text":"Your guitar identity grows from the sum of your choices: the music you transcribe, the techniques you refine, the sounds you love. Keep a practice journal (the Practice Studio notes) and revisit your goals each month."}],"guitar":[{"type":"p","text":"Transcribe a short melody from any recording you have permission to listen to, enter it in the Tab Editor and analyse it with the Scale Explorer."}],"exercise":{"title":"Transcribe and analyse","steps":["Transcribe 8 bars of a solo by ear.","Write a paragraph analysing it.","Use one idea from it in your own improvisation."]},"mistakes":["Transcribing too much at once.","Skipping the analysis."],"selfCheck":["I have transcribed and analysed a solo."],"realWorld":"Transcription is the most effective lifelong learning habit for musicians.","summary":["Key and chords first, then notes.","Analyse and transfer ideas.","Your identity is built from your choices."],"mastery":{"quizPass":1,"criteria":["Answer both questions.","Transcribe and analyse 8 bars."]}}'::jsonb) on conflict (lesson_id) do update set content = excluded.content;
insert into public.questions (id, lesson_id, prompt, options, answer, explanation, sort_order) values ('l12t-1', 'l12-transcription', 'What should you identify first when transcribing?', '["The fastest lick","The key and chords","The guitar model","The tempo only"]'::jsonb, 1, 'Harmony gives context for every note.', 0) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explanation = excluded.explanation;
