tion":8,"notes":[{"string":4,"fret":1}]}]},{"beats":[{"duration":8,"notes":[{"string":3,"fret":4}]},{"duration":8,"notes":[{"string":3,"fret":3}]},{"duration":8,"notes":[{"string":3,"fret":2}]},{"duration":8,"notes":[{"string":3,"fret":1}]},{"duration":8,"notes":[{"string":2,"fret":4}]},{"duration":8,"notes":[{"string":2,"fret":3}]},{"duration":8,"notes":[{"string":2,"fret":2}]},{"duration":8,"notes":[{"string":2,"fret":1}]}]},{"beats":[{"duration":8,"notes":[{"string":1,"fret":4}]},{"duration":8,"notes":[{"string":1,"fret":3}]},{"duration":8,"notes":[{"string":1,"fret":2}]},{"duration":8,"notes":[{"string":1,"fret":1}]},{"duration":8,"notes":[{"string":0,"fret":4}]},{"duration":8,"notes":[{"string":0,"fret":3}]},{"duration":8,"notes":[{"string":0,"fret":2}]},{"duration":8,"notes":[{"string":0,"fret":1}]}]}]}'::jsonb, array['One finger per fret, frets 1–4, every string, up and back.', 'Alternate-pick every note; keep fingers close to the strings.']::text[], array['Lifting fingers high between notes.', 'Picking and fretting not landing together.']::text[], 'Clean and relaxed at 120 bpm eighth notes.', null, 'ex-sync-spider', true) on conflict (id) do update set name = excluded.name, score = excluded.score, instructions = excluded.instructions;
