t":2}]},{"duration":16,"notes":[{"string":1,"fret":4}]}]}]}'::jsonb, array['Fingers 1-3-2-4 on frets 1-3-2-4 of each string.', 'Strict alternate picking; aim for pick and finger to land at the same instant.']::text[], array['Collapsing finger 4.', 'Sloppy string changes.']::text[], 'Clean sixteenths at 110 bpm.', 'ex-chromatic-1234', 'ex-sync-burst', true) on conflict (id) do update set name = excluded.name, score = excluded.score, instructions = excluded.instructions;
